    // The bushfire:  -executeMethod BulldozerBuilder.FireTest   A line of fire high on the hillside, the wind blowing
    // it down towards the mine, a firebreak strip past the fence that holds until the wind changes and strengthens.
    // Pictures as it burns.  Prints BULLDOZER_FIRE_RESULT.
    static int frPhase, frShot, frFrames;
    static float frRealStart, frMaxMs, frSumMs;
    static string frLog;
    static bool frClose;
    static readonly float[] FrShots = { 12f, 30f, 50f, 70f, 90f, 120f, 150f };
    const float FrBreakZ0 = 54f, FrBreakZ1 = 60f, FrChange = 60f;

    public static void FireTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        frPhase = 0; frShot = 0; frLog = ""; frClose = false; frFrames = 0; frMaxMs = 0f; frSumMs = 0f;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += FireTick;
        EditorApplication.EnterPlaymode();
    }

    static void FireFinish(int code)
    {
        EditorApplication.update -= FireTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    static int FrBurntBelow(float z)
    {
        int n = 0;
        for (float x = -100f; x < 100f; x += 2f) for (float zz = 49f; zz < z; zz += 2f) if (FireSim.Instance.CellBurnt(new Vector3(x, 0f, zz))) n++;
        return n;
    }

    static void FireTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 400) { Debug.LogError("BULLDOZER_FIRE_FAILED timed out in phase " + frPhase + " " + frLog); FireFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var fire = FireSim.Instance; var wk = Worker.Instance;
        if (fire == null || wk == null || Camera.main == null || FireSim.Trees.Count == 0) return;
        if (frPhase == 0)
        {
            if (Time.time < 2f) return;
            wk.useOverride = true;
            var follow = Camera.main.GetComponent<FollowCamera>(); if (follow != null) follow.enabled = false;
            fire.SetWind(new Vector2(0.6f, -5f), new Vector2(2.5f, -11f), FrChange);
            fire.ClearFuel(-110f, FrBreakZ0, 110f, FrBreakZ1);
            fire.speedUp = 3f;
            fire.Begin();
            fire.Ignite(new Vector3(-100f, 0f, 160f), new Vector3(100f, 0f, 160f));
            frLog += "trees=" + FireSim.Trees.Count;
            frPhase = 1; frRealStart = Time.realtimeSinceStartup;
            return;
        }
        float ms = Time.unscaledDeltaTime * 1000f;
        frFrames++; frSumMs += ms; if (frFrames > 10) frMaxMs = Mathf.Max(frMaxMs, ms);
        float t = fire.Now;
        if (frPhase == 1 && t > FrChange - 0.5f)
        {
            frLog += " beforeChange:cells=" + fire.CellsBurnt + " trees=" + fire.TreesBurnt + " crossedBreak=" + FrBurntBelow(FrBreakZ0);
            frPhase = 2;
        }
        if (!frClose && t >= 56f)
        {
            // close, on the track past the fence, as the front comes down through the trees
            frClose = true;
            Vector3 at = new Vector3(VoxelWorld.TrackCentreX(52f) - 1f, SiteProps.HillY(VoxelWorld.TrackCentreX(52f), 52f) + 2.4f, 52f);
            Vector3 look = new Vector3(VoxelWorld.TrackCentreX(72f), SiteProps.HillY(VoxelWorld.TrackCentreX(72f), 72f) + 7f, 72f);
            Camera.main.transform.SetPositionAndRotation(at, Quaternion.LookRotation(look - at));
            TestCapture("fire_close.png");
            return;
        }
        if (frShot < FrShots.Length && t >= FrShots[frShot])
        {
            var cam = Camera.main;
            // wide, from high over the quarry, looking up the hill; and the last two from inside the forest
            if (frShot < 4) cam.transform.SetPositionAndRotation(new Vector3(-14f, 26f, -26f), Quaternion.LookRotation(new Vector3(VoxelWorld.TrackX + 6f, 12f, 90f) - new Vector3(-14f, 26f, -26f)));
            else if (frShot == 6)
            {
                Vector3 at = new Vector3(VoxelWorld.TrackX - 16f, 16f, 22f), look = new Vector3(VoxelWorld.TrackX + 2f, 4f, 52f);   // over the burnt hilltop
                cam.transform.SetPositionAndRotation(at, Quaternion.LookRotation(look - at));
            }
            else
            {
                Vector3 at = new Vector3(VoxelWorld.TrackCentreX(36f) - 1f, 5.9f, 36f), look = new Vector3(VoxelWorld.TrackCentreX(70f), 12f, 70f);
                cam.transform.SetPositionAndRotation(at, Quaternion.LookRotation(look - at));
            }
            TestCapture("fire_" + frShot + "_" + Mathf.RoundToInt(FrShots[frShot]) + "s.png");
            frShot++;
            return;
        }
        if (frShot < FrShots.Length) return;
        // a fallen trunk must be solid: the middle of the first one blocks a dozer
        string solid = "none";
        for (int ft = 0; ft < FireSim.Trees.Count; ft++)
            if (fire.HasFallen(ft))
            {
                var tr = FireSim.Trees[ft];
                Vector3 mid = tr.at + new Vector3(Mathf.Sin(fire.FallAngle(ft)), 0f, Mathf.Cos(fire.FallAngle(ft))) * tr.height * 0.5f;
                solid = SiteProps.Blocks(mid, 1f).ToString();
                break;
            }
        frLog += " fallen=" + fire.TreesFallen + " logs=" + SiteProps.FallenCount + " fallenIsSolid=" + solid;
        frLog += " end:cells=" + fire.CellsBurnt + " trees=" + fire.TreesBurnt + " crossedBreakAfterChange=" + FrBurntBelow(FrBreakZ0)
              + " reachedHilltop=" + fire.CellBurnt(new Vector3(-20f, 0f, 30f)) + " avgMs=" + (frSumMs / Mathf.Max(1, frFrames)).ToString("F1") + " worstMs=" + frMaxMs.ToString("F1");
        Debug.Log("BULLDOZER_FIRE_RESULT " + frLog);
        FireFinish(0);
    }

    // The hill behind the mine:  -executeMethod BulldozerBuilder.HillTest   Pictures, and the dozer driving up the ramp
    // onto the hilltop track.  Prints BULLDOZER_HILL_RESULT.
    static int hPhase;
    static float hT0, hMaxY, hMaxZ;
    static string hLog;
    static Camera hCam;

    public static void HillTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        hPhase = 0; hLog = ""; hMaxY = -9f; hMaxZ = -99f;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += HillTick;
        EditorApplication.EnterPlaymode();
    }

    static void HillFinish(int code)
    {
        EditorApplication.update -= HillTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    static void HillShot(Vector3 pos, Vector3 look, string file)
    {
        var cam = Camera.main;
        var follow = cam.GetComponent<FollowCamera>();
        if (follow != null) follow.enabled = false;
        cam.transform.SetPositionAndRotation(pos, Quaternion.LookRotation(look - pos));
        TestCapture(file);
    }

    static void HillTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_HILL_FAILED timed out in phase " + hPhase + " " + hLog); HillFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var w = VoxelWorld.Instance; var wk = Worker.Instance;
        if (d == null || w == null || wk == null || Camera.main == null) return;
        float t = Time.time;
        float tx = VoxelWorld.TrackX;
        if (hPhase == 0)
        {
            if (t < 2f) return;
            hLog += "gums=" + SiteProps.TrackGumCount + "/" + SiteProps.HillGumCount + "/" + SiteProps.FarGumCount + " rampFoot=" + w.HeightAt(tx, VoxelWorld.TrackZ0).ToString("F2") + " rampTop=" + w.HeightAt(VoxelWorld.TrackCentreX(22f), 22f).ToString("F2")
                  + " hilltopTrack=" + w.HeightAt(VoxelWorld.TrackCentreX(40f), 40f).ToString("F2") + " pastFence=" + SiteProps.HillY(VoxelWorld.TrackCentreX(80f), 80f).ToString("F1");
            // 1. from the quarry floor, looking up the ramp and the hill behind the mine
            HillShot(new Vector3(tx - 4f, 2.2f, -8f), new Vector3(tx + 1f, 4f, 22f), "hill_from_floor.png");
            hPhase = 1; hT0 = t;
            return;
        }
        if (hPhase == 1)
        {
            if (t - hT0 < 0.5f) return;
            // 2. high, from the quarry, the whole hillside
            HillShot(new Vector3(-10f, 22f, -30f), new Vector3(tx, 8f, 45f), "hill_wide.png");
            // 3. on the hilltop track, looking up into the forest
            HillShot(new Vector3(VoxelWorld.TrackCentreX(30f), 6.6f, 30f), new Vector3(VoxelWorld.TrackCentreX(70f), 14f, 70f), "hill_track.png");
            Camera.main.GetComponent<FollowCamera>().enabled = true;
            // the dozer at the foot of the ramp, facing up it, driven
            wk.useOverride = true;
            d.dead = false;
            if (!wk.InDozer) wk.GetIn();
            d.useOverride = true;
            Vector3 start = new Vector3(VoxelWorld.TrackCentreX(1f), 0.2f, 1f);
            hLog += " startBlocked=" + SiteProps.Blocks(start, 2.3f) + " rampBlocked=" + SiteProps.Blocks(new Vector3(VoxelWorld.TrackCentreX(12f), 2f, 12f), 2.3f)
                  + " shedFront=" + SiteProps.GoldShedFront.ToString("F1") + " dozerWas=" + d.transform.position.ToString("F1");
            d.Place(start, 0f);                                     // (moving the transform alone left the machine's own height and heading behind)
            hPhase = 2; hT0 = t;
            return;
        }
        if (hPhase == 2)
        {
            float k = t - hT0;
            d.overrideBlade = 1f; d.overrideRipper = 1f;
            d.overrideThrottle = k < 1f ? 0f : 1f;
            // keep it on the track
            float want = VoxelWorld.TrackCentreX(d.transform.position.z + 3f) - d.transform.position.x;
            d.overrideSteer = Mathf.Clamp(want * 0.6f, -1f, 1f);
            hMaxY = Mathf.Max(hMaxY, d.transform.position.y); hMaxZ = Mathf.Max(hMaxZ, d.transform.position.z);
            if (k > 6f && hLog.IndexOf("climbPic") < 0) { TestCapture("hill_dozer_climb.png"); hLog += " climbPic"; }
            if (d.BlockedByRock && hLog.IndexOf("firstRock") < 0)
            {
                hLog += " firstRock=" + d.transform.position.ToString("F1") + " blade01=" + d.BladeHeight01.ToString("F2") + " edge=" + d.EdgeAboveTracks.ToString("F2");
            }
            if (k > 3f && hLog.IndexOf("at3s") < 0) hLog += " at3s=" + d.transform.position.ToString("F1") + " speed=" + d.Speed.ToString("F2") + " driven=" + d.driven;
            if (k < 16f) return;
            d.overrideThrottle = 0f;
            hLog += " dozerReachedZ=" + hMaxZ.ToString("F1") + " dozerMaxY=" + hMaxY.ToString("F2") + " onHilltop=" + (hMaxY > 3.5f) + " atCliff=" + d.AtCliff + " glancedOffRock=" + d.Glanced;
            bool up = hMaxY > 3.5f;
            if (up) Debug.Log("BULLDOZER_HILL_RESULT " + hLog); else Debug.LogError("BULLDOZER_HILL_FAILED (never reached the hilltop) " + hLog);
            HillFinish(up ? 0 : 1);
        }
    }

    // Blade auto:  -executeMethod BulldozerBuilder.BladeAutoTest      Prints BULLDOZER_BLADEAUTO_RESULT.
    // On the site floor, puts two low ridges across the way, then with blade auto on Flat drives 10 m: the ground left
    // behind must be level (within about 3 cm of the start).  A touch on the blade lever must switch auto off.  Then
    // back to the start and a second pass on Cut 10 cm: the floor it leaves must be about 10 cm lower.
    // Picture: Logs/blade_auto_flat.png.
    static int baPhase; static float baT0; static string baLog; static bool baFail;
    static Vector3 baP0, baFwd, baRight; static float baYaw, baBladeFrom, baBladeTo, baBefore;

    public static void BladeAutoTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        baPhase = 0; baLog = ""; baFail = false;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += BladeAutoTick;
        EditorApplication.EnterPlaymode();
    }

    static void BladeAutoFinish(int code)
    {
        EditorApplication.update -= BladeAutoTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    // how far along the drive line (from the start, in metres) the middle of the blade's edge is
    static float BaBladeAlong(DozerController d)
    {
        Vector3 e = d.Blade.TransformPoint(new Vector3(0f, -0.75f, 1.125f));
        return Vector3.Dot(e - baP0, baFwd);
    }

    // ground heights over the stretch the blade worked, across the middle 3 m of its width
    static System.Collections.Generic.List<float> BaSamples(VoxelWorld w, float from, float to)
    {
        var list = new System.Collections.Generic.List<float>();
        for (float a = from; a <= to; a += 0.25f)
            for (float s = -1.5f; s <= 1.51f; s += 0.5f)
            {
                Vector3 p = baP0 + baFwd * a + baRight * s;
                list.Add(w.HeightAt(p.x, p.z));
            }
        return list;
    }

    static float baNextTrace;
    // every half second while driving: how far along the blade is, its edge against the start ground, and the machine's tip
    static void BaTrace(DozerController d, VoxelWorld w, float t)
    {
        if (t < baNextTrace) return;
        baNextTrace = t + 0.5f;
        Vector3 e = d.Blade.TransformPoint(new Vector3(0f, -0.75f, 1.125f));
        baLog += " [" + BaBladeAlong(d).ToString("F1") + " edge" + (e.y - baBefore).ToString("F3") + " ground" + (w.HeightAt(e.x, e.z) - baBefore).ToString("F3")
               + " machine" + (d.transform.position.y - baBefore).ToString("F3") + " pitch" + d.transform.eulerAngles.x.ToString("F1") + " v" + d.Speed.ToString("F1")
               + " " + System.Text.RegularExpressions.Regex.Match(d.BladeLoadInfo(), @"clods\S+").Value + " ripped=" + w.TotalRipped + " cut=" + w.TotalCut + "]";
    }

    static float BaMean(System.Collections.Generic.List<float> l) { float sum = 0f; foreach (var h in l) sum += h; return l.Count > 0 ? sum / l.Count : 0f; }

    static void BladeAutoTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 600) { Debug.LogError("BULLDOZER_BLADEAUTO_FAILED timed out at " + Time.time.ToString("F0") + "s in phase " + baPhase + " " + baLog); BladeAutoFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var w = VoxelWorld.Instance; var wk = Worker.Instance;
        if (d == null || w == null || wk == null || Camera.main == null || d.Blade == null) return;
        float t = Time.time;
        if (baPhase == 0)
        {
            if (t < 2f) return;
            wk.useOverride = true;
            d.dead = false;
            if (!wk.InDozer) wk.GetIn();
            d.useOverride = true;
            d.overrideThrottle = d.overrideSteer = d.overrideBlade = d.overrideRipper = d.overrideAngle = d.overrideTilt = 0f;
            baP0 = d.transform.position; baYaw = d.transform.eulerAngles.y;
            baFwd = Quaternion.Euler(0f, baYaw, 0f) * Vector3.forward; baRight = Quaternion.Euler(0f, baYaw, 0f) * Vector3.right;
            baLog += "start=" + baP0.ToString("F1") + " yaw=" + baYaw.ToString("F0")
                   + " angles(flat/5/10/down)=" + d.AutoAngle(DozerController.BladeAutoMode.Flat).ToString("F2") + "/" + d.AutoAngle(DozerController.BladeAutoMode.Cut5).ToString("F2")
                   + "/" + d.AutoAngle(DozerController.BladeAutoMode.Cut10).ToString("F2") + "/" + d.bladeDownAngle.ToString("F0") + "deg bladeDownDepth=" + d.BladeDownDepth.ToString("F3");
            var before = BaSamples(w, 2f, 14f);
            float lo = 99f, hi = -99f; foreach (var h in before) { lo = Mathf.Min(lo, h); hi = Mathf.Max(hi, h); }
            baBefore = BaMean(before);
            int w0 = 0; foreach (var h in before) if (Mathf.Abs(h - baBefore) <= 0.035f) w0++;
            baLog += " groundBefore mean=" + baBefore.ToString("F3") + " range=" + (hi - lo).ToString("F3") + " within3cm=" + (100f * w0 / Mathf.Max(1, before.Count)).ToString("F0") + "%";
            // two ridges 12.5 cm high and half a metre wide across the way, 3 m wide
            int raised = 0; var done = new System.Collections.Generic.HashSet<long>();
            foreach (float along in new[] { 7f, 9.5f })
                for (float a = along; a < along + 0.5f; a += VoxelWorld.Voxel)
                    for (float s = -1.5f; s <= 1.5f; s += VoxelWorld.Voxel)
                    {
                        Vector3 p = baP0 + baFwd * a + baRight * s;
                        long key = Mathf.FloorToInt(p.x / VoxelWorld.Voxel) * 100000L + Mathf.FloorToInt(p.z / VoxelWorld.Voxel);
                        if (done.Add(key) && w.TestSetColumn(p.x, p.z, w.TopAt(p.x, p.z) + 0.125f)) raised++;
                    }
            baLog += " ridgeColumns=" + raised;
            // leaning 10 degrees either way, auto level brings the cutting edge level (it was 4.5 m x sin 10 = 78 cm out)
            float gapR = d.TestLevelGap(10f); baLog += " tiltR=" + DozerController.TestLevelTilt.ToString("F1") + " rawR=" + DozerController.TestLevelRaw.ToString("F3"); float gapL = d.TestLevelGap(-10f);
            bool levelOk = Mathf.Abs(gapR) < 0.03f && Mathf.Abs(gapL) < 0.03f;
            bool deepOk = d.BladeDownDepth > 0.85f;
            baLog += " levelGap(+10/-10)=" + gapR.ToString("F3") + "/" + gapL.ToString("F3") + " levelOk=" + levelOk + " deepOk=" + deepOk;
            if (!levelOk || !deepOk) baFail = true;
            // the cycle: Off -> Flat
            d.bladeAuto = DozerController.BladeAutoMode.Off;
            DozerController.LastAuto = DozerController.BladeAutoMode.Flat;
            d.CycleBladeAuto();
            baLog += " cycledTo=" + d.BladeAutoName;
            baPhase = 1; baT0 = t;
            return;
        }
        if (baPhase == 1)
        {
            // let the blade find its height, then drive 10 m
            if (t - baT0 < 1.5f) return;
            if (baLog.IndexOf("bladeFrom") < 0) { baBladeFrom = BaBladeAlong(d); baLog += " bladeFrom=" + baBladeFrom.ToString("F2") + " armAngle=" + d.BladeArmAngle.ToString("F2"); }
            d.overrideThrottle = 1f;
            BaTrace(d, w, t);
            if (Vector3.Dot(d.transform.position - baP0, baFwd) < 10f && t - baT0 < 15f) return;
            d.overrideThrottle = 0f;
            baBladeTo = BaBladeAlong(d);
            baLog += " flatAuto=" + d.BladeAutoName + " drove=" + Vector3.Dot(d.transform.position - baP0, baFwd).ToString("F1") + " bladeTo=" + baBladeTo.ToString("F2");
            baPhase = 2; baT0 = t;
            return;
        }
        if (baPhase == 2)
        {
            // stopped.  A touch on the blade lever (blade up) switches auto off; then lift clear and let the dirt settle.
            if (t - baT0 < 0.5f) return;
            d.overrideBlade = 1f;
            if (t - baT0 < 0.6f) return;
            if (baLog.IndexOf("afterPress") < 0)
            {
                bool off = d.AutoPaused && !d.HeightAutoActive && d.bladeAuto == DozerController.BladeAutoMode.Flat;
                baLog += " afterPress=" + d.BladeAutoName + (d.AutoPaused ? " paused" : ""); if (!off) baFail = true;
                // the lever only paused the height: one press carries on at the same height, the next turns auto off,
                // the next back on at that height
                d.CycleBladeAuto(); string back = d.BladeAutoName; bool resumed = !d.AutoPaused;
                d.CycleBladeAuto(); string next = d.BladeAutoName;
                d.CycleBladeAuto(); string again = d.BladeAutoName;
                d.CycleBladeAuto(); string third = d.BladeAutoName;
                bool resumeOk = back == "Flat" && resumed && next == "Grade (the pegs)" && again == "Off" && third == "Flat";
                baLog += " resume=" + back + " next=" + next + " then=" + again + " then=" + third + " resumeOk=" + resumeOk; if (!resumeOk) baFail = true;
                // with auto on, the lever steps the height it holds, 5 cm a step, from fully down to fully up
                d.StepAutoHeight(-1); string down1 = d.BladeAutoName;
                d.StepAutoHeight(1); d.StepAutoHeight(1); d.StepAutoHeight(1); string up2 = d.BladeAutoName;
                for (int i = 0; i < 40; i++) d.StepAutoHeight(-1);
                string bottom = d.BladeAutoName;
                for (int i = 0; i < 60; i++) d.StepAutoHeight(1);
                string top = d.BladeAutoName;
                bool anglesOk = d.AutoAngleCm(-d.MaxCutCm) > d.AutoAngleCm(0) && d.AutoAngleCm(d.MaxFillCm) < d.AutoAngleCm(20) && d.AutoAngleCm(20) < d.AutoAngleCm(0)
                                && Mathf.Abs(d.AutoAngleCm(-d.MaxCutCm) - d.bladeDownAngle) < 1f;
                bool stepsOk = down1 == "Cut 5 cm" && up2 == "Fill 10 cm" && bottom == "Cut " + d.MaxCutCm + " cm" && d.MaxCutCm >= 85 && top == "Fill " + d.MaxFillCm + " cm" && d.MaxFillCm >= 50 && anglesOk;
                baLog += " steps: " + down1 + " / " + up2 + " / bottom " + bottom + " / top " + top + " anglesOk=" + anglesOk + " stepsOk=" + stepsOk; if (!stepsOk) baFail = true;
                d.bladeAuto = DozerController.BladeAutoMode.Off;
                DozerController.LastAuto = DozerController.BladeAutoMode.Flat;
            }
            if (t - baT0 < 3f) return;
            d.overrideBlade = 0f;
            var after = BaSamples(w, baBladeFrom + 0.5f, baBladeTo - 2f);
            float mean = BaMean(after), worst = 0f; int within = 0;
            foreach (var h in after) { float dv = Mathf.Abs(h - baBefore); worst = Mathf.Max(worst, dv); if (dv <= 0.035f) within++; }
            float frac = within / (float)Mathf.Max(1, after.Count);
            // each metre along, the ground across the strip on average (a thin spread of loose clods is rough close up)
            baLog += " rows:"; float worstRow = 0f;
            for (float a = Mathf.Ceil(baBladeFrom + 0.5f); a + 0.75f <= baBladeTo - 2f; a += 1f)
            {
                float r = BaMean(BaSamples(w, a, a + 0.75f)) - baBefore;
                worstRow = Mathf.Max(worstRow, Mathf.Abs(r));
                baLog += " " + a.ToString("F0") + "=" + r.ToString("F3");
            }
            bool level = Mathf.Abs(mean - baBefore) <= 0.03f && worstRow <= 0.035f;
            if (!level) baFail = true;
            baLog += " FLAT: samples=" + after.Count + " meanChange=" + (mean - baBefore).ToString("F3") + " within3cm=" + (frac * 100f).ToString("F0") + "% worst=" + worst.ToString("F3") + " level=" + level;
            // picture: from behind and to one side, looking along the levelled strip
            Vector3 mid = baP0 + baFwd * ((baBladeFrom + baBladeTo) * 0.5f);
            HillShot(baP0 - baFwd * 3f + baRight * 6f + Vector3.up * 3.5f, mid + Vector3.up * 0.2f, "blade_auto_flat.png");
            Camera.main.GetComponent<FollowCamera>().enabled = true;
            // back to the start for the cut pass
            d.Place(baP0, baYaw);
            baPhase = 3; baT0 = t;
            return;
        }
        if (baPhase == 3)
        {
            if (t - baT0 < 1f) return;
            var before = BaSamples(w, baBladeFrom + 0.5f, baBladeTo - 2f);
            baBefore = BaMean(before);
            d.bladeAuto = DozerController.BladeAutoMode.Cut10;
            baPhase = 4; baT0 = t;
            return;
        }
        if (baPhase == 4)
        {
            if (t - baT0 < 1.5f) return;
            d.overrideThrottle = 1f;
            BaTrace(d, w, t);
            if (Vector3.Dot(d.transform.position - baP0, baFwd) < 10f && t - baT0 < 17f) return;
            d.overrideThrottle = 0f;
            baLog += " cutAuto=" + d.BladeAutoName + " drove=" + Vector3.Dot(d.transform.position - baP0, baFwd).ToString("F1");
            float to = BaBladeAlong(d);
            d.bladeAuto = DozerController.BladeAutoMode.Off;
            d.overrideBlade = 1f;
            baBladeTo = Mathf.Min(baBladeTo, to);
            baPhase = 5; baT0 = t;
            return;
        }
        if (baPhase == 5)
        {
            if (t - baT0 < 2.5f) return;
            d.overrideBlade = 0f;
            // where the machine's own tracks started is still on the old ground, so look from a metre past where the
            // blade started this pass, to two metres short of where it stopped
            var after = BaSamples(w, baBladeFrom + 1f, baBladeTo - 2f);
            float mean = BaMean(after);
            float drop = baBefore - mean;
            bool ok = drop >= 0.06f && drop <= 0.14f;
            if (!ok) baFail = true;
            float lo2 = 99f, hi2 = -99f;
            for (float a = baBladeFrom + 1f; a + 0.75f <= baBladeTo - 2f; a += 1f) { float r = baBefore - BaMean(BaSamples(w, a, a + 0.75f)); lo2 = Mathf.Min(lo2, r); hi2 = Mathf.Max(hi2, r); }
            baLog += " CUT10: floorDrop=" + drop.ToString("F3") + " rowDrops=" + lo2.ToString("F3") + ".." + hi2.ToString("F3") + " ok=" + ok;
            HillShot(baP0 - baFwd * 3f + baRight * 6f + Vector3.up * 3.5f, baP0 + baFwd * 8f, "blade_auto_cut10.png");
            Debug.Log("BULLDOZER_BLADEAUTO_RESULT " + (baFail ? "FAIL " : "PASS ") + baLog);
            BladeAutoFinish(baFail ? 1 : 0);
        }
    }

    // The mountain road:  -executeMethod BulldozerBuilder.MountainRoadTest      Prints BULLDOZER_ROAD_RESULT.
    // Checks the road strip is there and can be dug, the dozer can drive from the site up onto it, the pegs' and the
    // tint's CUT / FILL match the ground, grading one stretch ticks it (and only it), and grading them all pays.
    // Measures the memory the ground takes and the frame time on the road.  Pictures in Logs/road_*.png.
    static long mrCut0; static string mrPushLog = ""; const float MrPushS = 2f;
    static int mrPhase, mrSide, mrEdgeOut, mrEdgeFrames; static long mrSpill0;
    static float mrT0, mrMaxS, mrMaxY, mrFrameSum, mrFrameMax;
    static int mrFrames, mrUpCut, mrCliff, mrFence, mrOnStrip;
    static string mrLog;
    static long mrCoins0;
    static bool mrFail;

    public static void MountainRoadTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        mrPhase = 0; mrLog = ""; rcLog = ""; mrMaxS = 0f; mrMaxY = -9f; mrFrames = 0; mrFrameSum = 0f; mrFrameMax = 0f; mrCliff = mrFence = mrOnStrip = mrUpCut = 0; mrFail = false;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += RoadTick;
        EditorApplication.EnterPlaymode();
    }

    static void RoadFinish(int code)
    {
        EditorApplication.update -= RoadTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    static void RoadCheck(bool ok, string what) { mrLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) mrFail = true; }

    // A step between two stretches of the road that pass close to each other (a hairpin: the next leg up runs a few
    // metres away and several metres higher) is the bank between them, not a fault in the ground.
    static bool StepAtHairpin(Vector2 at)
    {
        float sN, oN; Vector2 dN, dir; MountainRoad.Nearest(at.x, at.y, out sN, out oN, out dN);
        for (float s2 = 0f; s2 < MountainRoad.Length; s2 += 0.5f)
            if (Mathf.Abs(s2 - sN) > 12f && Vector2.Distance(RoadPoint(s2, 0f, out dir), at) < MountainRoad.StripHalf + 2.5f
                && Mathf.Abs(MountainRoad.GradeAt(s2) - MountainRoad.GradeAt(sN)) > 2f) return true;
        return false;
    }

    static Vector2 RoadPoint(float s, float off, out Vector2 dir)
    {
        int n = MountainRoad.Count;
        int i = Mathf.Clamp(Mathf.FloorToInt(s / MountainRoad.Step), 0, n - 2);
        float u = Mathf.Clamp01((s - MountainRoad.AlongAt(i)) / MountainRoad.Step);
        Vector2 a = MountainRoad.Point(i), b = MountainRoad.Point(i + 1);
        dir = (b - a).normalized;
        return Vector2.Lerp(a, b, u) + new Vector2(-dir.y, dir.x) * off;
    }

    static void RoadTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 600) { Debug.LogError("BULLDOZER_ROAD_FAILED timed out in phase " + mrPhase + " " + mrLog); RoadFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var job = MountainRoadJob.Instance;
        if (d == null || w == null || wk == null || job == null || Camera.main == null || Money.Instance == null) return;
        float t = Time.time;
        Vector2 dir;
        if (mrPhase == 0)
        {
            if (t < 2f) return;
            // ---- the strip, and the memory it takes
            float mb = 1f / (1024f * 1024f);
            long oldGround = 1536L * 224 * 1536 + 1536L * 1536 * 2 + 1536L * 1536 * 2 + 48L * 7 * 48;   // before: voxels, heights, grass (array + picture), chunk flags
            mrLog += "length=" + MountainRoad.Length.ToString("F1") + "m start=" + MountainRoad.StartY.ToString("F2") + " top=" + MountainRoad.TopY.ToString("F2")
                   + " stripBlocks=" + w.StripBlocks + " stripVoxelsMB=" + (w.StripVoxels * mb).ToString("F1") + " allVoxelsMB=" + (w.VoxelBytes * mb).ToString("F1")
                   + " groundMB=" + (w.GridBytes * mb).ToString("F1") + " groundBeforeMB=" + (oldGround * mb).ToString("F1")
                   + " unityAllocatedMB=" + (UnityEngine.Profiling.Profiler.GetTotalAllocatedMemoryLong() * mb).ToString("F0")
                   + " groundBuildMs=" + w.BuildMs.ToString("F0") + " (road line " + MountainRoad.BuildMs.ToString("F0") + ", blocks " + w.BlocksMs.ToString("F0") + ", voxels " + w.GenerateMs.ToString("F0") + ", the rest drawing)"
                   + " roadGuidesSetupMs=" + job.SetupMs.ToString("F0")
                   + " hillsideHoles=" + SiteProps.HillsideHoles + " walls=" + SiteProps.HillsideWalls + " roadSquares=" + job.SquareCount + " pegs=" + job.PegCount;
            // every point of the road and the strip has voxels under it
            int missing = 0, roadPts = 0;
            float worst = 0f, sumAbs = 0f, cutShare = 0f, fillShare = 0f; int nCF = 0; string worstAt = "";
            for (float s = 0f; s <= MountainRoad.Length; s += 1f)
                for (float off = -MountainRoad.StripHalf + 0.2f; off <= MountainRoad.StripHalf - 0.19f; off += 0.95f)
                {
                    Vector2 p = RoadPoint(s, off, out dir);
                    roadPts++;
                    if (w.KindAt(p.x, p.y) == 0) { missing++; continue; }
                    if (Mathf.Abs(off) > MountainRoad.RoadHalf) continue;
                    float cf = w.TopAt(p.x, p.y) - MountainRoad.GradeAt(s);
                    if (Mathf.Abs(cf) > worst) worstAt = "s" + s.ToString("F0") + "/off" + off.ToString("F1");
                    worst = Mathf.Max(worst, Mathf.Abs(cf)); sumAbs += Mathf.Abs(cf); nCF++;
                    if (cf > MountainRoadJob.OnGrade) cutShare++; else if (cf < -MountainRoadJob.OnGrade) fillShare++;
                }
            mrLog += " stripPoints=" + roadPts + " withoutVoxels=" + missing
                   + " startCutFill: worst=" + worst.ToString("F2") + "m at " + worstAt + " mean=" + (sumAbs / Mathf.Max(1, nCF)).ToString("F2") + "m cut=" + (cutShare / Mathf.Max(1, nCF) * 100f).ToString("F0") + "% fill=" + (fillShare / Mathf.Max(1, nCF) * 100f).ToString("F0") + "%";
            // how much cut and fill each stretch starts with (on the road: + cut, - fill)
            string per = "";
            for (int k = 0; k < MountainRoad.Stretches; k++)
            {
                float s0 = k * MountainRoad.Length / MountainRoad.Stretches, s1 = (k + 1) * MountainRoad.Length / MountainRoad.Stretches, lo = 99f, hi = -99f, sum = 0f; int n = 0;
                for (float s = s0; s < s1; s += 0.5f)
                    for (float off = -1.9f; off <= 1.91f; off += 0.95f)
                    {
                        Vector2 p = RoadPoint(s, off, out dir);
                        float cf = w.TopAt(p.x, p.y) - MountainRoad.GradeAt(s);
                        lo = Mathf.Min(lo, cf); hi = Mathf.Max(hi, cf); sum += cf; n++;
                    }
                per += " " + (k + 1) + ":" + (sum / n).ToString("+0.0;-0.0") + "[" + lo.ToString("+0.0;-0.0") + "," + hi.ToString("+0.0;-0.0") + "]";
            }
            mrLog += " perStretch(mean[min,max])" + per;
            // the start of the road, metre by metre on its centre line (+ cut, - fill): the hump (22 Nov 2026)
            string prof = "";
            for (float s = 0f; s <= 30f; s += 1f) { Vector2 p = RoadPoint(s, 0f, out dir); prof += " " + (w.TopAt(p.x, p.y) - MountainRoad.GradeAt(s)).ToString("+0.0;-0.0"); }
            mrLog += " startProfile(0..30m)" + prof;
            // no sudden steps in the starting ground: the biggest rise between neighbouring points 0.25 m apart on a square
            // grid over the strip (and where the strip meets the mountain's mesh)
            float maxStep = 0f; Vector2 stepAt = Vector2.zero;
            for (float z = MountainRoad.Min.y - 5f; z < MountainRoad.Max.y + 5f; z += 0.25f)
                for (float x = MountainRoad.Min.x - 5f; x < MountainRoad.Max.x + 5f; x += 0.25f)
                {
                    if (w.KindAt(x, z) != VoxelWorld.BlockStrip) continue;
                    float h0 = w.TopAt(x, z), st = Mathf.Max(Mathf.Abs(w.TopAt(x + 0.25f, z) - h0), Mathf.Abs(w.TopAt(x, z + 0.25f) - h0));
                    if (st > maxStep) { maxStep = st; stepAt = new Vector2(x, z); }
                }
            mrLog += " biggestStep=" + maxStep.ToString("F2") + "m at " + stepAt.ToString("F1");
            {
                // is another stretch of the road close by (a hairpin), and how high is it?
                float sN, oN; Vector2 dN; MountainRoad.Nearest(stepAt.x, stepAt.y, out sN, out oN, out dN);
                float best = 99f, bestS = -1f;
                for (float s2 = 0f; s2 < MountainRoad.Length; s2 += 0.5f)
                {
                    if (Mathf.Abs(s2 - sN) < 12f) continue;
                    float dd2 = Vector2.Distance(RoadPoint(s2, 0f, out dir), stepAt);
                    if (dd2 < best) { best = dd2; bestS = s2; }
                }
                mrLog += " (road here at s=" + sN.ToString("F0") + " grade " + MountainRoad.GradeAt(sN).ToString("F2") + "; other road " + best.ToString("F1") + "m away at s=" + bestS.ToString("F0") + " grade " + MountainRoad.GradeAt(bestS).ToString("F2") + ")";
            }
            if (maxStep >= 0.45f)
                for (float dz = -0.25f; dz <= 0.26f; dz += 0.25f)
                {
                    mrLog += " |   z+" + dz.ToString("F2") + ":";
                    for (float dx = -0.25f; dx <= 0.51f; dx += 0.25f)
                    {
                        float x = stepAt.x + dx, z = stepAt.y + dz, ss, so, clo, chi; Vector2 sd;
                        float dd = MountainRoad.Nearest(x, z, out ss, out so, out sd);
                        w.ColumnRange(x, z, out clo, out chi);
                        mrLog += " [" + w.TopAt(x, z).ToString("F2") + " k" + w.KindAt(x, z) + " win" + clo.ToString("F1") + "-" + chi.ToString("F1") + " raw" + Mountain.OutsideY(x, z).ToString("F2")
                               + " sh" + MountainRoad.ShapeDelta(x, z).ToString("F2") + " d" + dd.ToString("F1") + " s" + ss.ToString("F0") + "]";
                    }
                }
            // how much dirt each stretch makes: the cut and the fill on the 4 m road, in cubic metres
            string vol = ""; float cutAll = 0f, fillAll = 0f;
            for (int k = 0; k < MountainRoad.Stretches; k++)
            {
                float s0 = k * MountainRoad.Length / MountainRoad.Stretches, s1 = (k + 1) * MountainRoad.Length / MountainRoad.Stretches, vc = 0f, vf = 0f;
                for (float s = s0 + 0.125f; s < s1; s += 0.25f)
                    for (float off = -MountainRoad.RoadHalf + 0.125f; off < MountainRoad.RoadHalf; off += 0.25f)
                    {
                        Vector2 p = RoadPoint(s, off, out dir);
                        float cf = w.TopAt(p.x, p.y) - MountainRoad.GradeAt(s);
                        if (cf > 0f) vc += cf * 0.0625f; else vf -= cf * 0.0625f;
                    }
                vol += " " + (k + 1) + ":" + vc.ToString("F0") + "/" + vf.ToString("F0");
                cutAll += vc; fillAll += vf;
            }
            mrLog += " dirtPerStretch(cut/fill m3)" + vol + " total cut=" + cutAll.ToString("F0") + " fill=" + fillAll.ToString("F0");
            RoadCheck(worst <= MountainRoad.MaxStart + 0.1f, "startCutFillUnderMax");
            RoadCheck(maxStep < 0.45f || mrLog.Contains("other road ") && StepAtHairpin(stepAt), "noSuddenSteps");
            RoadCheck(missing == 0, "stripCovered");
            RoadCheck(Mathf.Abs(MountainRoad.TopY - MountainRoad.StartY - 20f) < 0.01f && MountainRoad.Length > 150f && MountainRoad.Length < 185f, "climbs20m");
            // it can be dug: firm diggable ground under the road, and the pick takes it out
            Vector2 q = RoadPoint(80f, 0f, out dir);
            float gy = w.TopAt(q.x, q.y);
            byte under = w.VoxelAtPoint(new Vector3(q.x, gy - 0.3f, q.y)), deep = w.VoxelAtPoint(new Vector3(q.x, gy - 2.5f, q.y));
            long solid0 = w.CountSolid();
            int picked = w.Pick(new Vector3(q.x, gy - 0.1f, q.y), 0.35f, Vector3.zero);
            mrLog += " under=" + under + " deep=" + deep + " picked=" + picked + " countDrop=" + (solid0 - w.CountSolid());
            RoadCheck((under == VoxelWorld.Soil || under == VoxelWorld.Clay) && (deep == VoxelWorld.Soil || deep == VoxelWorld.Clay) && picked > 100 && solid0 - w.CountSolid() == picked, "diggable");
            int ticked0 = job.TickedCount;
            mrLog += " tickedAtStart=" + ticked0; for (int k = 0; k < MountainRoad.Stretches; k++) mrLog += (k == 0 ? " share%:" : ",") + (k + 1) + "=" + (job.StretchShare(k) * 100f).ToString("F0") + (job.Ticked(k) ? "T" : "");
            RoadCheck(ticked0 == 0, "noFreeTicks");
            // 1. the mountain from the quarry floor
            HillShot(new Vector3(8f, 26f, -14f), new Vector3(-30f, 14f, 80f), "road_mountain_from_site.png");
            HillShot(new Vector3(-10f, 40f, 20f), new Vector3(-32f, 12f, 75f), "road_from_above.png");
            mrPhase = 1; mrT0 = t;
            return;
        }
        if (mrPhase == 1)
        {
            if (t - mrT0 < 0.5f) return;
            // ---- the guides match the ground
            job.Refresh();
            int bad = 0, cuts = 0, fills = 0, onGrade = 0; float worstPeg = 0f;
            for (int i = 0; i < job.PegCount; i++)
            {
                Vector2 p = job.PegAt(i);
                float want = w.HeightAt(p.x, p.y) - MountainRoad.GradeAt(job.PegAlong(i));
                string txt = job.PegText(i);
                float shown = txt == "ON GRADE" ? 0f : float.Parse(txt.Substring(txt.IndexOf(' ') + 1), System.Globalization.CultureInfo.InvariantCulture) * (txt.StartsWith("CUT") ? 1f : -1f);
                if (txt.StartsWith("CUT")) cuts++; else if (txt.StartsWith("FILL")) fills++; else onGrade++;
                float err = txt == "ON GRADE" ? (Mathf.Abs(want) <= MountainRoadJob.OnGrade ? 0f : 1f) : Mathf.Abs(shown - want);
                worstPeg = Mathf.Max(worstPeg, err);
                if (err > 0.051f || (want > MountainRoadJob.OnGrade && !txt.StartsWith("CUT")) || (want < -MountainRoadJob.OnGrade && !txt.StartsWith("FILL"))) bad++;
            }
            int tintBad = 0, tintN = 0;
            for (float s = 1f; s < MountainRoad.Length; s += 2.3f)
                for (float off = -1.6f; off <= 1.61f; off += 0.8f)
                {
                    Vector2 p = RoadPoint(s, off, out dir);
                    int tc = job.TintAt(p.x, p.y);
                    if (tc == 99) continue;
                    // the square's own middle is what it was worked out from
                    float cx = Mathf.Floor((p.x - (MountainRoad.Min.x - 3f)) / 0.25f) * 0.25f + (MountainRoad.Min.x - 3f) + 0.125f;
                    float cz = Mathf.Floor((p.y - (MountainRoad.Min.y - 3f)) / 0.25f) * 0.25f + (MountainRoad.Min.y - 3f) + 0.125f;
                    float ss, so; Vector2 sd;
                    MountainRoad.Nearest(cx, cz, out ss, out so, out sd);
                    float cf = w.TopAt(cx, cz) - MountainRoad.GradeAt(ss);
                    int want = cf > MountainRoadJob.OnGrade ? 1 : cf < -MountainRoadJob.OnGrade ? -1 : 0;
                    tintN++; if (tc != want) tintBad++;
                }
            mrLog += " pegs: cut=" + cuts + " fill=" + fills + " onGrade=" + onGrade + " wrong=" + bad + " worstError=" + worstPeg.ToString("F3") + "m tintChecked=" + tintN + " tintWrong=" + tintBad;
            RoadCheck(bad == 0 && cuts > 0 && fills > 0, "pegsMatchGround");
            RoadCheck(tintBad == 0 && tintN > 100, "tintMatchesGround");
            // 2. the tint and the pegs, low down on the first leg, looking up the road
            Vector2 a = RoadPoint(22f, -6f, out dir), b = RoadPoint(40f, 0f, out dir);
            HillShot(new Vector3(a.x, w.HeightAt(a.x, a.y) + 4.5f, a.y), new Vector3(b.x, w.HeightAt(b.x, b.y), b.y), "road_tint_pegs.png");
            Vector2 c = RoadPoint(95f, 9f, out dir), e = RoadPoint(95f, 0f, out dir);
            HillShot(new Vector3(c.x, w.HeightAt(e.x, e.y) + 7f, c.y), new Vector3(e.x, w.HeightAt(e.x, e.y), e.y), "road_tint_pegs_2.png");
            Camera.main.GetComponent<FollowCamera>().enabled = true;
            // ---- the dozer: on the hilltop just short of the road's start, facing up it
            wk.useOverride = true;
            d.dead = false;
            if (!wk.InDozer) wk.GetIn();
            d.useOverride = true;
            Vector2 st = RoadPoint(0f, 0f, out dir);
            Vector2 back = st - dir * 4f;
            mrLog += " startInSite=" + (Mathf.Abs(back.x) <= VoxelWorld.DriveLimit && Mathf.Abs(back.y) <= VoxelWorld.DriveLimit) + " startBlocked=" + SiteProps.Blocks(new Vector3(back.x, 0f, back.y), 2.3f);
            int blockedAlong = 0;
            for (float s = 0f; s < MountainRoad.Length; s += 1f) { Vector2 p = RoadPoint(s, 0f, out dir); if (SiteProps.Blocks(new Vector3(p.x, 0f, p.y), 2.3f)) blockedAlong++; }
            mrLog += " solidThingsOnRoad=" + blockedAlong;
            var way = RcFindWay(new Vector2(VoxelWorld.TrackCentreX(27f), 27f), RoadPoint(3f, 0f, out dir));
            bool reach = rcLog.IndexOf("noClearWay") < 0;
            mrLog += " fromEscapeTrack=" + (reach ? "clear way, " + way.Count + " points" : "NO WAY");
            RoadCheck(reach, "reachableFromTrack");
            RoadPoint(0f, 0f, out dir);
            d.Place(new Vector3(back.x, 0f, back.y), Mathf.Atan2(dir.x, dir.y) * Mathf.Rad2Deg);
            mrPhase = 2; mrT0 = t;
            return;
        }
        if (mrPhase == 2)
        {
            // drive up the road, blade up, steering at a point 4 m further along
            float k = t - mrT0;
            Vector3 pos = d.transform.position;
            float s, off;
            float dist = MountainRoad.Nearest(pos.x, pos.z, out s, out off, out dir);
            Vector2 aim = RoadPoint(s + 4.5f, 0f, out dir);
            Vector3 to = new Vector3(aim.x - pos.x, 0f, aim.y - pos.z);
            float ang = Vector3.SignedAngle(Vector3.ProjectOnPlane(d.transform.forward, Vector3.up), to, Vector3.up);
            d.overrideSteer = Mathf.Clamp(ang / 25f, -1f, 1f);
            d.overrideThrottle = k < 0.5f ? 0f : Mathf.Abs(ang) > 50f ? 0.15f : 1f;
            d.overrideBlade = 1f; d.overrideRipper = 1f;
            if (k > 1f)
            {
                mrFrames++; mrFrameSum += Time.unscaledDeltaTime; mrFrameMax = Mathf.Max(mrFrameMax, Time.unscaledDeltaTime);
                if (d.AtCliff) mrCliff++;
                mrUpCut += d.LastCut;
                if (d.AtFence) mrFence++;
                if (w.KindAt(pos.x, pos.z) == VoxelWorld.BlockStrip) mrOnStrip++;
            }
            if (dist < MountainRoad.CorridorHalf + 0.3f) mrMaxS = Mathf.Max(mrMaxS, s);
            mrMaxY = Mathf.Max(mrMaxY, pos.y);
            if (k > 12f && mrLog.IndexOf("drivePic") < 0) { TestCapture("road_dozer_climbing.png"); mrLog += " drivePic"; }
            if (k < 45f && mrMaxS < 60f) return;
            d.overrideThrottle = 0f; d.overrideSteer = 0f;
            mrLog += " drove: reachedS=" + mrMaxS.ToString("F1") + "m in " + k.ToString("F0") + "s maxY=" + mrMaxY.ToString("F2") + " stepsOnMountainStrip=" + mrOnStrip + " bladeUpScraped=" + mrUpCut + " atCliffSteps=" + mrCliff + " atEdgeSteps=" + mrFence
                   + " frameMs(avg/worst)=" + (mrFrameSum / Mathf.Max(1, mrFrames) * 1000f).ToString("F1") + "/" + (mrFrameMax * 1000f).ToString("F1")
                   + " guideRefreshMs=" + job.LastRefreshMs.ToString("F2")
                   + " ms(avg/max) cut=" + w.MsAvg[0].ToString("F2") + "/" + w.MsMax[0].ToString("F1") + " clods=" + w.MsAvg[1].ToString("F2") + "/" + w.MsMax[1].ToString("F1")
                   + " slump=" + w.MsAvg[2].ToString("F2") + "/" + w.MsMax[2].ToString("F1") + " ground=" + w.MsAvg[3].ToString("F2") + "/" + w.MsMax[3].ToString("F1");
            RoadCheck(mrMaxS > 30f && mrOnStrip > 50 && mrMaxY > MountainRoad.StartY + 2.5f, "drivesOntoStrip");
            RoadCheck(mrUpCut < 1200, "bladeUpClearsHill");   // (the start's hump: going over its crest the raised blade nicks about 0.1 m3)
            mrPhase = 20; mrT0 = t; mrSide = 1; mrEdgeOut = mrEdgeFrames = 0; mrSpill0 = w.SpilledVoxels;
            return;
        }
        if (mrPhase == 20)
        {
            // cutting along the very edge of where the dozer may drive, blade down and swung right over, each side in
            // turn: the blade's ends must stay over diggable ground, and the dirt it pushes must not be thrown away
            float k = t - mrT0;
            const float S0 = 16f, Off = 3.1f;
            if (k < 0.1f)
            {
                Vector2 st = RoadPoint(S0, mrSide * Off, out dir);
                d.Place(new Vector3(st.x, 0f, st.y), Mathf.Atan2(dir.x, dir.y) * Mathf.Rad2Deg);
                return;
            }
            Vector3 pos = d.transform.position;
            float s, off;
            MountainRoad.Nearest(pos.x, pos.z, out s, out off, out dir);
            Vector2 aim = RoadPoint(s + 4.5f, mrSide * Off, out dir);
            Vector3 to = new Vector3(aim.x - pos.x, 0f, aim.y - pos.z);
            float ang = Vector3.SignedAngle(Vector3.ProjectOnPlane(d.transform.forward, Vector3.up), to, Vector3.up);
            d.overrideSteer = Mathf.Clamp(ang / 25f, -1f, 1f);
            d.overrideBlade = k < 2f ? -1f : 0f;
            d.overrideAngle = k < 2f ? mrSide : 0f;
            d.overrideThrottle = k < 1f ? 0f : 1f;
            if (k > 2f && d.Blade != null)
            {
                foreach (float e in new[] { -2.25f, 2.25f })
                {
                    Vector3 p = d.Blade.TransformPoint(new Vector3(e, -0.6f, 0.8f));
                    mrEdgeFrames++;
                    if (w.KindAt(p.x, p.z) == 0) mrEdgeOut++;
                }
            }
            if (k < 10f) return;
            d.overrideThrottle = 0f; d.overrideSteer = 0f; d.overrideAngle = 0f;
            if (mrSide == 1) { mrSide = -1; mrT0 = t; return; }
            if (k < 16f) return;                                  // let the pushed dirt settle
            long spilled = w.SpilledVoxels - mrSpill0;
            mrLog += " edgeCut: bladeEndOffDiggable=" + mrEdgeOut + "/" + mrEdgeFrames + " dirtThrownAway=" + (spilled * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L";
            RoadCheck(mrEdgeOut == 0, "bladeStaysOverDiggable");
            RoadCheck(spilled * VoxelWorld.VoxelVolume < 0.02f, "dirtKept");
            d.overrideBlade = 1f;
            mrPhase = 21; mrT0 = t; mrCut0 = w.TotalCut; mrSpill0 = w.SpilledVoxels; mrPushLog = "";
            return;
        }
        if (mrPhase == 21)
        {
            // a plain push up the middle of the road from its start, blade down: where does the cut dirt go?
            float k = t - mrT0;
            if (k < 0.1f)
            {
                Vector2 st = RoadPoint(MrPushS, 0f, out dir);
                d.Place(new Vector3(st.x, 0f, st.y), Mathf.Atan2(dir.x, dir.y) * Mathf.Rad2Deg);
                return;
            }
            Vector3 pos = d.transform.position;
            float s, off;
            MountainRoad.Nearest(pos.x, pos.z, out s, out off, out dir);
            Vector2 aim = RoadPoint(s + 4.5f, 0f, out dir);
            Vector3 to = new Vector3(aim.x - pos.x, 0f, aim.y - pos.z);
            d.overrideSteer = Mathf.Clamp(Vector3.SignedAngle(Vector3.ProjectOnPlane(d.transform.forward, Vector3.up), to, Vector3.up) / 25f, -1f, 1f);
            d.overrideBlade = k < 2f ? -1f : 0f; d.overrideAngle = 0f;
            d.overrideThrottle = k < 1f ? 0f : 1f;
            if (k > 2f && Mathf.Repeat(k, 1f) < Time.deltaTime)
                mrPushLog += " t" + k.ToString("F0") + "[speed=" + d.Speed.ToString("F2") + " bog=" + d.Bog.ToString("F2") + " heap=" + d.BladeLoadM3.ToString("F1") + " bite=" + d.CutRateM3.ToString("F1") + " s=" + s.ToString("F1") + " kind=" + w.KindAt(pos.x, pos.z) + " blade01=" + d.BladeHeight01.ToString("F2") + " cutNow=" + d.LastCut + " cutSoFar=" + (w.TotalCut - mrCut0) + " clods=" + w.ClodCount + " " + d.BladeLoadInfo() + "]";
            if (k > 6f && mrPushLog.IndexOf("pic") < 0 && d.Blade != null)
            {
                Vector3 bp = d.Blade.position;
                HillShot(bp - d.transform.right * 7f + Vector3.up * 1.5f + d.transform.forward * 1.5f, bp + d.transform.forward * 1f, "road_push_side.png");
                mrPushLog += " pic";
            }
            if (k < 9f) return;
            d.overrideThrottle = 0f; d.overrideSteer = 0f;
            mrLog += " centrePush:" + mrPushLog + " spilledL=" + ((w.SpilledVoxels - mrSpill0) * VoxelWorld.VoxelVolume * 1000f).ToString("F0");
            d.overrideBlade = 1f;
            mrPhase = 3; mrT0 = t;
            return;
        }
        if (mrPhase == 3)
        {
            // the cab readout, with the blade down a little
            float k = t - mrT0;
            d.overrideBlade = k < 0.6f ? -1f : 0f; d.overrideThrottle = 0f;
            if (k < 1.5f) return;
            mrLog += " cab=[" + job.CabText.Replace("\n", " | ") + "] arrow=" + job.CabArrow + " legend=" + job.LegendShown;
            RoadCheck(job.CabText.Length > 0 && job.CabText.Contains("Blade edge") && job.CabText.Contains("Road slope") && job.LegendShown, "cabReadout");
            ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/road_cab.png");
            mrPhase = 4; mrT0 = t;
            return;
        }
        if (mrPhase == 4)
        {
            if (t - mrT0 < 0.6f) return;
            d.overrideBlade = 1f;
            // ---- one stretch to grade: it alone gets its tick
            const int K = 4;
            job.Refresh();
            float before = job.StretchShare(K);
            int tickedBefore = job.TickedCount;
            job.TestGradeStretch(K);
            job.Refresh();
            mrLog += " stretch" + (K + 1) + ": before=" + (before * 100f).ToString("F0") + "% after=" + (job.StretchShare(K) * 100f).ToString("F0") + "% ticked=" + job.Ticked(K) + " tickedNow=" + job.TickedCount;
            RoadCheck(!(before >= MountainRoadJob.TickShare) && job.Ticked(K) && job.TickedCount == tickedBefore + 1, "gradeTicks");
            RoadCheck(!job.Paid, "notPaidYet");
            mrCoins0 = Money.Instance.Coins;
            mrPhase = 5; mrT0 = t;
            return;
        }
        if (mrPhase == 5)
        {
            if (t - mrT0 < 0.5f) return;
            // ---- the rest to grade: the job pays, once
            for (int k = 0; k < MountainRoad.Stretches; k++) job.TestGradeStretch(k);
            job.Refresh();
            long paid = Money.Instance.Coins - mrCoins0;
            job.Refresh();
            long paidAgain = Money.Instance.Coins - mrCoins0 - paid;
            long solid = w.CountSolid();
            mrLog += " allTicked=" + job.TickedCount + " paid=" + paid + " paidAgain=" + paidAgain + " volumeBooks=" + ((w.SolidCount + w.LoadVoxels) - w.StartTotal) + " trackingError=" + (w.SolidCount - solid);
            RoadCheck(job.TickedCount == MountainRoad.Stretches && job.Paid && paid == MountainRoadJob.Reward && paidAgain == 0, "allTickedPays");
            mrPhase = 6; mrT0 = t;
            return;
        }
        if (mrPhase == 6)
        {
            if (t - mrT0 < 1.2f) return;                 // let the redrawn ground show
            Vector2 a = RoadPoint(22f, -6f, out dir), b = RoadPoint(40f, 0f, out dir);
            HillShot(new Vector3(a.x, w.HeightAt(a.x, a.y) + 4.5f, a.y), new Vector3(b.x, w.HeightAt(b.x, b.y), b.y), "road_graded.png");
            HillShot(new Vector3(-10f, 40f, 20f), new Vector3(-32f, 12f, 75f), "road_graded_above.png");
            Debug.Log((mrFail ? "BULLDOZER_ROAD_FAILED " : "BULLDOZER_ROAD_RESULT ") + mrLog);
            RoadFinish(mrFail ? 1 : 0);
        }
    }

    // A save made before the mountain road loads into the bigger grid:  -executeMethod BulldozerBuilder.RoadOldSaveTest
    // Loads the save that is already there (read only) and checks the ground's books.  Prints BULLDOZER_OLDSAVE_RESULT.
    static int osPhase;
    public static void RoadOldSaveTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        osPhase = 0;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += OldSaveTick;
        EditorApplication.EnterPlaymode();
    }

    static void OldSaveTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_OLDSAVE_FAILED timed out"); EditorApplication.update -= OldSaveTick; EditorApplication.Exit(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var sg = SaveGame.Instance; var job = MountainRoadJob.Instance;
        if (w == null || sg == null || job == null || Worker.Instance == null || Time.time < 2f) return;
        if (osPhase == 0)
        {
            osPhase = 1;
            int version = -1;
            try { using (var f = System.IO.File.OpenRead(SaveGame.FilePath)) using (var z = new System.IO.Compression.GZipStream(f, System.IO.Compression.CompressionMode.Decompress)) using (var r = new System.IO.BinaryReader(z)) version = r.ReadInt32(); }
            catch (Exception e) { Debug.Log("no save to read: " + e.Message); }
            string said = sg.Load();
            long solid = w.CountSolid();
            Vector2 road = MountainRoad.Point(200);
            bool ok = said == "Game loaded." && solid == w.SolidCount && solid + w.LooseTotal() == w.StartTotal && w.KindAt(road.x, road.y) == VoxelWorld.BlockStrip && job.TickedCount == 0;
            Debug.Log((ok ? "BULLDOZER_OLDSAVE_RESULT " : "BULLDOZER_OLDSAVE_FAILED ") + "saveVersion=" + version + " said=[" + said + "] trackingError=" + (w.SolidCount - solid)
                      + " books=" + (solid + w.LooseTotal() - w.StartTotal) + " touchedChunks=" + w.TouchedChunks() + " roadStripThere=" + (w.KindAt(road.x, road.y) == VoxelWorld.BlockStrip) + " ticks=" + job.TickedCount + " loadMs=" + sg.LastMs.ToString("F0"));
            TestCapture("road_oldsave_loaded.png");
            EditorApplication.update -= OldSaveTick;
            EditorSettings.enterPlayModeOptionsEnabled = false;
            EditorApplication.Exit(ok ? 0 : 1);
        }
    }

    // Why the dozer stalls on the mountain road:  -executeMethod BulldozerBuilder.RoadStallTest     Prints BULLDOZER_STALL_RESULT.
    // Cuts up a stretch the way a driver would (thin layers, blade angled), logging the tracks, the blade and the load; when it
    // stalls it tries reversing, then lifting the blade, and logs whether either frees it.
    static int stPhase;
    static float stT0, stNext, stStallAt;
    static string stLog;

    public static void RoadStallTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        stPhase = 0; stLog = ""; stStallAt = -1f;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += StallTick;
        EditorApplication.EnterPlaymode();
    }

    static string StallState(DozerController d, VoxelWorld w)
    {
        Vector3 p = d.transform.position;
        Quaternion yr = Quaternion.Euler(0f, d.transform.eulerAngles.y, 0f);
        System.Func<float, float, float> h = (x, z) => { Vector3 q = p + yr * new Vector3(x, 0f, z); return w.HeightAt(q.x, q.z); };
        float front = (h(-1.4f, 2.2f) + h(1.4f, 2.2f)) * 0.5f, mid = (h(-1.4f, 0.1f) + h(1.4f, 0.1f)) * 0.5f, rear = (h(-1.4f, -2.0f) + h(1.4f, -2.0f)) * 0.5f;
        float ahead = h(0f, 3.0f), left = h(-1.4f, 1.2f), right = h(1.4f, 1.2f);
        Vector3 fl = p + yr * new Vector3(-1.4f, 0f, 2.2f);
        byte under = w.VoxelAtPoint(new Vector3(fl.x, w.TopAt(fl.x, fl.z) - 0.03f, fl.z));
        float s, off; Vector2 dir;
        MountainRoad.Nearest(p.x, p.z, out s, out off, out dir);
        return "s=" + s.ToString("F1") + " off=" + off.ToString("F1") + " v=" + d.Speed.ToString("F2") + " cliff=" + d.AtCliff + " rock=" + d.BlockedByRock + " fence=" + d.AtFence
             + " y=" + p.y.ToString("F2") + " tracks f/m/r=" + front.ToString("F2") + "/" + mid.ToString("F2") + "/" + rear.ToString("F2") + " (f-m " + (front - mid).ToString("F2") + ")"
             + " between=" + ahead.ToString("F2") + " sideL/R=" + left.ToString("F2") + "/" + right.ToString("F2") + " underFront=" + under
             + " pitch=" + (-d.transform.eulerAngles.x > -180f ? Mathf.DeltaAngle(0f, -d.transform.eulerAngles.x) : 0f).ToString("F1")
             + " bladeUp01=" + d.BladeHeight01.ToString("F2") + " cut=" + d.LastCut + " loadL=" + (w.LoadVoxels * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + " clods=" + w.ClodCount
             + " grade=" + (p.y - MountainRoad.GradeAt(s)).ToString("F2");
    }

    static void StallTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 400) { Debug.LogError("BULLDOZER_STALL_FAILED timed out " + stLog); EditorApplication.update -= StallTick; EditorApplication.Exit(1); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var w = VoxelWorld.Instance; var wk = Worker.Instance;
        if (d == null || w == null || wk == null || MountainRoadJob.Instance == null || Time.time < 2f) return;
        float t = Time.time;
        Vector2 dir;
        if (stPhase == 0)
        {
            wk.useOverride = true; d.dead = false;
            if (!wk.InDozer) wk.GetIn();
            d.useOverride = true;
            float s0 = 9 * MountainRoad.Length / MountainRoad.Stretches - 4f;
            Vector2 st = RoadPoint(s0, 0f, out dir);
            d.Place(new Vector3(st.x, 0f, st.y), Mathf.Atan2(dir.x, dir.y) * Mathf.Rad2Deg);
            stPhase = 1; stT0 = t; stNext = t;
            return;
        }
        float k = t - stT0;
        Vector3 pos = d.transform.position;
        float s, off;
        MountainRoad.Nearest(pos.x, pos.z, out s, out off, out dir);
        var blade = d.Blade;
        Vector3 edge = (blade.TransformPoint(new Vector3(-2.25f, -0.75f, 1.1f)) + blade.TransformPoint(new Vector3(2.25f, -0.75f, 1.1f))) * 0.5f;
        float es, eo; Vector2 ed;
        MountainRoad.Nearest(edge.x, edge.z, out es, out eo, out ed);
        float edgeOff = edge.y - MountainRoad.GradeAt(es);
        if (t >= stNext) { stNext = t + 0.5f; stLog += "\n  " + stPhase + " k=" + k.ToString("F1") + " " + StallState(d, w) + " edge=" + edgeOff.ToString("F2"); }
        if (stPhase == 1)
        {
            // cutting up the road: thin layers, the blade angled to the downhill side
            Vector3 outw = pos - new Vector3(Mountain.CX, pos.y, Mountain.CZ);
            float wy = Vector3.Dot(d.transform.right, outw) > 0f ? d.bladeMaxAngle : -d.bladeMaxAngle;
            d.overrideAngle = Mathf.Abs(d.BladeYaw - wy) < 1f ? 0f : Mathf.Sign(wy - d.BladeYaw);
            float thin = (pos.y - 0.15f) - (MountainRoad.GradeAt(s) + edgeOff);
            float aim = Mathf.Min(edgeOff, -thin);
            d.overrideBlade = aim > 0.03f ? -1f : aim < -0.03f ? 1f : 0f;
            RcSteer(d, RoadPoint(s + 4.5f, 0f, out dir), false, 0.6f);
            if (k > 1f && Mathf.Abs(d.Speed) < 0.05f) { if (stStallAt < 0f) stStallAt = t; } else stStallAt = -1f;
            if ((stStallAt > 0f && t - stStallAt > 2f) || k > 40f)
            {
                stLog += "\n  STALLED (or 40 s) at k=" + k.ToString("F1") + ": " + StallState(d, w) + " -> reversing 3 s, blade still down";
                stPhase = 2; stT0 = t;
            }
            return;
        }
        if (stPhase == 2)
        {
            d.overrideBlade = 0f; d.overrideSteer = 0f; d.overrideThrottle = -1f;
            if (k < 3f) return;
            stLog += "\n  after reversing: " + StallState(d, w) + " -> lift the blade fully and drive on 4 s";
            stPhase = 3; stT0 = t;
            return;
        }
        if (stPhase == 3)
        {
            d.overrideBlade = 1f;
            RcSteer(d, RoadPoint(s + 4.5f, 0f, out dir), false, 0.6f);
            if (k < 4f) return;
            stLog += "\n  after blade up and forward: " + StallState(d, w);
            Debug.Log("BULLDOZER_STALL_RESULT" + stLog);
            EditorApplication.update -= StallTick;
            EditorSettings.enterPlayModeOptionsEnabled = false;
            EditorApplication.Exit(0);
        }
    }

    // The upgrade tree:  -executeMethod BulldozerBuilder.UpgradeTest      Prints BULLDOZER_UPGRADE_RESULT.
    static int uPhase, uMaxShovel;
    static float uPhaseStart;
    static string uLog;
    static Vector3 uStand;

    public static void UpgradeTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        uPhase = 0; uLog = ""; uMaxShovel = 0;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += UpgradeTick;
        EditorApplication.EnterPlaymode();
    }

    static void UpgradeFinish(int code)
    {
        EditorApplication.update -= UpgradeTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    static void UpgradeTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_UPGRADE_FAILED timed out in phase " + uPhase + " " + uLog); UpgradeFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var cart = MineCart.Instance; var money = Money.Instance; var up = Upgrades.Instance;
        if (w == null || wk == null || cart == null || money == null || up == null || cart.Length <= 0f) return;
        float t = Time.time;
        if (uPhase == 0)
        {
            if (t < 1f) return;                                                  // let everything start
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            up.Reset(); money.Clear();
            uLog += "start=P" + up.Level(Upgrades.Branch.Pick) + "/S" + up.Level(Upgrades.Branch.Shovel) + "/B" + up.Level(Upgrades.Branch.Backpack) + "/C" + up.Level(Upgrades.Branch.Cart);
            wk.SetTool(2);
            uLog += " backpackLocked=" + (!wk.backpackOwned && wk.Tool != 2) + " shovelHolds=" + wk.shovelHolds + " cartHolds=" + cart.capacity;
            uLog += " buyBroke=" + up.Buy(Upgrades.Branch.Shovel) + "(" + up.CantBuy(Upgrades.Branch.Shovel) + ")";
            money.TestGrant(10000, Mathf.CeilToInt(50f / (VoxelWorld.VoxelVolume * 1000f)));
            long c0 = money.Coins;
            uLog += " backpackBeforeShovel6=" + up.Buy(Upgrades.Branch.Backpack) + "(" + up.CantBuy(Upgrades.Branch.Backpack) + ")";
            for (int k = 0; k < 5; k++) up.Buy(Upgrades.Branch.Shovel);
            uLog += " shovel=" + up.Level(Upgrades.Branch.Shovel) + " holds=" + wk.shovelHolds + " speed=" + wk.shovelSpeed.ToString("F2") + " paid=" + (c0 - money.Coins) + "(want 860)";
            int g0 = money.GoldStore; c0 = money.Coins;
            uLog += " buyBackpack=" + up.Buy(Upgrades.Branch.Backpack) + " owned=" + wk.backpackOwned + " packHolds=" + wk.packHolds + " goldTaken=" + (g0 - money.GoldStore) + " coinsTaken=" + (c0 - money.Coins);
            uLog += " sellShovel6WithPack=" + up.SellBack(Upgrades.Branch.Shovel) + "(" + up.CantSellBack(Upgrades.Branch.Shovel) + ")";
            uLog += " sellBackpack=" + up.SellBack(Upgrades.Branch.Backpack) + " refunded=" + (money.Coins == c0 && money.GoldStore == g0) + " ownedAfter=" + wk.backpackOwned;
            up.Buy(Upgrades.Branch.Backpack);
            for (int k = 0; k < 7; k++) up.Buy(Upgrades.Branch.Backpack);
            uLog += " backpackMax=" + up.Level(Upgrades.Branch.Backpack) + " packHolds=" + wk.packHolds + " suck=" + wk.suckRate.ToString("F0");
            up.Buy(Upgrades.Branch.Cart);
            uLog += " cart2Holds=" + cart.capacity;
            for (int k = 0; k < 4; k++) up.Buy(Upgrades.Branch.Pick);
            uLog += " pick=" + up.Level(Upgrades.Branch.Pick) + " radius=" + wk.pickRadius.ToString("F2") + " maxedRefused=" + !up.Buy(Upgrades.Branch.Pick);
            // keep and bring back
            var ms = new System.IO.MemoryStream(); var bw = new System.IO.BinaryWriter(ms); up.WriteState(bw); bw.Flush();
            up.Reset();
            bool resetOk = up.Level(Upgrades.Branch.Shovel) == 1 && wk.shovelHolds == 480;
            ms.Position = 0; up.ReadState(new System.IO.BinaryReader(ms));
            uLog += " resetOk=" + resetOk + " afterLoad=P" + up.Level(Upgrades.Branch.Pick) + "/S" + up.Level(Upgrades.Branch.Shovel) + "/B" + up.Level(Upgrades.Branch.Backpack) + "/C" + up.Level(Upgrades.Branch.Cart) + " holdsBack=" + wk.shovelHolds;
            // a real shovelful with Shovel 6: break up a patch beside the cart, then dig it
            Vector3 side = cart.transform.right; side.y = 0f; side.Normalize();
            uStand = cart.transform.position + side * 1.5f;
            Vector3 patch = cart.transform.position + side * 2.8f;
            for (int i = 0; i < 8; i++)
            {
                Vector3 at = patch + cart.transform.forward * (-0.6f + (i % 3) * 0.6f) + side * ((i / 3) * 0.4f);
                at.y = w.FloorAt(at + Vector3.up) + 0.05f;
                w.Pick(at, 0.45f, Vector3.zero);
            }
            Vector3 aim = patch; aim.y = w.FloorAt(aim + Vector3.up);
            Vector3 eye = uStand + Vector3.up * 1.6f, dd = aim - eye, flat = new Vector3(dd.x, 0f, dd.z);
            wk.Teleport(uStand, Facing(flat));
            wk.Look(Mathf.Atan2(-dd.y, flat.magnitude) * Mathf.Rad2Deg);
            wk.SetTool(1);
            uPhase = 1; uPhaseStart = t;
            return;
        }
        if (uPhase == 1)
        {
            if (t - uPhaseStart < 4f) return;                                    // let the broken ground settle
            wk.overrideUse = true;
            uPhase = 2; uPhaseStart = t;
            return;
        }
        if (uPhase == 2)
        {
            uMaxShovel = Mathf.Max(uMaxShovel, w.ShovelVoxels);
            if (t - uPhaseStart < 0.8f) return;
            wk.overrideUse = false;
            uLog += " realScoop=" + (uMaxShovel * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L(level1 max 117L)";
            bool uOk = uMaxShovel * VoxelWorld.VoxelVolume * 1000f > 117f;
            foreach (var want in new[] { "start=P1/S1/B0/C1", "backpackLocked=True", "buyBroke=False", "backpackBeforeShovel6=False", "shovel=6 ", "paid=860(want 860)",
                                         "buyBackpack=True", "owned=True", "sellShovel6WithPack=False", "sellBackpack=True", "refunded=True", "ownedAfter=False",
                                         "backpackMax=8", "resetOk=True", "holdsBack=1400" })
                if (uLog.IndexOf(want) < 0) { uOk = false; uLog += " WRONG[" + want + "]"; }
            Debug.Log((uOk ? "BULLDOZER_UPGRADE_RESULT " : "BULLDOZER_UPGRADE_FAILED ") + uLog);
            UpgradeFinish(uOk ? 0 : 1);
        }
    }

    // The dump and money:  -executeMethod BulldozerBuilder.DumpTest
    // Fills the cart and tips it by the mine (must pay nothing), fills it again, takes it to the dump and tips it
    // (must pay what the load was worth), checks the coins survive a save and load, and that no dirt was lost.
    // Prints BULLDOZER_DUMP_RESULT.
    static int dPhase, dSteps;
    static float dPhaseStart, dNext;
    static long dVolume0, dCoins0;
    static int dSold0, dCartV0;
    static long dPoured0;
    static float dTipEnd;
    static double dExpected;
    static string dLog;

    public static void DumpTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        dPhase = 0; dLog = "";
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += DumpTick;
        EditorApplication.EnterPlaymode();
    }

    static void DumpFinish(int code)
    {
        EditorApplication.update -= DumpTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    /// Digs the ground beside the cart and drops each load into its tub, as CartTest does.  True when done.
    static bool FillCart(VoxelWorld w, MineCart cart, float t, int want)
    {
        if (w.CartVoxels >= want) return true;
        if (t < dNext) return false;
        dNext = t + 0.08f;
        Vector3 side = cart.transform.right;
        Vector3 at = cart.transform.position + side * 2.4f + cart.transform.forward * (-1f + (dSteps % 9) * 0.25f) + Vector3.up * (0.1f - (dSteps / 9) * 0.12f);
        dSteps++;
        w.Pick(at, 0.35f, Vector3.zero);
        w.Scoop(at, 0.5f, 4000);
        if (w.ShovelVoxels >= VoxelWorld.ClodVoxels) w.Throw(cart.Mouth + Vector3.up * 0.7f, Vector3.zero, 0.25f, 0.4f);
        return false;
    }

    static double CartWorth(VoxelWorld w)
    {
        double v = 0;
        for (int m = VoxelWorld.LooseSoil; m <= VoxelWorld.LooseGold; m++) v += Money.ValueOf(m, w.CartLoadOf(m));
        return v;
    }

    static void DumpTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_DUMP_FAILED timed out in phase " + dPhase + " " + dLog); DumpFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var cart = MineCart.Instance; var money = Money.Instance;
        if (w == null || wk == null || cart == null || money == null || cart.Length <= 0f) return;
        float t = Time.time;
        if (dPhase == 0)
        {
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            dVolume0 = w.CountSolid() + w.LoadVoxels;
            dCoins0 = money.Coins;
            dLog += "coinsAtStart=" + dCoins0 + " cartAtDumpAtStart=" + cart.AtDump;
            wk.Teleport(cart.transform.position + cart.transform.right * 3.2f, Facing(-cart.transform.right));
            dSteps = 0; dNext = t;
            dPhase = 1; dPhaseStart = t;
            return;
        }
        if (dPhase == 1)
        {
            // fill it a little by the mine and tip it there: no pay
            if (!FillCart(w, cart, t, 1200) && t - dPhaseStart < 15f) return;
            if (t - dPhaseStart < 1.5f) return;
            wk.Teleport(cart.transform.position - cart.transform.right * 1.6f, Facing(cart.transform.right));
            wk.TipCart();
            dPhase = 2; dPhaseStart = t;
            return;
        }
        if (dPhase == 2)
        {
            if (cart.Tipping && t - dPhaseStart < 12f) return;
            if (t - dPhaseStart < 1f) return;
            dLog += " tippedByMine=" + (money.Earned - 0) + "coinsPaid(wantZero) leftInCart=" + w.CartVoxels;
            wk.Teleport(cart.transform.position + cart.transform.right * 3.2f, Facing(-cart.transform.right));
            dSteps = 0; dNext = t;
            dPhase = 3; dPhaseStart = t;
            return;
        }
        if (dPhase == 3)
        {
            // fill it properly, then roll it to the end of the line
            if (!FillCart(w, cart, t, 3000) && t - dPhaseStart < 20f) return;
            if (t - dPhaseStart < 2f) return;                                   // let the last clods land in it
            dExpected = CartWorth(w);
            dLog += " loaded=" + (w.CartVoxels * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L worth=" + dExpected.ToString("F1");
            cart.SetAlong(cart.EndLimit);
            dLog += " atDumpNow=" + cart.AtDump;
            wk.Teleport(cart.transform.position + cart.transform.right * 1.5f - cart.transform.forward * 1.2f, Facing(-cart.transform.right * 0.8f + cart.transform.forward * 0.6f));
            wk.Look(22f);
            dCoins0 = money.Coins; dSold0 = w.SoldVoxels; dPoured0 = w.PouredFromCart; dCartV0 = w.CartVoxels;
            wk.PressE();                                                      // E at the dump: into the hopper
            dLog += " tippingAfterE=" + cart.Tipping;
            dPhase = 4; dPhaseStart = t;
            return;
        }
        if (dPhase == 4)
        {
            if (t - dPhaseStart > 0.5f && dLog.IndexOf("tipPic") < 0)
            {
                // over his shoulder from behind the cart, looking along the track at the hopper
                Vector3 back = cart.transform.position - cart.transform.forward * 3.4f + cart.transform.right * 0.9f;
                wk.Teleport(back, Facing(cart.transform.forward - cart.transform.right * 0.45f));
                wk.Look(30f);
                dLog += " tipPicWait";
            }
            if (t - dPhaseStart > 0.9f && dLog.IndexOf("tipPic ") < 0 && dLog.IndexOf("tipPicWait") >= 0) { TestCapture("dump_tip.png"); dLog += " tipPic "; }
            if (cart.Tipping && t - dPhaseStart < 12f) { dTipEnd = t; return; }
            if (t - dTipEnd < 3.5f) return;                                    // the last of the stream is still falling in
            dLog += " cartVoxelsAtTip=" + dCartV0 + " pouredAsClods=" + (w.PouredFromCart - dPoured0) + " soldVoxels=" + (w.SoldVoxels - dSold0);
            long paid = money.Coins - dCoins0;
            dLog += " paid=" + paid + " matches=" + (System.Math.Abs(paid - dExpected) < 1.01) + " intoHopper=" + ((w.SoldVoxels - dSold0) * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L"
                  + " paidShare=" + (paid / System.Math.Max(1e-6, dExpected) * 100).ToString("F0") + "%" + " leftInCart=" + w.CartVoxels;
            // the coins in a save and back
            var ms = new System.IO.MemoryStream();
            var bw = new System.IO.BinaryWriter(ms);
            money.WriteState(bw); bw.Flush();
            long had = money.Coins;
            money.Clear();
            ms.Position = 0;
            money.ReadState(new System.IO.BinaryReader(ms));
            dLog += " coinsAfterLoad=" + (money.Coins == had);
            // spending: too much is refused, a little is taken
            dLog += " overspendRefused=" + !money.Spend(money.Coins + 1) + " spendOk=" + money.Spend(1) + " coinsNow=" + money.Coins;
            dPhase = 5; dPhaseStart = t;
            return;
        }
        if (dPhase == 5)
        {
            if (t - dPhaseStart < 1.5f) return;
            // gold: the hopper keeps it in the gold store and pays only for the dirt; the shed buys the gold
            int store0 = money.GoldStore; long c0 = money.Coins;
            var load = new int[16]; load[VoxelWorld.LooseSoil] = 400; load[VoxelWorld.LooseGold] = 80;
            money.Pay(load);
            dLog += " goldKept=" + (money.GoldStore - store0 == 80) + " dirtPaid=" + (money.Coins - c0) + "(want~" + Money.ValueOf(VoxelWorld.LooseSoil, 400).ToString("F1") + ")";
            var gm = new System.IO.MemoryStream(); var gw = new System.IO.BinaryWriter(gm); money.WriteState(gw); gw.Flush();
            int storeHad = money.GoldStore; money.Clear(); gm.Position = 0; money.ReadState(new System.IO.BinaryReader(gm));
            dLog += " goldAfterLoad=" + (money.GoldStore == storeHad);
            Vector3 front = SiteProps.GoldShedFront;
            wk.Teleport(front, Facing(Vector3.right));
            long worth = money.GoldWorth; c0 = money.Coins;
            dLog += " atShed=" + wk.AtGoldShed() + " shedAt=(" + front.x.ToString("F1") + "," + front.y.ToString("F2") + "," + front.z.ToString("F1") + ")";
            wk.PressE();
            dLog += " goldSoldFor=" + (money.Coins - c0) + "(worth " + worth + ") goldLeft=" + money.GoldStore;
            wk.PressE();                                                       // nothing left: sells nothing
            dLog += " secondSellAdded=" + (money.Coins - c0 - worth);
            // a look at the shed from out by the rails
            wk.Teleport(front + new Vector3(-6.5f, 0f, -3.5f), Facing(new Vector3(6.5f, 0f, 3.5f)));
            wk.Look(8f);
            dPhase = 8; dPhaseStart = t;
            return;
        }
        if (dPhase == 8)
        {
            if (t - dPhaseStart < 1.5f) return;
            TestCapture("gold_shed.png");
            dPhase = 9; dPhaseStart = t;
            return;
        }
        if (dPhase == 9)
        {
            Vector3 sign = SiteProps.DumpSign;
            wk.Teleport(sign + new Vector3(0f, 0f, 0f) - Vector3.up * 2f + (cart.transform.position - sign).normalized * 9f, Facing(sign - cart.transform.position) );
            wk.Look(10f);
            dPhase = 6; dPhaseStart = t;
            return;
        }
        if (dPhase == 6)
        {
            if (t - dPhaseStart < 1.5f) return;
            TestCapture("dump_sign.png");
            dPhase = 7; dPhaseStart = t;
            return;
        }
        if (dPhase == 7)
        {
            if (t - dPhaseStart < 6f) return;                                      // let the tipped dirt settle
            dLog += " clodsStillLoose=" + w.ClodCount + " volumeChange=" + ((w.CountSolid() + w.LoadVoxels) - dVolume0);
            Debug.Log("BULLDOZER_DUMP_RESULT " + dLog);
            DumpFinish(0);
        }
    }

    // How smooth pushing a big heap is:  -executeMethod BulldozerBuilder.PushPerfTest
    // Drives the dozer forward with the blade dug in for 14 seconds, building and pushing a heap, and logs the
    // frame times (median, 95th, 99th, worst) and where the time goes.  Prints BULLDOZER_PERF_RESULT.
    static int pPhase, pPeakClods;
    static float pStart;
    static readonly List<float> pFrames = new List<float>();
    static long pVolume0;

    public static void PushPerfTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        pPhase = 0; pPeakClods = 0; pFrames.Clear();
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += PerfTick;
        EditorApplication.EnterPlaymode();
    }

    static void PerfFinish(int code)
    {
        EditorApplication.update -= PerfTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    static float Pct(List<float> sorted, float q) { return sorted.Count == 0 ? 0f : sorted[Mathf.Clamp(Mathf.RoundToInt(q * (sorted.Count - 1)), 0, sorted.Count - 1)]; }

    static void PerfTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 240) { Debug.LogError("BULLDOZER_PERF_FAILED timed out"); PerfFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var w = VoxelWorld.Instance;
        if (d == null || w == null || Worker.Instance == null) return;
        float t = Time.time;
        if (pPhase == 0)
        {
            d.dead = false;
            Worker.Instance.useOverride = true;
            if (!Worker.Instance.InDozer) Worker.Instance.GetIn();
            d.useOverride = true;
            pVolume0 = w.CountSolid() + w.LoadVoxels;
            pStart = t; pPhase = 1;
            return;
        }
        float k = t - pStart;
        if (k < 1.2f) { d.overrideBlade = -1f; d.overrideThrottle = 0f; return; }       // blade down
        if (pPhase == 1) { w.ResetTimings(); pPhase = 2; }
        if (k < 15.2f)
        {
            // push on, the blade held well down so the heap keeps growing; ease it up a little part way
            d.overrideThrottle = 1f; d.overrideBlade = (k > 6f && k < 6.6f) ? 1f : (k < 3.5f ? -1f : 0f); d.overrideRipper = 0f;
            pFrames.Add(Time.unscaledDeltaTime * 1000f);
            pPeakClods = Mathf.Max(pPeakClods, w.ClodCount);
            if (pPhase == 2 && k > 10f) { pPhase = 3; TestCapture("push_heap.png"); }
            return;
        }
        if (pPhase < 4)
        {
            d.overrideThrottle = 0f;
            int n = pFrames.Count;
            float sum = 0f; foreach (var f in pFrames) sum += f;
            var sorted = new List<float>(pFrames); sorted.Sort();
            string parts = "";
            for (int i = 0; i < 5; i++)
                parts += " " + VoxelWorld.MsNames[i] + "=" + (w.MsTotal[i] / Mathf.Max(1, n)).ToString("F2") + "ms/frame(" + (w.Calls[i] > 0 ? (w.MsTotal[i] / w.Calls[i]).ToString("F2") : "0") + "x" + w.Calls[i] + ")";
            Debug.Log("BULLDOZER_PERF_RESULT frames=" + n + " avgMs=" + (sum / Mathf.Max(1, n)).ToString("F1")
                + " p50=" + Pct(sorted, 0.5f).ToString("F1") + " p95=" + Pct(sorted, 0.95f).ToString("F1") + " p99=" + Pct(sorted, 0.99f).ToString("F1")
                + " worst=" + Pct(sorted, 1f).ToString("F1") + " peakClods=" + pPeakClods + " drove=" + (d.transform.position - testPos0).magnitude.ToString("F1")
                + parts + " worstRemeshMs=" + w.MaxRemeshMs.ToString("F1") + "/" + w.MaxRemeshChunks + "chunks"
                + " volumeChange=" + ((w.CountSolid() + w.LoadVoxels) - pVolume0));
            pPhase = 4;
            return;
        }
        // stopped, blade still down against the heap: the clods should settle and go still
        if (pPhase == 4 && k > 17.2f) { int f; float sp = w.ClodMeanSpeed(0.05f, out f); Debug.Log("BULLDOZER_STOP_A clods=" + w.ClodCount + " meanSpeed=" + sp.ToString("F3") + " moving=" + f); pPhase = 5; }
        if (pPhase == 5 && k > 21.2f)
        {
            int f; float sp = w.ClodMeanSpeed(0.05f, out f);
            Debug.Log("BULLDOZER_STOP_RESULT after6s clods=" + w.ClodCount + " meanSpeed=" + sp.ToString("F3") + " moving=" + f + " volumeChange=" + ((w.CountSolid() + w.LoadVoxels) - pVolume0));
            pPhase = 6;
            PerfFinish(0);
        }
    }

    // The mine tunnel:  -executeMethod BulldozerBuilder.TunnelTest
    // Counts what is in each collapse and the seams in the far chambers, pictures each stretch (tunnel_*.png), and
    // stands him with the jackhammer at the chamber seam to check the gold warning comes up (tunnel_warning.png is a
    // screenshot with the HUD).  Prints BULLDOZER_TUNNEL_RESULT.
    static int dustSeam, chipsSeam, glintsSeam; static float tPitch;
    static int tPhase; static string tLog; static float tStart; static int tShot;

    public static void TunnelTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        tPhase = 0; tLog = ""; tShot = 0;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += TunnelTick;
        EditorApplication.EnterPlaymode();
    }

    static void TunnelFinish(int code)
    {
        EditorApplication.update -= TunnelTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    /// What fills a stretch of the tunnel: loose rubble, solid rock, quartz and gold voxels.
    static string TunnelStretch(VoxelWorld w, float a0, float a1, float halfW, float tall, out int loose, out int rock, out int gold)
    {
        loose = rock = gold = 0; int quartz = 0;
        for (float z = a0; z < a1; z += VoxelWorld.Voxel)
            for (float x = -halfW; x < halfW; x += VoxelWorld.Voxel)
                for (float y = 0.03f; y < tall; y += VoxelWorld.Voxel)
                {
                    byte m = w.MaterialAt(new Vector3(VoxelWorld.PortalX + x, y, VoxelWorld.PortalZ + z));
                    if (m >= VoxelWorld.LooseSoil) loose++;
                    else if (m == VoxelWorld.Rock) rock++;
                    else if (m == VoxelWorld.Quartz) quartz++;
                    else if (m == VoxelWorld.Gold) gold++;
                }
        return "loose=" + loose + " rock=" + rock + " quartz=" + quartz + " gold=" + gold;
    }

    static void TunnelShot(Vector3 at, Vector3 look, string file)
    {
        var cam = Camera.main;
        cam.transform.SetPositionAndRotation(at, Quaternion.LookRotation(look - at));
        TestCapture(file);
    }

    static void TunnelTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_TUNNEL_FAILED timed out in phase " + tPhase + " " + tLog); TunnelFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var up = Upgrades.Instance;
        if (w == null || wk == null || up == null) return;
        float t = Time.time;
        float px = VoxelWorld.PortalX, pz = VoxelWorld.PortalZ;
        if (tPhase == 0)
        {
            if (t < 1.5f) return;
            int l0, r0, g0, l1, r1, g1, l2, r2, g2, lo, ro, go;
            tLog += "collapse1[" + TunnelStretch(w, 3f, 7f, 1.5f, 2.6f, out l0, out r0, out g0) + "]";
            tLog += " collapse2[" + TunnelStretch(w, 13f, 19f, 1.5f, 2.6f, out l1, out r1, out g1) + "]";
            tLog += " collapse3[" + TunnelStretch(w, 23f, 28f, 1.5f, 2.6f, out l2, out r2, out g2) + "]";
            tLog += " openStretch[" + TunnelStretch(w, 8f, 12.5f, 1.5f, 2.5f, out lo, out ro, out go) + "]";
            int sl, sr, sg, el, er, eg;
            tLog += " chamber2Walls[" + TunnelStretch(w, 19.5f, 22.5f, 3.2f, 3.0f, out sl, out sr, out sg) + "]";
            tLog += " endWalls[" + TunnelStretch(w, 28f, 31f, 3.5f, 3.2f, out el, out er, out eg) + "]";
            for (int k = 0; k < 3; k++) tLog += " find" + k + "=" + VoxelWorld.FindSpot(k).z.ToString("F1");
            bool rockier = (float)r0 / Mathf.Max(1, l0 + r0) < (float)r1 / Mathf.Max(1, l1 + r1) && (float)r1 / Mathf.Max(1, l1 + r1) < (float)r2 / Mathf.Max(1, l2 + r2);
            tLog += " eachRockier=" + rockier + " openIsOpen=" + (lo + ro < 200) + " seamGold=" + (sg + eg);
            if (!rockier || lo + ro >= 200 || sg + eg == 0 || l0 < 1000 || l1 < 1000 || l2 < 500) { Debug.LogError("BULLDOZER_TUNNEL_FAILED " + tLog); TunnelFinish(1); return; }
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            tPhase = 1; tStart = t;
            return;
        }
        if (tPhase == 1)
        {
            // pictures: from the mouth, the open stretch, the seam chamber, the end chamber
            if (tShot == 0) { wk.Teleport(new Vector3(px - 4f, 0f, pz - 8f), 0f); TunnelShot(new Vector3(px - 0.6f, 1.6f, pz - 3f), new Vector3(px, 1.0f, pz + 6f), "tunnel_mouth.png"); }
            if (tShot == 1) TunnelShot(new Vector3(px - 0.8f, 1.7f, pz + 8f), new Vector3(px, 1.0f, pz + 15f), "tunnel_open.png");
            if (tShot == 2) TunnelShot(new Vector3(px + 1.4f, 1.6f, pz + 19.8f), new Vector3(px - 2.3f, 1.3f, pz + 22f), "tunnel_seam.png");
            if (tShot == 3) TunnelShot(new Vector3(px - 1.8f, 1.8f, pz + 28.4f), new Vector3(px + 1.5f, 1.2f, pz + 30.8f), "tunnel_end.png");
            tShot++;
            if (tShot < 4) return;
            // the jackhammer at the chamber seam, biggest bite: the warning should be up
            up.SetLevel(Upgrades.Branch.Pick, 6);
            wk.SetTool(0);
            wk.SetJackSize(1f);
            wk.Teleport(new Vector3(px - 1.0f, 0f, pz + 21f), -90f);   // within reach of the west wall
            tPhase = 2; tStart = t;
            return;
        }
        if (tPhase == 2)
        {
            // find a pitch that puts the aim on the seam (quartz or gold) in the west wall
            float best = 0f; bool on = false;
            for (float pitch = -20f; pitch <= 30f && !on; pitch += 1f)
            {
                wk.Look(pitch);
                if (wk.AimingAtSeam) { best = pitch; on = true; }
            }
            if (!on) { if (t - tStart > 3f) { Debug.LogError("BULLDOZER_TUNNEL_FAILED never aimed at the seam " + tLog); TunnelFinish(1); } return; }
            wk.Look(best); tPitch = best;
            tPhase = 3; tStart = t;
            return;
        }
        if (tPhase == 3)
        {
            if (t - tStart < 0.6f) return;
            bool warnBig = wk.GoldWarning;
            ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/tunnel_warning.png");
            tLog += " warningAtBigBite=" + warnBig;
            tPhase = 4; tStart = t;
            return;
        }
        if (tPhase == 4)
        {
            if (t - tStart < 0.6f) return;
            wk.SetJackSize(0f);
            tPhase = 5; tStart = t;
            return;
        }
        if (tPhase == 5)
        {
            if (t - tStart < 0.6f) return;
            bool warnSmall = wk.GoldWarning;
            tLog += " warningAtSmallBite=" + warnSmall;
            if (!tLog.Contains("warningAtBigBite=True") || warnSmall) { Debug.LogError("BULLDOZER_TUNNEL_FAILED " + tLog); TunnelFinish(1); return; }
            // close up on the seam beside him, under the lantern: a few blocks of it twinkle (he is within 4 m)
            TunnelShot(new Vector3(px - 1.2f, 1.5f, pz + 19.9f), new Vector3(px - 2.3f, 1.2f, pz + 20.7f), "tunnel_sparkle.png");
            wk.SetJackSize(0.25f);              // still safe for gold, a bit more dust than the smallest
            wk.overrideUse = true;
            tPhase = 6; tStart = t;
            return;
        }
        if (tPhase == 6)
        {
            // a still aim bores straight in (about a metre in half a second), so sweep it up and down the seam the
            // way a player does, and take the picture after a second and a half of work
            wk.Look(tPitch + Mathf.Sin((t - tStart) * 4f) * 7f);
            if (t - tStart < 1.5f) return;
            TunnelShot(new Vector3(px - 0.6f, 1.75f, pz + 19.7f), new Vector3(px - 2.2f, 1.1f, pz + 21.0f), "tunnel_dust.png");
            int dN, cN, gN; JackFX.Alive(out dN, out cN, out gN);
            tPhase = 7; tStart = t;
            tLog += " hammering=" + wk.Hammering + " " + wk.AimInfo + " dust " + JackFX.DustInfo() + " cam=" + Camera.main.transform.position;
            dustSeam = dN; chipsSeam = cN; glintsSeam = gN;
            return;
        }
        if (tPhase == 7)
        {
            if (t - tStart < 0.3f) return;
            wk.overrideUse = false;
            int dN = dustSeam, cN = chipsSeam, gN = glintsSeam;
            tLog += " dustAtSeam=" + dN + " chipsAtSeam=" + cN + " glintsAtSeam=" + gN;
            bool ok = dN + cN > 0;      // a fifth of a second in: a few chips, maybe a puff (the smallest bite puffs less)
            if (ok) Debug.Log("BULLDOZER_TUNNEL_RESULT " + tLog); else Debug.LogError("BULLDOZER_TUNNEL_FAILED " + tLog);
            TunnelFinish(ok ? 0 : 1);
        }
    }

    // ---------------------------------------------------------------- the game pad
    // The pad's sticks, triggers and d-pad, by name, in the Input Manager (Pad.cs reads them).  Adds any that are
    // missing; leaves everything else as it is.  Axis numbers are Unity's for an Xbox-style pad on Windows, which is
    // what Steam makes of the Steam Controller.
    [MenuItem("Tools/Bulldozer/Add game pad axes")]
    public static void EnsurePadAxes()
    {
        var assets = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/InputManager.asset");
        if (assets == null || assets.Length == 0) { Debug.LogWarning("Pad axes: no InputManager.asset"); return; }
        var so = new SerializedObject(assets[0]);
        var axes = so.FindProperty("m_Axes");
        int added = 0;
        for (int a = 0; a < Pad.AxisNames.Length; a++)
        {
            bool have = false;
            for (int i = 0; i < axes.arraySize && !have; i++)
                have = axes.GetArrayElementAtIndex(i).FindPropertyRelative("m_Name").stringValue == Pad.AxisNames[a];
            if (have) continue;
            axes.arraySize++;
            var e = axes.GetArrayElementAtIndex(axes.arraySize - 1);
            e.FindPropertyRelative("m_Name").stringValue = Pad.AxisNames[a];
            e.FindPropertyRelative("descriptiveName").stringValue = "";
            e.FindPropertyRelative("descriptiveNegativeName").stringValue = "";
            e.FindPropertyRelative("negativeButton").stringValue = "";
            e.FindPropertyRelative("positiveButton").stringValue = "";
            e.FindPropertyRelative("altNegativeButton").stringValue = "";
            e.FindPropertyRelative("altPositiveButton").stringValue = "";
            e.FindPropertyRelative("gravity").floatValue = 0f;
            e.FindPropertyRelative("dead").floatValue = 0.02f;            // Pad.cs takes out its own dead zones
            e.FindPropertyRelative("sensitivity").floatValue = 1f;
            e.FindPropertyRelative("snap").boolValue = false;
            e.FindPropertyRelative("invert").boolValue = Pad.AxisInvert[a];
            e.FindPropertyRelative("type").intValue = 2;                  // joystick axis
            e.FindPropertyRelative("axis").intValue = Pad.AxisNumbers[a];
            e.FindPropertyRelative("joyNum").intValue = 0;                // any pad
            added++;
        }
        if (added == 0) return;
        so.ApplyModifiedPropertiesWithoutUndo();
        AssetDatabase.SaveAssets();
        Debug.Log("Pad axes: added " + added + " to the Input Manager");
    }

    // The pause menu:  -executeMethod BulldozerBuilder.MenuTest
    // Opens the menu from the upgrades with the pad's Back (the game must stop), picks Settings with the d-pad and A,
    // raises the quality, changes the mouse speed and view distance, closes it with Start (the game must run again),
    // then checks the settings come back from PlayerPrefs.  Saves Logs/menu_paused.png and Logs/menu_settings.png.
    // Then Ultra: digs a stepped pit in front of him, turns the fps counter on, and on Medium and on Ultra takes a
    // picture of the pit (Logs/quality_medium.png, Logs/quality_ultra.png) and times the frames: the editor's game view
    // over two seconds, and the camera drawing alone at 3440 x 1440.  Then back to Medium, which must be as it was.
    // The editor's own saved settings are put back at the end.  Prints BULLDOZER_MENU_RESULT.
    static int menuPhase, menuWaitFrame;
    static float menuWaitReal, menuT, menuShadow1, menuMeasureT, menuAA;
    static int menuMeasureF; static bool menuMsaa0; static int menuSunRes0;
    static Vector3 menuPit, menuCamAt;
    static bool menuOk;
    static string menuLog;
    static readonly string[] menuKeys = { "set.quality", "set.view", "set.shadows", "set.invert", "set.mouse", "set.fps", "set.uisize" };
    static bool MenuFloatKey(string k) { return k == "set.mouse" || k == "set.uisize"; }
    static string[] menuOld;

    public static void MenuTest()
    {
        EnsurePadAxes();
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        menuPhase = 0; menuWaitFrame = 0; menuWaitReal = 0f; menuOk = true; menuLog = "";
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += MenuTick;
        EditorApplication.EnterPlaymode();
    }

    static void MenuCheck(bool ok, string what) { menuLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) menuOk = false; }

    static void MenuFinish(bool ok)
    {
        if (menuOld != null)                                                    // put the editor's own settings back
        {
            for (int i = 0; i < menuKeys.Length; i++)
            {
                if (menuOld[i] == null) PlayerPrefs.DeleteKey(menuKeys[i]);
                else if (MenuFloatKey(menuKeys[i])) PlayerPrefs.SetFloat(menuKeys[i], float.Parse(menuOld[i], System.Globalization.CultureInfo.InvariantCulture));
                else PlayerPrefs.SetInt(menuKeys[i], int.Parse(menuOld[i]));
            }
            PlayerPrefs.Save();
            menuOld = null;
        }
        if (ok) Debug.Log("BULLDOZER_MENU_RESULT" + menuLog);
        else Debug.LogError("BULLDOZER_MENU_FAILED phase " + menuPhase + menuLog);
        Pad.overrideOn = false; Pad.ClearOverride();
        Time.timeScale = 1f;
        EditorApplication.update -= MenuTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(ok ? 0 : 1);
    }

    static void MenuTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 480) { menuLog += " timed out"; MenuFinish(false); return; }
        if (!EditorApplication.isPlaying) return;
        var wk = Worker.Instance; var up = Upgrades.Instance; var pm = PauseMenu.Instance;
        if (wk == null || up == null || pm == null || VoxelWorld.Instance == null) return;
        float now = Time.realtimeSinceStartup;                               // (game time stops while the menu is up)
        if (Time.frameCount < menuWaitFrame || now < menuWaitReal) return;
        menuWaitFrame = Time.frameCount + 2;                                    // each step gets at least two frames
        switch (menuPhase++)
        {
            case 0: menuWaitReal = now + 2f; break;                             // let everything start
            case 1:
                wk.useOverride = true;
                menuOld = new string[menuKeys.Length];
                for (int i = 0; i < menuKeys.Length; i++)
                    menuOld[i] = !PlayerPrefs.HasKey(menuKeys[i]) ? null : MenuFloatKey(menuKeys[i])
                        ? PlayerPrefs.GetFloat(menuKeys[i]).ToString(System.Globalization.CultureInfo.InvariantCulture) : PlayerPrefs.GetInt(menuKeys[i]).ToString();
                foreach (var k in menuKeys) PlayerPrefs.DeleteKey(k);
                PauseMenu.LoadPrefs(); pm.ApplyGraphics();
                menuShadow1 = QualitySettings.shadowDistance;
                menuLog += " start: quality=" + PauseMenu.QualityNames[PauseMenu.Quality] + " shadowDist=" + menuShadow1.ToString("F0") + " far=" + Camera.main.farClipPlane.ToString("F0");
                MenuCheck(PauseMenu.Quality == 1 && PauseMenu.View == 2 && Mathf.Approximately(Camera.main.farClipPlane, 900f), "defaultIsTheOldLook");
                Pad.overrideOn = true; Pad.ClearOverride();
                up.SetOpen(true);
                break;
            case 2: Pad.Hold(Pad.B.Back, true); break;
            case 3:
                Pad.Hold(Pad.B.Back, false);
                MenuCheck(PauseMenu.Paused && !up.Open, "backFromUpgradesOpensMenu");
                MenuCheck(Time.timeScale == 0f, "timeStopped");
                menuT = Time.time; menuWaitReal = now + 0.5f;
                break;
            case 4:
                MenuCheck(Time.time == menuT, "clockStill");
                ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/menu_paused.png");
                menuWaitReal = now + 1f;
                break;
            case 5: Pad.oDY = -1; break;                                     // d-pad down: Settings
            case 6: Pad.oDY = 0; break;
            case 7: Pad.Hold(Pad.B.A, true); break;
            case 8: Pad.Hold(Pad.B.A, false); break;
            case 9: Pad.oDX = 1; break;                                      // d-pad right on Quality
            case 10:
                Pad.oDX = 0;
                MenuCheck(PauseMenu.Quality == 2, "padRaisesQuality");
                MenuCheck(QualitySettings.shadowDistance > menuShadow1 * 1.5f, "highDrawsShadowsFurther");
                pm.Change(7, +1); pm.Change(7, +1);                          // mouse speed 1 -> 1.5
                pm.Change(PauseMenu.UiSizeRow, +1);                          // UI size 100% -> 125%
                MenuCheck(Mathf.Approximately(Ui.Size, 1.25f) && Mathf.Approximately(Ui.Wanted, Mathf.Max(0.5f, Screen.height / 1080f) * 1.25f), "uiSizeScales");
                pm.Change(2, -1);                                            // view distance Far -> Middle
                MenuCheck(Mathf.Approximately(PauseMenu.MouseSpeed, 1.5f), "mouseSpeed");
                ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/menu_settings.png");
                menuWaitReal = now + 1f;
                break;
            case 11: Pad.Hold(Pad.B.Start, true); break;
            case 12:
                Pad.Hold(Pad.B.Start, false);
                MenuCheck(!PauseMenu.Paused && Time.timeScale == 1f, "startCloses");
                menuT = Time.time; menuWaitReal = now + 0.5f;
                break;
            case 13:
                MenuCheck(Time.time > menuT + 0.2f, "clockRunsAgain");
                MenuCheck(Mathf.Approximately(Camera.main.farClipPlane, 450f), "viewDistance=" + Camera.main.farClipPlane.ToString("F0"));
                MenuCheck(RenderSettings.fogDensity >= 2.4f / 450f - 0.0001f, "hazeThickened");
                PauseMenu.Quality = 0; PauseMenu.MouseSpeed = 1f; PauseMenu.View = 2; Ui.Size = 1f;   // forget them, then read them back
                PauseMenu.LoadPrefs();
                MenuCheck(PauseMenu.Quality == 2 && Mathf.Approximately(PauseMenu.MouseSpeed, 1.5f) && PauseMenu.View == 1, "keptAfterReload");
                MenuCheck(Mathf.Approximately(Ui.Size, 1.25f), "uiSizeKept");
                Ui.Size = 1f;
                // ---- Ultra and the fps counter
                PauseMenu.View = 2;
                PauseMenu.Quality = 1; pm.ApplyGraphics();
                menuMsaa0 = Camera.main.allowMSAA; menuAA = QualitySettings.antiAliasing;
                menuSunRes0 = RenderSettings.sun != null ? RenderSettings.sun.shadowCustomResolution : -1;
                MenuDigPit(wk);
                if (!PauseMenu.ShowFps) pm.ToggleFps();
                MenuAim();
                menuWaitReal = now + 2f;
                break;
            case 14: menuMeasureT = now; menuMeasureF = Time.frameCount; MenuAim(); menuWaitReal = now + 2f; break;
            case 15:
                MenuCheck(PauseMenu.ShowFps && PauseMenu.FpsText.Length > 0, "fpsCounterShows(" + PauseMenu.FpsText + ")");
                menuLog += " medium: gameView=" + MenuMs(now) + "ms render3440=" + MenuRenderMs() + "ms";
                ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/quality_medium.png");
                menuWaitReal = now + 1f;
                break;
            case 16:
                pm.Change(0, +1); pm.Change(0, +1);                          // Medium -> High -> Ultra
                MenuCheck(PauseMenu.Quality == 3 && PauseMenu.QualityNames[3] == "Ultra", "ultraPicked");
                MenuCheck(QualitySettings.antiAliasing == 8 && QualitySettings.shadowDistance > menuShadow1 * 2f, "ultraAaAndShadows");
                MenuCheck(RenderSettings.sun == null || RenderSettings.sun.shadowCustomResolution == 8192, "ultraSunShadowMap");
                MenuCheck(PauseMenu.AoNow == PauseMenu.UltraAo, "ultraAo=" + PauseMenu.AoNow.ToString("F1"));
                MenuAim();
                menuWaitReal = now + 2f;
                break;
            case 17:
                MenuCheck(Camera.main.allowMSAA, "ultraMsaaOn");
                menuMeasureT = now; menuMeasureF = Time.frameCount; MenuAim(); menuWaitReal = now + 2f; break;
            case 18:
                menuLog += " ultra: gameView=" + MenuMs(now) + "ms render3440=" + MenuRenderMs() + "ms";
                ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/quality_ultra.png");
                menuWaitReal = now + 1f;
                break;
            case 19:
                pm.Change(0, -1); pm.Change(0, -1);                          // back to Medium
                MenuCheck(PauseMenu.Quality == 1 && Mathf.Approximately(QualitySettings.shadowDistance, menuShadow1)
                          && QualitySettings.antiAliasing == menuAA, "backToMedium");
                MenuCheck(RenderSettings.sun == null || RenderSettings.sun.shadowCustomResolution == menuSunRes0, "sunShadowMapBack");
                MenuCheck(PauseMenu.AoNow < PauseMenu.UltraAo, "aoBack=" + PauseMenu.AoNow.ToString("F1"));
                MenuAim(); menuWaitReal = now + 1f;
                break;
            case 20:
                // Medium timed again, now everything is warmed up (the first time included the pit being built)
                menuMeasureT = now; menuMeasureF = Time.frameCount; MenuAim(); menuWaitReal = now + 2f; break;
            case 21:
                menuLog += " mediumAgain: gameView=" + MenuMs(now) + "ms render3440=" + MenuRenderMs() + "ms";
                MenuCheck(Camera.main.allowMSAA == menuMsaa0, "msaaBackAsItWas");
                pm.ToggleFps();
                MenuCheck(!PauseMenu.ShowFps, "fpsCounterOff");
                MenuFinish(menuOk);
                break;
        }
    }

    // a stepped pit (terraces a quarter metre deep, with odd blocks up and down) and a ripped furrow beside it,
    // 4 m in front of him, so the pictures show dug voxel ground
    static void MenuDigPit(Worker wk)
    {
        var w = VoxelWorld.Instance;
        var dz0 = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        Transform from = wk.InDozer && dz0 != null ? dz0.transform : wk.transform;        // he starts in the dozer
        Vector3 fwd = from.forward; fwd.y = 0f; fwd.Normalize();
        menuPit = from.position + fwd * 8f;
        float v = VoxelWorld.Voxel;
        for (float dx = -1.6f; dx <= 1.6f; dx += v)
            for (float dz = -1.6f; dz <= 1.6f; dz += v)
            {
                float r = Mathf.Max(Mathf.Abs(dx), Mathf.Abs(dz));
                float depth = r < 0.5f ? 0.75f : r < 1.0f ? 0.5f : r < 1.5f ? 0.25f : 0f;
                if (depth <= 0f) continue;
                float hsh = Mathf.Abs(Mathf.Sin(dx * 127.1f + dz * 311.7f) * 43758.5453f) % 1f;
                if (hsh > 0.93f) depth -= v * 2f; else if (hsh < 0.05f) depth += v;
                float wx = menuPit.x + dx, wz = menuPit.z + dz;
                w.TestSetColumn(wx, wz, w.HeightAt(wx, wz) - depth);
            }
        Vector3 side = Vector3.Cross(Vector3.up, fwd);
        var pts = new Vector3[12];
        for (int i = 0; i < pts.Length; i++)
        {
            Vector3 q = menuPit + side * 2.4f + fwd * (-1.5f + i * 0.27f);
            q.y = w.HeightAt(q.x, q.z) - 0.12f;
            pts[i] = q;
        }
        w.Rip(pts, 0.35f, Vector3.zero);
        menuPit.y = w.HeightAt(menuPit.x, menuPit.z);
        menuCamAt = menuPit + fwd * 3.0f + side * 1.1f + Vector3.up * 2.2f;   // past the pit, looking back at it (and the dozer)
    }

    static void MenuAim()
    {
        var cam = Camera.main;
        var follow = cam.GetComponent<FollowCamera>();
        if (follow != null) follow.enabled = false;
        cam.transform.SetPositionAndRotation(menuCamAt, Quaternion.LookRotation(menuPit + Vector3.up * 0.2f - menuCamAt));
    }

    static string MenuMs(float now)
    {
        int f = Time.frameCount - menuMeasureF;
        return f > 0 ? ((now - menuMeasureT) * 1000f / f).ToString("F2") : "?";
    }

    // the camera drawing the same view 20 times at the owner's screen size, waited for by reading a pixel back
    static string MenuRenderMs()
    {
        var cam = Camera.main;
        int aa = cam.allowMSAA ? Mathf.Max(1, QualitySettings.antiAliasing) : 1;
        var rt = new RenderTexture(3440, 1440, 24, RenderTextureFormat.DefaultHDR) { antiAliasing = aa };
        var px = new Texture2D(1, 1, TextureFormat.RGBAFloat, false);
        var old = cam.targetTexture;
        cam.targetTexture = rt;
        cam.Render();                                                         // the first one sets things up
        RenderTexture.active = rt; px.ReadPixels(new Rect(0, 0, 1, 1), 0, 0); RenderTexture.active = null;
        var sw = System.Diagnostics.Stopwatch.StartNew();
        const int n = 20;
        for (int i = 0; i < n; i++) cam.Render();
        RenderTexture.active = rt; px.ReadPixels(new Rect(0, 0, 1, 1), 0, 0); px.Apply(); RenderTexture.active = null;
        double ms = sw.Elapsed.TotalMilliseconds / n;
        cam.targetTexture = old;
        rt.Release(); UnityEngine.Object.DestroyImmediate(rt); UnityEngine.Object.DestroyImmediate(px);
        return ms.ToString("F2");
    }

    // The upgrade tree screen and the UI size:  -executeMethod BulldozerBuilder.TreeTest
    // Gets him out of the dozer, then with the pad (Pad's override): Start opens the tree, the d-pad moves the pick down
    // a column and across to the next, A on a locked node buys nothing, A on a node that can be bought buys it, A on one
    // that is too dear buys nothing, and d-pad right from Shovel 6 lands on the Backpack.  Then the pictures, with the
    // editor's game view set to 1920 x 1080 and to 3440 x 1440: Logs/tree_1080.png, tree_3440.png, hud_3440.png,
    // settings_3440.png, and it checks the panels' scale follows the screen height (1440 high draws them 1.33 times).
    // Prints BULLDOZER_TREE_RESULT.
    static int treePhase, treeWaitFrame, treeSize0 = -1;
    static float treeWaitReal;
    static bool treeOk;
    static string treeLog;
    static long treeCoins;

    public static void TreeTest()
    {
        EnsurePadAxes();
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        treePhase = 0; treeWaitFrame = 0; treeWaitReal = 0f; treeOk = true; treeLog = "";
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += TreeTick;
        EditorApplication.EnterPlaymode();
    }

    static void TreeCheck(bool ok, string what) { treeLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) treeOk = false; }

    static void TreeFinish(bool ok)
    {
        if (treeSize0 >= 0) GameViewSelect(treeSize0);
        if (ok) Debug.Log("BULLDOZER_TREE_RESULT" + treeLog);
        else Debug.LogError("BULLDOZER_TREE_FAILED phase " + treePhase + treeLog);
        Pad.overrideOn = false; Pad.ClearOverride();
        Ui.Size = 1f;
        EditorApplication.update -= TreeTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(ok ? 0 : 1);
    }

    static void TreeShot(string name) { ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/" + name); }

    static void TreeTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { treeLog += " timed out"; TreeFinish(false); return; }
        if (!EditorApplication.isPlaying) return;
        var wk = Worker.Instance; var up = Upgrades.Instance; var pm = PauseMenu.Instance; var money = Money.Instance;
        if (wk == null || up == null || pm == null || money == null || VoxelWorld.Instance == null) return;
        float now = Time.realtimeSinceStartup;
        if (Time.frameCount < treeWaitFrame || now < treeWaitReal) return;
        treeWaitFrame = Time.frameCount + 2;
        switch (treePhase++)
        {
            case 0: treeWaitReal = now + 2f; break;                             // let everything start
            case 1:
                if (wk.InDozer) wk.GetOut();
                wk.useOverride = false;                                         // (the tree ignores the pad while a test drives him)
                up.Reset(); money.Clear(); money.TestGrant(1000, 0);
                Ui.Size = 1f;
                treeSize0 = GameViewIndex();
                TreeCheck(GameViewSize(1920, 1080), "gameView1080");
                Pad.overrideOn = true; Pad.ClearOverride();
                treeWaitReal = now + 0.5f;
                break;
            case 2: Pad.Hold(Pad.B.Start, true); break;
            case 3:
                Pad.Hold(Pad.B.Start, false);
                TreeCheck(up.Open, "startOpensTree");
                TreeCheck(up.SelectedName == "Pick 2" && up.SelectedState == Upgrades.NodeState.CanBuy, "startsOnFirstBuyable(" + up.SelectedName + ")");
                Pad.oDY = -1;                                                   // d-pad down
                break;
            case 4: Pad.oDY = 0; break;
            case 5:
                TreeCheck(up.SelectedName == "Pick 3", "dpadDown(" + up.SelectedName + ")");
                Pad.oDX = 1;                                                    // d-pad right: the shovel column
                break;
            case 6: Pad.oDX = 0; break;
            case 7:
                TreeCheck(up.SelectedName == "Shovel 3" && up.SelectedColumn == 1, "dpadRight(" + up.SelectedName + ")");
                up.Select(Upgrades.Branch.Backpack, 0);
                TreeCheck(up.SelectedState == Upgrades.NodeState.Locked, "backpackLocked");
                treeCoins = money.Coins;
                Pad.Hold(Pad.B.A, true);
                break;
            case 8: Pad.Hold(Pad.B.A, false); break;
            case 9:
                TreeCheck(up.Level(Upgrades.Branch.Backpack) == 0 && money.Coins == treeCoins, "lockedNotBought");
                up.Select(Upgrades.Branch.Shovel, 1);
                Pad.Hold(Pad.B.A, true);
                break;
            case 10: Pad.Hold(Pad.B.A, false); break;
            case 11:
                TreeCheck(up.Level(Upgrades.Branch.Shovel) == 2 && money.Coins == treeCoins - 40 && up.SelectedState == Upgrades.NodeState.Owned, "aBuys");
                up.SetLevel(Upgrades.Branch.Pick, 5);
                money.Clear(); money.TestGrant(100, 0);                         // the jackhammer: 600 coins, there are 100
                up.Select(Upgrades.Branch.Pick, 5);
                TreeCheck(up.SelectedState == Upgrades.NodeState.TooDear, "jackhammerTooDear");
                treeCoins = money.Coins;
                Pad.Hold(Pad.B.A, true);
                break;
            case 12: Pad.Hold(Pad.B.A, false); break;
            case 13:
                TreeCheck(up.Level(Upgrades.Branch.Pick) == 5 && money.Coins == treeCoins, "tooDearNotBought");
                up.SetLevel(Upgrades.Branch.Shovel, 6);
                up.Select(Upgrades.Branch.Shovel, 5);
                Pad.oDX = 1;
                break;
            case 14: Pad.oDX = 0; break;
            case 15:
                TreeCheck(up.SelectedName == "Backpack" && up.SelectedState == Upgrades.NodeState.TooDear, "shovel6ToBackpackUnlocked(" + up.SelectedName + " " + up.SelectedState + ")");
                // a tree that shows every kind of node for the pictures
                up.SetLevel(Upgrades.Branch.Backpack, 2); up.SetLevel(Upgrades.Branch.Cart, 2);
                money.Clear(); money.TestGrant(700, 0);
                up.Select(Upgrades.Branch.Pick, 5);
                treeWaitReal = now + 1f;
                break;
            case 16:
                TreeCheck(Screen.height == 1080 && Mathf.Abs(Ui.Scale - 1f) < 0.01f, "scale1080=" + Ui.Scale.ToString("F2") + "(" + Screen.width + "x" + Screen.height + ")");
                TreeShot("tree_1080.png");
                treeWaitReal = now + 1f;
                break;
            case 17:
                TreeCheck(GameViewSize(3440, 1440), "gameView3440");
                up.Select(Upgrades.Branch.Backpack, 2);
                treeWaitReal = now + 1.5f;
                break;
            case 18:
                TreeCheck(Screen.height == 1440 && Mathf.Abs(Ui.Scale - 1440f / 1080f) < 0.01f, "scale1440=" + Ui.Scale.ToString("F2") + "(" + Screen.width + "x" + Screen.height + ")");
                TreeShot("tree_3440.png");
                treeWaitReal = now + 1f;
                break;
            case 19: Pad.Hold(Pad.B.Start, true); break;
            case 20:
                Pad.Hold(Pad.B.Start, false);
                TreeCheck(!up.Open, "startCloses");
                treeWaitReal = now + 1f;
                break;
            case 21:
                TreeShot("hud_3440.png");
                treeWaitReal = now + 1f;
                break;
            case 22:
                pm.SetOpen(true); pm.ShowSettings();
                pm.Change(PauseMenu.UiSizeRow, +1);                             // 125%
                treeWaitReal = now + 1f;
                break;
            case 23:
                TreeCheck(Mathf.Abs(Ui.Scale - 1440f / 1080f * 1.25f) < 0.01f, "uiSize125Scale=" + Ui.Scale.ToString("F2"));
                TreeShot("settings_3440.png");
                treeWaitReal = now + 1f;
                break;
            case 24:
                pm.Change(PauseMenu.UiSizeRow, -1);
                pm.SetOpen(false);
                TreeFinish(treeOk);
                break;
        }
    }

    // ---- the editor's game view size (for the pictures): through the editor's own (internal) game view sizes
    static object GameViewGroup(out System.Type groupType)
    {
        var asm = typeof(Editor).Assembly;
        var sizesType = asm.GetType("UnityEditor.GameViewSizes");
        var single = typeof(ScriptableSingleton<>).MakeGenericType(sizesType);
        var inst = single.GetProperty("instance").GetValue(null, null);
        var group = sizesType.GetProperty("currentGroup").GetValue(inst, null);
        groupType = group.GetType();
        return group;
    }

    static EditorWindow GameViewWindow()
    {
        var gvType = typeof(Editor).Assembly.GetType("UnityEditor.GameView");
        return EditorWindow.GetWindow(gvType, false, null, false);
    }

    static System.Reflection.PropertyInfo GameViewIndexProp(EditorWindow gv)
    {
        return gv.GetType().GetProperty("selectedSizeIndex", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic);
    }

    static int GameViewIndex()
    {
        try
        {
            var gv = GameViewWindow();
            var p = GameViewIndexProp(gv);
            return p != null ? (int)p.GetValue(gv, null) : -1;
        }
        catch (System.Exception e) { Debug.LogWarning("TreeTest: game view index: " + e.Message); return -1; }
    }

    static void GameViewSelect(int index)
    {
        var gv = GameViewWindow();
        var p = GameViewIndexProp(gv);
        if (p != null) p.SetValue(gv, index, null);
        else
        {
            var m = gv.GetType().GetMethod("SizeSelectionCallback", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic);
            if (m != null) m.Invoke(gv, new object[] { index, null });
        }
        gv.Repaint();
    }

    /// Sets the game view to a fixed w x h (adding the size to the list if it isn't there).  True if it worked.
    static bool GameViewSize(int w, int h)
    {
        try
        {
            System.Type groupType;
            var group = GameViewGroup(out groupType);
            int total = (int)groupType.GetMethod("GetTotalCount").Invoke(group, null);
            int index = -1;
            for (int i = 0; i < total; i++)
            {
                var sz = groupType.GetMethod("GetGameViewSize").Invoke(group, new object[] { i });
                var st = sz.GetType();
                if ((int)st.GetProperty("width").GetValue(sz, null) == w && (int)st.GetProperty("height").GetValue(sz, null) == h
                    && st.GetProperty("sizeType").GetValue(sz, null).ToString() == "FixedResolution") { index = i; break; }
            }
            if (index < 0)
            {
                var asm = typeof(Editor).Assembly;
                var sizeType = asm.GetType("UnityEditor.GameViewSize");
                var kind = asm.GetType("UnityEditor.GameViewSizeType");
                var ctor = sizeType.GetConstructor(new[] { kind, typeof(int), typeof(int), typeof(string) });
                var size = ctor.Invoke(new object[] { System.Enum.Parse(kind, "FixedResolution"), w, h, "Test " + w + "x" + h });
                groupType.GetMethod("AddCustomSize").Invoke(group, new[] { size });
                index = total;
            }
            GameViewSelect(index);
            return true;
        }
        catch (System.Exception e) { Debug.LogWarning("TreeTest: couldn't set the game view size: " + e); return false; }
    }

    // The game pad path:  -executeMethod BulldozerBuilder.PadTest
    // Drives everything through Pad's override (as if a pad were plugged in), with the dozer's and worker's own
    // overrides off.  In the dozer: the left stick drives, the left trigger raises the blade, and with the gyro button
    // (right stick click) held the right stick's position sets the blade's tilt and angle; let go and the blade stays.
    // Then Y gets out, and on foot: RB changes tool, the left stick walks, the right stick turns him, the right trigger
    // swings the tool.  Prints BULLDOZER_PAD_RESULT.
    static int padPhase; static float padStart; static string padLog; static Vector3 padPos; static float padHeight, padYaw, padTilt, padAngle;
    static int padTool; static bool padSwung;

    public static void PadTest()
    {
        EnsurePadAxes();
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        padPhase = 0; padLog = ""; padSwung = false;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += PadTick;
        EditorApplication.EnterPlaymode();
    }

    static void PadFinish(bool ok)
    {
        if (ok) Debug.Log("BULLDOZER_PAD_RESULT " + padLog);
        else Debug.LogError("BULLDOZER_PAD_FAILED phase " + padPhase + " " + padLog);
        Pad.overrideOn = false; Pad.ClearOverride();
        EditorApplication.update -= PadTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(ok ? 0 : 1);
    }

    static void PadTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { padLog += " timed out"; PadFinish(false); return; }
        if (!EditorApplication.isPlaying) return;
        var wk = Worker.Instance; var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        if (wk == null || d == null || VoxelWorld.Instance == null) return;
        float t = Time.time, since = t - padStart;
        switch (padPhase)
        {
            case 0:                                              // in the dozer: drive forward and raise the blade
                if (t < 1f) return;
                wk.useOverride = false; d.useOverride = false;
                if (!wk.InDozer) wk.TryDozer();
                if (!wk.InDozer) { padLog += "could not get in the dozer"; PadFinish(false); return; }
                Pad.ClearOverride(); Pad.overrideOn = true;
                padPos = d.transform.position; padHeight = d.BladeHeight01;
                Pad.oLY = 1f; Pad.oLT = 1f;
                padPhase = 1; padStart = t; return;
            case 1:
                if (since < 1.5f) return;
                float drove = Vector3.Distance(padPos, d.transform.position);
                padLog += "drove=" + drove.ToString("F2") + " bladeUp " + padHeight.ToString("F2") + "->" + d.BladeHeight01.ToString("F2") + " padInUse=" + Pad.InUse;
                if (drove < 0.5f || d.BladeHeight01 < padHeight + 0.2f || !Pad.InUse) { PadFinish(false); return; }
                Pad.oLY = 0f; Pad.oLT = 0f;
                padTilt = d.BladeTilt; padAngle = d.BladeYaw;
                Pad.Hold(Pad.B.RS, true);                        // the gyro button, stick in the middle
                padPhase = 2; padStart = t; return;
            case 2:
                if (since < 0.3f) return;
                Pad.oRX = 0.5f; Pad.oRY = -0.4f;                 // tip the controller: half right, a bit back
                padPhase = 3; padStart = t; return;
            case 3:
                if (since < 1.2f) return;
                {
                    float dz = d.gyroDeadZone;
                    float wantTilt = padTilt + (0.5f - dz) / (1f - dz) * d.bladeMaxTilt;
                    float wantAngle = padAngle - (0.4f - dz) / (1f - dz) * d.bladeMaxAngle;
                    padLog += " gyroTilt=" + d.BladeTilt.ToString("F2") + "(want " + wantTilt.ToString("F2") + ") gyroAngle=" + d.BladeYaw.ToString("F2") + "(want " + wantAngle.ToString("F2") + ") gyroHeld=" + d.GyroHeld;
                    if (!d.GyroHeld || Mathf.Abs(d.BladeTilt - wantTilt) > 0.3f || Mathf.Abs(d.BladeYaw - wantAngle) > 0.8f) { PadFinish(false); return; }
                }
                Pad.Hold(Pad.B.RS, false);                       // let go of the gyro button ...
                padTilt = d.BladeTilt; padAngle = d.BladeYaw;
                Pad.oRX = -1f; Pad.oRY = 1f;                     // ... and wave the stick about: the blade must stay
                padPhase = 4; padStart = t; return;
            case 4:
                if (since < 1f) return;
                padLog += " afterRelease tilt=" + d.BladeTilt.ToString("F2") + " angle=" + d.BladeYaw.ToString("F2");
                if (Mathf.Abs(d.BladeTilt - padTilt) > 0.01f || Mathf.Abs(d.BladeYaw - padAngle) > 0.01f) { PadFinish(false); return; }
                Pad.oRX = 0f; Pad.oRY = 0f;
                Pad.Hold(Pad.B.Y, true);                         // Y: get out
                padPhase = 5; padStart = t; return;
            case 5:
                if (since < 0.4f) return;
                Pad.Hold(Pad.B.Y, false);
                padLog += " outWithY=" + !wk.InDozer;
                if (wk.InDozer) { PadFinish(false); return; }
                padTool = wk.Tool;
                Pad.Hold(Pad.B.RB, true);                        // RB: next tool
                padPhase = 6; padStart = t; return;
            case 6:
                if (since < 0.3f) return;
                Pad.Hold(Pad.B.RB, false);
                padLog += " tool " + padTool + "->" + wk.Tool;
                if (wk.Tool == padTool) { PadFinish(false); return; }
                padPos = wk.transform.position; padYaw = wk.transform.eulerAngles.y;
                Pad.oLY = 1f; Pad.oRX = 0.7f;                    // walk on, turning right
                padPhase = 7; padStart = t; return;
            case 7:
                if (since < 1.2f) return;
                {
                    float walked = Vector3.Distance(new Vector3(padPos.x, 0f, padPos.z), new Vector3(wk.transform.position.x, 0f, wk.transform.position.z));
                    float turned = Mathf.Abs(Mathf.DeltaAngle(padYaw, wk.transform.eulerAngles.y));
                    padLog += " walked=" + walked.ToString("F2") + " turned=" + turned.ToString("F0");
                    if (walked < 0.5f || turned < 20f) { PadFinish(false); return; }
                }
                Pad.oLY = 0f; Pad.oRX = 0f; Pad.oRT = 1f;        // right trigger: use the tool
                padPhase = 8; padStart = t; return;
            case 8:
                if (wk.SwingNow != "None") padSwung = true;
                if (since < 0.8f) return;
                Pad.oRT = 0f;
                padLog += " swungWithRT=" + padSwung;
                PadFinish(padSwung);
                return;
        }
    }

    // ---------------------------------------------------------------- the Windows game
    // Builds the game on its own, for adding to Steam as a non-Steam game (so Steam Input works on it).
    //   -executeMethod BulldozerBuilder.BuildWindowsFromCommandLine     (or Tools > Bulldozer > Build Windows game)
    // Lands in voxel-dozer-unity/Builds/DiggerGame/DiggerGame.exe.  Prints BULLDOZER_WINBUILD_RESULT.
    const string WindowsExe = "Builds/DiggerGame/DiggerGame.exe";

    [MenuItem("Tools/Bulldozer/Build Windows game")]
    public static void BuildWindows() { BuildWindowsGame(); }

    public static void BuildWindowsFromCommandLine() { EditorApplication.Exit(BuildWindowsGame() ? 0 : 1); }

    static bool BuildWindowsGame()
    {
        EnsurePadAxes();
        // shaders the scripts look up by name at run time, which no material in the scene points at
        IncludeShaders("Voxel/FireFlame", "Voxel/FireParticle", "Voxel/FireSmoke", "Voxel/Terrain", "Unlit/Color", "Sprites/Default", "Standard");
        KeepInstancingShaders();
        var opts = new BuildPlayerOptions
        {
            scenes = new[] { ScenePath },
            locationPathName = System.Environment.GetEnvironmentVariable("DIGGER_BUILD_EXE") ?? WindowsExe,   // (a build somewhere else while the game is open)
            target = BuildTarget.StandaloneWindows64,
            options = BuildOptions.None,                           // not a Development build
        };
        var report = BuildPipeline.BuildPlayer(opts);
        bool ok = report.summary.result == UnityEditor.Build.Reporting.BuildResult.Succeeded;
        if (ok) Debug.Log("BULLDOZER_WINBUILD_RESULT " + System.IO.Path.GetFullPath(WindowsExe) + " " + (report.summary.totalSize / (1024 * 1024)) + " MB in " + report.summary.totalTime.TotalSeconds.ToString("F0") + " s");
        else Debug.LogError("BULLDOZER_WINBUILD_FAILED " + report.summary.result + " errors=" + report.summary.totalErrors);
        return ok;
    }

    // The loose dirt (clods) is drawn many at a time with instancing, from materials made in code.  No material saved
    // in the project uses instancing, so the build threw the shaders' instancing versions away and the dirt in the
    // built game was drawn as nothing (in the editor everything is kept, so it showed there).  Keep them all.
    static void KeepInstancingShaders()
    {
        var gs = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/GraphicsSettings.asset");
        if (gs == null || gs.Length == 0) return;
        var so = new SerializedObject(gs[0]);
        var p = so.FindProperty("m_InstancingStripping");
        if (p == null || p.intValue == 2) return;
        p.intValue = 2;                                            // 0 strip unused, 1 strip all, 2 keep all
        so.ApplyModifiedPropertiesWithoutUndo(); AssetDatabase.SaveAssets();
    }

    static void IncludeShaders(params string[] names)
    {
        var gs = AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/GraphicsSettings.asset");
        if (gs == null || gs.Length == 0) return;
        var so = new SerializedObject(gs[0]);
        var list = so.FindProperty("m_AlwaysIncludedShaders");
        bool changed = false;
        foreach (var n in names)
        {
            var sh = Shader.Find(n);
            if (sh == null) { Debug.LogWarning("Build: shader " + n + " not found"); continue; }
            bool have = false;
            for (int i = 0; i < list.arraySize && !have; i++) have = list.GetArrayElementAtIndex(i).objectReferenceValue == sh;
            if (have) continue;
            list.arraySize++;
            list.GetArrayElementAtIndex(list.arraySize - 1).objectReferenceValue = sh;
            changed = true;
        }
        if (changed) { so.ApplyModifiedPropertiesWithoutUndo(); AssetDatabase.SaveAssets(); }
    }

    // The jackhammer:  -executeMethod BulldozerBuilder.JackTest
    // Picks rock at Pick 5 for 4 s, then jackhammers rock (Jackhammer 1, biggest bite) for 4 s: it must break much
    // more.  Then breaks gold in the quartz seam with a big bite (some is smashed) and a small one (none is).
    // Prints BULLDOZER_JACK_RESULT.
    static int jPhase; static string jLog; static float jStart; static Vector3 jSpot, jStand; static int jFirm0, jPickBroke; static bool jSawHammer;
    static int jMaxDust, jMaxChips; static float jMaxShake; static bool jAimSteady = true; static Vector3 jAim0;

    public static void JackTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        jPhase = 0; jLog = ""; jSawHammer = false; jMaxDust = jMaxChips = 0; jMaxShake = 0f; jAimSteady = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += JackTick;
        EditorApplication.EnterPlaymode();
    }

    static void JackFinish(int code)
    {
        EditorApplication.update -= JackTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    /// Firm rock (rock, quartz, gold) in a 1.8 m box round a spot.
    static int FirmNear(VoxelWorld w, Vector3 c)
    {
        int n = 0;
        for (float x = -0.9f; x <= 0.9f; x += VoxelWorld.Voxel)
            for (float y = -0.9f; y <= 0.9f; y += VoxelWorld.Voxel)
                for (float z = -0.9f; z <= 0.9f; z += VoxelWorld.Voxel)
                {
                    byte m = w.MaterialAt(c + new Vector3(x, y, z));
                    if (m >= VoxelWorld.Rock && m <= VoxelWorld.Gold) n++;
                }
        return n;
    }

    /// Bare rock on top, with flat ground to stand on 1.3 m south of it.  Stands him there aiming at it.
    static bool StandAtRock(VoxelWorld w, Worker wk, Vector3 avoid)
    {
        for (float x = -30f; x <= 30f; x += 0.5f)
            for (float z = -30f; z <= 30f; z += 0.5f)
            {
                var p = new Vector3(x, 0f, z);
                if ((p - new Vector3(avoid.x, 0f, avoid.z)).sqrMagnitude < 16f) continue;
                float f = w.FloorAt(p + Vector3.up * 8f);
                if (w.MaterialAt(new Vector3(x, f - 0.03f, z)) != VoxelWorld.Rock) continue;
                if (w.MaterialAt(new Vector3(x, f - 0.6f, z)) != VoxelWorld.Rock) continue;
                var st = new Vector3(x, 0f, z - 1.3f);
                float fs = w.FloorAt(st + Vector3.up * 8f);
                if (Mathf.Abs(fs - f) > 0.25f || SiteProps.Blocks(st, 0.4f, true)) continue;
                jSpot = new Vector3(x, f, z); jStand = new Vector3(st.x, fs, st.z);
                Vector3 eye = new Vector3(st.x, fs + 1.6f, st.z), d = jSpot - eye, flat = new Vector3(d.x, 0f, d.z);
                wk.Teleport(new Vector3(st.x, fs, st.z), Facing(flat));
                wk.Look(Mathf.Atan2(-d.y, flat.magnitude) * Mathf.Rad2Deg);
                return true;
            }
        return false;
    }

    static void JackTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_JACK_FAILED timed out in phase " + jPhase + " " + jLog); JackFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var up = Upgrades.Instance;
        if (w == null || wk == null || up == null) return;
        float t = Time.time;
        if (wk.Hammering) jSawHammer = true;
        if (jPhase == 1 || jPhase == 2)
        {
            // work across a patch of the rock, as a player would, not one spot
            int k = Mathf.FloorToInt((t - jStart) / 0.45f);
            var target = jSpot + new Vector3((k % 4) * 0.33f - 0.5f, 0f, ((k / 4) % 4) * 0.33f - 0.5f);
            target.y = w.FloorAt(target + Vector3.up * 3f);
            Vector3 eye = jStand + Vector3.up * 1.6f, d = target - eye, flat = new Vector3(d.x, 0f, d.z);
            wk.Teleport(jStand, Facing(flat));
            wk.Look(Mathf.Atan2(-d.y, flat.magnitude) * Mathf.Rad2Deg);
        }
        if (jPhase == 0)
        {
            if (t < 1f) return;
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            up.SetLevel(Upgrades.Branch.Pick, 5);
            wk.SetTool(0);
            if (!StandAtRock(w, wk, new Vector3(999f, 0f, 999f))) { Debug.LogError("BULLDOZER_JACK_FAILED no bare rock found"); JackFinish(1); return; }
            jFirm0 = FirmNear(w, jSpot);
            wk.overrideUse = true;
            jPhase = 1; jStart = t;
            return;
        }
        if (jPhase == 1)
        {
            if (t - jStart < 4f) return;
            wk.overrideUse = false;
            jPickBroke = jFirm0 - FirmNear(w, jSpot);
            jLog += "pickAt=" + jSpot + " pickBroke=" + jPickBroke;
            Vector3 first = jSpot;
            up.SetLevel(Upgrades.Branch.Pick, 6);
            wk.SetJackSize(1f);
            wk.SetTool(0);
            if (!StandAtRock(w, wk, first)) { Debug.LogError("BULLDOZER_JACK_FAILED no second rock found " + jLog); JackFinish(1); return; }
            jFirm0 = FirmNear(w, jSpot);
            wk.overrideUse = true;
            jPhase = 2; jStart = t;
            return;
        }
        if (jPhase == 2)
        {
            int dN, cN, gN; JackFX.Alive(out dN, out cN, out gN);
            jMaxDust = Mathf.Max(jMaxDust, dN); jMaxChips = Mathf.Max(jMaxChips, cN);
            jMaxShake = Mathf.Max(jMaxShake, FollowCamera.LastShake);
            if (t - jStart < 4f) return;
            wk.overrideUse = false;
            jLog += " dust=" + jMaxDust + " chips=" + jMaxChips + " shake=" + jMaxShake.ToString("F3") + "m";
            int jackBroke = jFirm0 - FirmNear(w, jSpot);
            jLog += " jackAt=" + jSpot + " jackBroke=" + jackBroke + " hammered=" + jSawHammer + " goldShatteredWhileTesting=" + wk.GoldShattered;
            float bigShatter = wk.JackShatter; wk.SetJackSize(0f); float smallShatter = wk.JackShatter;
            jLog += " shatterBigBite=" + bigShatter.ToString("F2") + " shatterSmallBite=" + smallShatter.ToString("F2");
            // gold in the seam: break half of it with a big bite and half with a small one
            var gold = new System.Collections.Generic.List<Vector3>();
            for (float x = -40f; x <= 40f && gold.Count < 300; x += 0.5f)
                for (float z = -40f; z <= 40f && gold.Count < 300; z += 0.5f)
                {
                    float f = w.FloorAt(new Vector3(x, 8f, z));
                    for (float y = f - 4f; y < f; y += VoxelWorld.Voxel)
                        if (w.MaterialAt(new Vector3(x, y, z)) == VoxelWorld.Gold) { gold.Add(new Vector3(x, y, z)); break; }
                }
            int smashedBig = 0, smashedSmall = 0, brokeBig = 0, brokeSmall = 0, goldGoneBig = 0;
            for (int i = 0; i < gold.Count; i++)
            {
                bool wasGold = w.MaterialAt(gold[i]) == VoxelWorld.Gold;
                int broke = w.Pick(gold[i], 0.1f, Vector3.zero, i % 2 == 0 ? 0.4f : 0f);
                if (i % 2 == 0) { smashedBig += w.LastShattered; brokeBig += broke; if (wasGold && w.MaterialAt(gold[i]) != VoxelWorld.Gold) goldGoneBig++; }
                else { smashedSmall += w.LastShattered; brokeSmall += broke; }
            }
            jLog += " goldSpots=" + gold.Count + " smashedBigBite=" + smashedBig + " smashedSmallBite=" + smashedSmall + " brokeBig=" + brokeBig + " brokeSmall=" + brokeSmall + " goldSpotsBrokenBig=" + goldGoneBig;
            bool ok = jSawHammer && jackBroke > jPickBroke * 1.3f && jPickBroke > 0 && bigShatter > 0f && smallShatter == 0f && gold.Count > 10 && smashedSmall == 0
                && brokeBig > 0 && goldGoneBig > 20 && smashedBig > 0
                && jMaxDust > 5 && jMaxChips > 5 && jMaxShake > 0.004f && jMaxShake < 0.02f;
            if (!ok) { Debug.LogError("BULLDOZER_JACK_FAILED " + jLog); JackFinish(1); return; }
            jPhase = 3; jStart = t;
            return;
        }
        if (jPhase == 3)
        {
            // let go: no shake next frame, and the dust thins out within a few seconds
            if (t - jStart < 0.3f) return;
            if (FollowCamera.LastShake > 0f) { Debug.LogError("BULLDOZER_JACK_FAILED still shaking after letting go " + jLog); JackFinish(1); return; }
            if (t - jStart < 3f) return;
            int dN, cN, gN; JackFX.Alive(out dN, out cN, out gN);
            jLog += " dustAfter3s=" + dN + " chipsAfter3s=" + cN;
            bool ok = dN < jMaxDust / 3 + 2 && cN == 0;
            if (ok) Debug.Log("BULLDOZER_JACK_RESULT " + jLog);
            else Debug.LogError("BULLDOZER_JACK_FAILED " + jLog);
            JackFinish(ok ? 0 : 1);
        }
    }

    // Gold in his pockets:  -executeMethod BulldozerBuilder.PocketGoldTest    prints BULLDOZER_POCKETS_RESULT (or _FAILED)
    // Loose gold on the ground near the gold shed: E aimed at it puts it in his pockets, up to 20 L and no more, and
    // nothing else is taken; then E at the gold buyer's counter puts it all in the gold store.  Volume kept straight.
    static int pgPhase, pgLaid, pgStore0, pgPocket;
    static float pgT0;
    static long pgVolume0;
    static string pgLog;
    static bool pgOk;
    static Vector3 pgPatch;
    public static void PocketGoldTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        pgPhase = 0; pgLog = ""; pgOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += PocketGoldTick;
        EditorApplication.EnterPlaymode();
    }
    static void PgCheck(bool ok, string what) { pgLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) pgOk = false; }
    static void PocketGoldFinish(int code)
    {
        EditorApplication.update -= PocketGoldTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }
    static void PocketGoldTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_POCKETS_FAILED timed out in phase " + pgPhase + pgLog); PocketGoldFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var m = Money.Instance;
        if (w == null || wk == null || m == null || SiteProps.GoldShedFront == Vector3.zero) return;
        float t = Time.time;
        if (pgPhase == 0)
        {
            if (t < 2f) return;
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            Vector3 shed = SiteProps.GoldShedFront;
            Vector3 away = (new Vector3(0f, 0f, 0f) - shed); away.y = 0f;
            away = away.sqrMagnitude > 0.01f ? away.normalized : Vector3.forward;
            bStand = shed + away * 4f; bStand.y = w.FloorAt(bStand + Vector3.up * 3f);
            pgPatch = bStand + away * 1.4f;
            pgPatch.y = w.FloorAt(pgPatch + Vector3.up * 3f);
            pgLaid = w.TestLayGold(pgPatch, 0.3f, 2);
            pgVolume0 = w.CountSolid() + w.LoadVoxels;
            wk.PocketGold = 0;
            pgPhase = 1; pgT0 = t;
            return;
        }
        if (pgPhase == 1)
        {
            if (t - pgT0 < 0.5f) return;
            AimAt(wk, new Vector3(pgPatch.x, w.FloorAt(pgPatch + Vector3.up * 3f), pgPatch.z));
            for (int i = 0; i < 4; i++) wk.PressE();
            pgPocket = wk.PocketGold;
            pgLog += " laid=" + pgLaid + " pockets=" + pgPocket + "/" + Worker.PocketHolds + " (" + wk.PocketLitresNow.ToString("F1") + " L)";
            PgCheck(pgLaid > Worker.PocketHolds, "enoughLaid");
            PgCheck(pgPocket == Worker.PocketHolds, "pocketsFilledTo20L");
            wk.PressE();
            PgCheck(wk.PocketGold == pgPocket && wk.LastSaid.Contains("full"), "noMoreWhenFull");
            long vol = w.CountSolid() + w.LoadVoxels;
            pgLog += " volumeChange=" + (vol - pgVolume0);
            PgCheck(vol == pgVolume0, "volumeKept");
            pgPhase = 2; pgT0 = t;
            return;
        }
        if (pgPhase == 2)
        {
            if (t - pgT0 < 0.5f) return;
            wk.Teleport(SiteProps.GoldShedFront, 0f);
            pgStore0 = m.GoldStore;
            wk.PressE();
            pgLog += " store " + pgStore0 + " -> " + m.GoldStore;
            PgCheck(m.GoldStore == pgStore0 + pgPocket && wk.PocketGold == 0, "intoGoldStore");
            Debug.Log((pgOk ? "BULLDOZER_POCKETS_RESULT" : "BULLDOZER_POCKETS_FAILED") + pgLog);
            PocketGoldFinish(pgOk ? 0 : 1);
        }
    }

    // The rifle:  -executeMethod BulldozerBuilder.RifleTest    prints BULLDOZER_RIFLE_RESULT (or _FAILED)
    // On foot, 4 picks the rifle (it shows, the others hide); held fire shoots 8 a second; shots at the ground a few
    // metres off chip it (loose rubble, the dirt kept: no ground made or lost); a far shot (20 m) still reaches; the
    // bumpers go round to it and back; nothing costs money.
    static int rfPhase, rfShots0;
    static float rfT0;
    static long rfVolume0, rfCoins0;
    static string rfLog;
    static bool rfOk;
    public static void RifleTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        rfPhase = 0; rfLog = ""; rfOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += RifleTick;
        EditorApplication.EnterPlaymode();
    }
    static void RfCheck(bool ok, string what) { rfLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) rfOk = false; }
    static void RifleFinish(int code)
    {
        EditorApplication.update -= RifleTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }
    static void RifleTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 240) { Debug.LogError("BULLDOZER_RIFLE_FAILED timed out in phase " + rfPhase + rfLog); RifleFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var m = Money.Instance;
        if (w == null || wk == null || m == null || SiteProps.GoldShedFront == Vector3.zero) return;
        float t = Time.time;
        if (rfPhase == 0)
        {
            if (t < 2f) return;
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            wk.SetTool(3);
            var rifle = wk.transform.Find("Hold/Rifle");
            var pick = wk.transform.Find("Hold/Pick");
            RfCheck(wk.Tool == 3 && rifle != null && rifle.gameObject.activeSelf && (pick == null || !pick.gameObject.activeSelf), "rifleInHand");
            Vector3 shed = SiteProps.GoldShedFront;
            Vector3 away = -shed; away.y = 0f;
            away = away.sqrMagnitude > 0.01f ? away.normalized : Vector3.forward;
            bStand = shed + away * 4f; bStand.y = w.FloorAt(bStand + Vector3.up * 3f);
            Vector3 spot = bStand + away * 4f; spot.y = w.FloorAt(spot + Vector3.up * 3f);
            AimAt(wk, spot);
            rfVolume0 = w.CountSolid() + w.LoadVoxels;
            rfCoins0 = m.Coins;
            rfShots0 = Rifle.Shots;
            rfPhase = 1; rfT0 = t;
            return;
        }
        if (rfPhase == 1)
        {
            if (t - rfT0 < 0.3f) return;
            int chips0 = Rifle.Chips;
            for (int i = 0; i < 6; i++) wk.FireRifle();
            rfLog += " shots=" + (Rifle.Shots - rfShots0) + " chips=" + (Rifle.Chips - chips0);
            RfCheck(Rifle.Shots - rfShots0 == 6, "fires");
            RfCheck(Rifle.Chips - chips0 >= 3, "chipsTheGround");
            // held fire: about 8 a second
            wk.overrideUse = true;
            rfShots0 = Rifle.Shots;
            rfPhase = 2; rfT0 = t;
            return;
        }
        if (rfPhase == 2)
        {
            if (t - rfT0 < 1f) return;
            wk.overrideUse = false;
            int n = Rifle.Shots - rfShots0;
            rfLog += " heldOneSecond=" + n;
            RfCheck(n >= 6 && n <= 10, "eightASecond");
            // a far shot: 20 m out along the ground
            Vector3 dir = wk.transform.forward;
            Vector3 far = bStand + dir * 20f; far.y = w.FloorAt(far + Vector3.up * 6f);
            AimAt(wk, far);
            int chips0 = Rifle.Chips;
            wk.FireRifle();
            RfCheck(Rifle.Chips > chips0, "reachesFar");
            rfPhase = 3; rfT0 = t;
            return;
        }
        if (rfPhase == 3)
        {
            if (t - rfT0 < 5f) return;                       // let the chips land
            long vol = w.CountSolid() + w.LoadVoxels;
            rfLog += " volumeChange=" + (vol - rfVolume0);
            RfCheck(vol == rfVolume0, "dirtKept");
            RfCheck(m.Coins == rfCoins0, "free");
            wk.SetTool(0);
            RfCheck(wk.transform.Find("Hold/Rifle") != null && !wk.transform.Find("Hold/Rifle").gameObject.activeSelf, "putAway");
            Debug.Log((rfOk ? "BULLDOZER_RIFLE_RESULT" : "BULLDOZER_RIFLE_FAILED") + rfLog);
            RifleFinish(rfOk ? 0 : 1);
        }
    }

    // The backpack:  -executeMethod BulldozerBuilder.BackpackTest
    // Beside the cart: sucks at firm ground (must take nothing), picks a patch loose, sucks it up (must stop at
    // 500 litres), saves and loads (the load must come back), then squirts it into the cart with Q.
    // Volume must not change.  Prints BULLDOZER_PACK_RESULT.
    static int bPhase, bAimStep, bMaxPack, bPackSaved, bCart0;
    static float bPhaseStart, bNext;
    static long bVolume0;
    static string bLog;
    static Vector3 bStand, bSide, bPatch;

    public static void BackpackTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        bPhase = 0; bLog = ""; bMaxPack = 0;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += BackpackTick;
        EditorApplication.EnterPlaymode();
    }

    static void BackpackFinish(int code)
    {
        EditorApplication.update -= BackpackTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    /// Turns him (standing at bStand) to aim at a spot on the ground.
    static void AimAt(Worker wk, Vector3 target)
    {
        Vector3 eye = bStand + Vector3.up * 1.6f, d = target - eye;
        Vector3 flat = new Vector3(d.x, 0f, d.z);
        wk.Teleport(bStand, Facing(flat));
        wk.Look(Mathf.Atan2(-d.y, flat.magnitude) * Mathf.Rad2Deg);
    }

    static float Litres(int voxels) { return voxels * VoxelWorld.VoxelVolume * 1000f; }

    static void BackpackTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_PACK_FAILED timed out in phase " + bPhase + " " + bLog); BackpackFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var cart = MineCart.Instance;
        if (w == null || wk == null || cart == null || cart.Length <= 0f) return;
        float t = Time.time;
        if (w.PackVoxels > bMaxPack) bMaxPack = w.PackVoxels;
        if (bPhase == 0)
        {
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            bSide = cart.transform.right; bSide.y = 0f; bSide.Normalize();
            bStand = cart.transform.position + bSide * 1.5f;
            bPatch = cart.transform.position + bSide * 2.8f;
            bVolume0 = w.CountSolid() + w.LoadVoxels;
            if (Upgrades.Instance != null) Upgrades.Instance.SetLevel(Upgrades.Branch.Backpack, 4);   // 500 litres
            wk.SetTool(2);
            AimAt(wk, new Vector3(bPatch.x, w.FloorAt(bPatch + Vector3.up), bPatch.z));
            wk.overrideUse = true;                               // suck at firm ground: nothing should come
            bPhase = 1; bPhaseStart = t;
            return;
        }
        if (bPhase == 1)
        {
            if (t - bPhaseStart < 2.5f) return;
            wk.overrideUse = false;
            bLog += "firmGroundTaken=" + w.PackVoxels + "voxels";
            // break a patch of ground loose with the pick, as he would, and let it settle into loose rubble
            for (int i = 0; i < 12; i++)
            {
                Vector3 at = bPatch + cart.transform.forward * (-0.8f + (i % 3) * 0.8f) + bSide * (((i / 3) % 2) * 0.6f);
                at.y = w.FloorAt(at + Vector3.up) + (i < 6 ? 0.05f : -0.3f);
                w.Pick(at, 0.42f, Vector3.up * 0.3f);
            }
            bPhase = 2; bPhaseStart = t;
            return;
        }
        if (bPhase == 2)
        {
            if (t - bPhaseStart < 5f) return;
            bLog += " looseMade=" + (w.ClodCount) + "clodsStillMoving";
            wk.overrideUse = true;
            bAimStep = 0; bNext = t;
            bPhase = 3; bPhaseStart = t;
            return;
        }
        if (bPhase == 3)
        {
            // sweep the nozzle over the loose patch until the backpack is full
            if (t >= bNext)
            {
                bNext = t + 0.6f;
                Vector3 at = bPatch + cart.transform.forward * (-0.9f + (bAimStep % 4) * 0.6f) + bSide * (((bAimStep / 4) % 3) * 0.35f);
                at.y = w.FloorAt(at + Vector3.up);
                AimAt(wk, at);
                bAimStep++;
            }
            if (t - bPhaseStart > 3f && bLog.IndexOf("suckPic") < 0) { TestCapture("backpack_suck.png"); bLog += " suckPic"; }
            bool full = w.PackVoxels >= wk.packHolds - VoxelWorld.ClodVoxels;
            if (!full && t - bPhaseStart < 25f) return;
            wk.overrideUse = false;
            bLog += " packFull=" + full + " packLitres=" + Litres(w.PackVoxels).ToString("F0") + " suckTook=" + (t - bPhaseStart).ToString("F1") + "s"
                  + " sucked=" + Litres(wk.Sucked).ToString("F0") + "L";
            // keep sucking a while longer: nothing more may go in
            wk.overrideUse = true;
            bPhase = 4; bPhaseStart = t;
            return;
        }
        if (bPhase == 4)
        {
            if (t - bPhaseStart < 2f) return;
            wk.overrideUse = false;
            bLog += " maxPack=" + bMaxPack + "/" + wk.packHolds + " neverOver=" + (bMaxPack <= wk.packHolds);
            // save and load: the backpack's load must come back
            bPackSaved = w.PackVoxels;
            var ms = new System.IO.MemoryStream();
            var bw = new System.IO.BinaryWriter(ms);
            w.WriteSave(bw); bw.Flush();
            ms.Position = 0;
            w.ReadSave(new System.IO.BinaryReader(ms));
            bLog += " packAfterLoad=" + (w.PackVoxels == bPackSaved);
            // to the cart, and Q
            bCart0 = w.CartVoxels;
            AimAt(wk, cart.Mouth);
            wk.StartPour();
            bLog += " pourStarted=" + wk.Pouring;
            bPhase = 5; bPhaseStart = t;
            return;
        }
        if (bPhase == 5)
        {
            if (t - bPhaseStart > 0.8f && bLog.IndexOf("pourPic") < 0) { TestCapture("backpack_pour.png"); bLog += " pourPic"; }
            if (wk.Pouring && t - bPhaseStart < 15f) return;
            bLog += " pourTook=" + (t - bPhaseStart).ToString("F1") + "s";
            bPhase = 6; bPhaseStart = t;
            return;
        }
        if (bPhase == 6)
        {
            if (t - bPhaseStart < 3f) return;                       // let the last of it land in the tub
            bLog += " packLeft=" + Litres(w.PackVoxels).ToString("F0") + "L intoCart=" + Litres(w.CartVoxels - bCart0).ToString("F0") + "L of " + Litres(bPackSaved).ToString("F0") + "L"
                  + " missedCart=" + Litres(bPackSaved - (w.CartVoxels - bCart0) - w.PackVoxels).ToString("F0") + "L";
            bPhase = 7; bPhaseStart = t;
            return;
        }
        if (bPhase == 7)
        {
            if (t - bPhaseStart < 7f) return;
            long bChange = (w.CountSolid() + w.LoadVoxels) - bVolume0;
            bLog += " volumeChange=" + bChange;
            Debug.Log((bChange == 0 ? "BULLDOZER_PACK_RESULT " : "BULLDOZER_PACK_FAILED ") + bLog);
            BackpackFinish(bChange == 0 ? 0 : 1);
        }
    }

    // The motor cart:  -executeMethod BulldozerBuilder.MotorCartTest
    // Without the motor he can't ride.  Buys the Motor cart (Upgrades.SetLevel), fills the cart by the mine mouth,
    // rides it out to the dump under power (W), tips it with E while still on it and checks it pays what the load
    // was worth (as the hand cart does), drives back into the mine (S) until it stops, then gets off.
    // Prints BULLDOZER_MOTORCART_RESULT, or BULLDOZER_MOTORCART_FAILED if a check didn't hold.
    static int mPhase;
    static float mPhaseStart, mAlong0, mTopSpeed, mTipEnd;
    static long mCoins0;
    static double mExpected;
    static bool mOk;
    static string mLog;

    public static void MotorCartTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        mPhase = 0; mLog = ""; mOk = true; mTopSpeed = 0f;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += MotorCartTick;
        EditorApplication.EnterPlaymode();
    }

    static void MotorCartFinish(int code)
    {
        EditorApplication.update -= MotorCartTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    static void MCheck(string name, bool good) { mLog += " " + name + "=" + good; if (!good) mOk = false; }

    static void MotorCartTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_MOTORCART_FAILED timed out in phase " + mPhase + " " + mLog); MotorCartFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var cart = MineCart.Instance; var money = Money.Instance; var up = Upgrades.Instance;
        if (w == null || wk == null || cart == null || money == null || up == null || cart.Length <= 0f) return;
        float t = Time.time;
        if (mPhase == 0)
        {
            if (t < 1f) return;                                                  // let everything start
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            up.Reset(); money.Clear();
            Vector3 at, f;
            cart.HoldPlace(-1, out at, out f);
            wk.Teleport(at, Facing(f));
            MCheck("noRideWithoutMotor", !wk.RideCart() && !wk.RidingCart);
            up.SetLevel(Upgrades.Branch.Cart, Upgrades.MotorCartLevel);
            MCheck("motorOwned", cart.spec.motor && up.HasMotorCart);
            mLog += " speed=" + cart.spec.motorSpeed + " holdsL=" + (cart.capacity * VoxelWorld.VoxelVolume * 1000f).ToString("F0");
            wk.Teleport(cart.transform.position + cart.transform.right * 3.2f, Facing(-cart.transform.right));
            dSteps = 0; dNext = t;
            mPhase = 1; mPhaseStart = t;
            return;
        }
        if (mPhase == 1)
        {
            if (!FillCart(w, cart, t, 3000) && t - mPhaseStart < 20f) return;
            if (t - mPhaseStart < 2f) return;                                   // let the last clods land in it
            mExpected = CartWorth(w);
            mLog += " loaded=" + (w.CartVoxels * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L worth=" + mExpected.ToString("F1");
            var box = cart.transform.Find("Motor");
            MCheck("motorBoxShown", box != null && box.gameObject.activeSelf);
            mAlong0 = cart.Along;
            MCheck("startsAwayFromDump", !cart.AtDump);
            Vector3 at, f;
            cart.HoldPlace(-1, out at, out f);
            wk.Teleport(at, Facing(f));
            MCheck("getsOn", wk.RideCart() && wk.RidingCart);
            wk.overrideWalk = 1f;                                               // W: drive out
            mPhase = 2; mPhaseStart = t;
            return;
        }
        if (mPhase == 2)
        {
            mTopSpeed = Mathf.Max(mTopSpeed, cart.MotorSpeedNow);
            if (t - mPhaseStart > 1.5f && mLog.IndexOf("ridePic") < 0) { TestCapture("motor_cart_ride.png"); mLog += " ridePic"; }
            bool stopped = t - mPhaseStart > 1f && Mathf.Abs(cart.MotorSpeedNow) < 1e-3f;
            if (!stopped && t - mPhaseStart < 60f) return;
            float took = t - mPhaseStart;
            mLog += " rode=" + (cart.Along - mAlong0).ToString("F1") + "m in " + took.ToString("F1") + "s topSpeed=" + mTopSpeed.ToString("F2");
            MCheck("reachedDump", cart.AtDump);
            MCheck("atEndOfLine", cart.Along >= cart.EndLimit - 0.05f);
            MCheck("topSpeedOk", mTopSpeed > cart.spec.motorSpeed * 0.95f);
            Vector3 at, f;
            cart.RidePlace(out at, out f);
            MCheck("onFootboard", wk.RidingCart && Vector3.Distance(wk.transform.position, at) < 0.05f);
            wk.overrideWalk = 0f;
            mCoins0 = money.Coins;
            wk.PressE();                                                        // E at the dump: tip it, stay on
            MCheck("tipsAtDump", cart.Tipping);
            MCheck("staysOn", wk.RidingCart);
            mPhase = 3; mPhaseStart = t;
            return;
        }
        if (mPhase == 3)
        {
            if (t - mPhaseStart > 0.8f && mLog.IndexOf("tipPic") < 0) { TestCapture("motor_cart_tip.png"); mLog += " tipPic"; }
            if (cart.Tipping && t - mPhaseStart < 12f) { mTipEnd = t; return; }
            if (t - mTipEnd < 3.5f) return;                                    // the last of the stream is still falling in
            long paid = money.Coins - mCoins0;
            mLog += " paid=" + paid + " paidShare=" + (paid / System.Math.Max(1e-6, mExpected) * 100).ToString("F0") + "% leftInCart=" + w.CartVoxels;
            MCheck("paysLikeHandCart", System.Math.Abs(paid - mExpected) < 1.01 && paid > 0);
            up.SetLevel(Upgrades.Branch.Cart, Upgrades.MotorCartLevel + 2);
            mLog += " motor3Speed=" + cart.spec.motorSpeed;
            mAlong0 = cart.Along; mTopSpeed = 0f;
            wk.overrideWalk = -1f;                                              // S: back into the mine
            mPhase = 4; mPhaseStart = t;
            return;
        }
        if (mPhase == 4)
        {
            mTopSpeed = Mathf.Max(mTopSpeed, -cart.MotorSpeedNow);
            bool stopped = t - mPhaseStart > 1f && Mathf.Abs(cart.MotorSpeedNow) < 1e-3f;
            if (!stopped && t - mPhaseStart < 60f) return;
            wk.overrideWalk = 0f;
            mLog += " backIn=" + (mAlong0 - cart.Along).ToString("F1") + "m in " + (t - mPhaseStart).ToString("F1") + "s topSpeed=" + mTopSpeed.ToString("F2") + " along=" + cart.Along.ToString("F1") + " start=" + cart.StartLimit.ToString("F1");
            MCheck("droveBackIn", mAlong0 - cart.Along > 5f);
            MCheck("stoppedAtRubbleOrEnd", cart.Along <= cart.StartLimit + 0.05f || cart.RoomAhead(-1f) < 1.5f);
            TestCapture("motor_cart_back_in.png");
            wk.PressE();                                                        // E away from the dump: get off
            MCheck("getsOff", !wk.RidingCart && !cart.BlocksWalker(wk.transform.position));
            up.SetLevel(Upgrades.Branch.Cart, 2);
            MCheck("sellBackRemovesMotor", !cart.spec.motor);
            Debug.Log((mOk ? "BULLDOZER_MOTORCART_RESULT" : "BULLDOZER_MOTORCART_FAILED") + mLog);
            MotorCartFinish(mOk ? 0 : 1);
        }
    }

    // The automatic cart:  -executeMethod BulldozerBuilder.AutoCartTest
    // Without it, G does nothing.  Buys it through the tree (Upgrades.Buy: the coins and gold must come off), fills
    // the cart by the mine mouth, sends it (G), and checks that it reaches the dump, tips itself, pays what the
    // load was worth (dirt as coins, gold into the gold store, as a tip by hand), and comes back empty to where
    // it was sent from.  Then the upgrade level survives a save and load of the tree, selling it back mid-trip
    // stops the trip, and the refund is the full price.
    // Prints BULLDOZER_AUTOCART_RESULT, or BULLDOZER_AUTOCART_FAILED if a check didn't hold.
    static int acPhase;
    static float acPhaseStart, acAlong0, acMaxAlong, acTripEnd;
    static long acCoins0;
    static int acGold0, acGoldIn;
    static double acDirtWorth;
    static bool acOk;
    static string acLog;

    public static void AutoCartTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        acPhase = 0; acLog = ""; acOk = true; acMaxAlong = 0f;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += AutoCartTick;
        EditorApplication.EnterPlaymode();
    }

    static void AutoCartFinish(int code)
    {
        EditorApplication.update -= AutoCartTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    static void ACheck(string name, bool good) { acLog += " " + name + "=" + good; if (!good) acOk = false; }

    static void AutoCartTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_AUTOCART_FAILED timed out in phase " + acPhase + " " + acLog); AutoCartFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var cart = MineCart.Instance; var money = Money.Instance; var up = Upgrades.Instance;
        if (w == null || wk == null || cart == null || money == null || up == null || cart.Length <= 0f) return;
        float t = Time.time;
        if (acPhase == 0)
        {
            if (t < 1f) return;                                                  // let everything start
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            up.Reset(); money.Clear();
            wk.Teleport(cart.transform.position + cart.transform.right * 3.2f, Facing(-cart.transform.right));
            up.SetLevel(Upgrades.Branch.Cart, Upgrades.AutoCartLevel - 1);       // the level before it
            ACheck("noSendWithoutIt", !wk.SendCart() && !cart.OnTrip);
            money.TestGrant(5000, 400);
            long c0 = money.Coins; int g0 = money.GoldStore;
            ACheck("buys", up.Buy(Upgrades.Branch.Cart));
            acLog += " price=" + (c0 - money.Coins) + "c+" + (g0 - money.GoldStore) + "vox";
            ACheck("costTaken", money.Coins < c0 && money.GoldStore < g0);
            ACheck("autoOwned", cart.spec.auto && cart.spec.motor && up.HasAutoCart);
            ACheck("noSendEmpty", !wk.SendCart() && !cart.OnTrip);
            money.Clear();
            dSteps = 0; dNext = t;
            acPhase = 1; acPhaseStart = t;
            return;
        }
        if (acPhase == 1)
        {
            if (!FillCart(w, cart, t, 3000) && t - acPhaseStart < 20f) return;
            if (t - acPhaseStart < 2f) return;                                  // let the last clods land in it
            acDirtWorth = 0;
            for (int m = VoxelWorld.LooseSoil; m < VoxelWorld.LooseGold; m++) acDirtWorth += Money.ValueOf(m, w.CartLoadOf(m));
            acGoldIn = w.CartLoadOf(VoxelWorld.LooseGold);
            acLog += " loaded=" + (w.CartVoxels * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L dirtWorth=" + acDirtWorth.ToString("F1") + " goldIn=" + acGoldIn;
            acAlong0 = cart.Along; acMaxAlong = cart.Along;
            acCoins0 = money.Coins; acGold0 = money.GoldStore;
            ACheck("startsAwayFromDump", !cart.AtDump);
            ACheck("sends", wk.SendCart() && cart.OnTrip);
            ACheck("workerNotRiding", !wk.RidingCart && wk.HoldingCart == 0);
            acPhase = 2; acPhaseStart = t;
            return;
        }
        if (acPhase == 2)
        {
            acMaxAlong = Mathf.Max(acMaxAlong, cart.Along);
            if (t - acPhaseStart > 1.2f && acLog.IndexOf("outPic") < 0) { TestCapture("auto_cart_out.png"); acLog += " outPic"; }
            if (cart.TripState == MineCart.Trip.Tipping && acLog.IndexOf("tipPic") < 0 && t - acPhaseStart > 2f) { TestCapture("auto_cart_tip.png"); acLog += " tipPic"; }
            if (cart.OnTrip && t - acPhaseStart < 60f) { acTripEnd = t; return; }
            if (t - acTripEnd < 3.5f) return;                                   // the last of the stream is still falling in
            long paid = money.Coins - acCoins0;
            int gold = money.GoldStore - acGold0;
            acLog += " trip=" + (acTripEnd - acPhaseStart).ToString("F1") + "s reached=" + acMaxAlong.ToString("F1") + "/" + cart.EndLimit.ToString("F1") + " backAt=" + cart.Along.ToString("F2") + "/" + acAlong0.ToString("F2")
                   + " paid=" + paid + " goldStored=" + gold + " leftInCart=" + w.CartVoxels + " trips=" + cart.TripsDone;
            ACheck("tripEnded", !cart.OnTrip);
            ACheck("reachedDump", acMaxAlong >= cart.EndLimit - MineCart.DumpLength);
            ACheck("cameBack", Mathf.Abs(cart.Along - acAlong0) < 0.15f);
            ACheck("empty", w.CartVoxels < VoxelWorld.ClodVoxels);
            ACheck("paysLikeHandTip", paid >= acDirtWorth - 1.01 && paid <= acDirtWorth * 1.08 + 1.01);   // (a few spilled clods on the rails get scooped up on the way, as when pushed)
            ACheck("goldKept", gold == acGoldIn);
            TestCapture("auto_cart_back.png");

            // the upgrade level survives a save and load of the tree
            var ms = new System.IO.MemoryStream();
            up.WriteState(new System.IO.BinaryWriter(ms));
            up.Reset();
            ACheck("resetRemovesIt", !cart.spec.auto);
            ms.Position = 0;
            up.ReadState(new System.IO.BinaryReader(ms));
            ACheck("loadKeepsIt", cart.spec.auto && up.Level(Upgrades.Branch.Cart) == Upgrades.AutoCartLevel);

            // sent off again with a little in it, then sold back mid-trip: it stops, and the refund is the full price
            for (int k = 0; k < 6; k++) { w.Pick(cart.transform.position + cart.transform.right * 2.4f + Vector3.up * (0.1f - k * 0.1f), 0.35f, Vector3.zero); w.Scoop(cart.transform.position + cart.transform.right * 2.4f + Vector3.up * (0.1f - k * 0.1f), 0.5f, 4000); if (w.ShovelVoxels >= VoxelWorld.ClodVoxels) w.Throw(cart.Mouth + Vector3.up * 0.7f, Vector3.zero, 0.25f, 0.4f); }
            acPhase = 3; acPhaseStart = t;
            return;
        }
        if (acPhase == 3)
        {
            if (t - acPhaseStart < 2f) return;
            if (acLog.IndexOf(" resent=") < 0)
            {
                acLog += " resent=" + (w.CartVoxels >= VoxelWorld.ClodVoxels ? wk.SendCart() : false);
                acPhaseStart = t;
                return;
            }
            if (t - acPhaseStart < 1f) return;                                  // part way out
            long c0 = money.Coins; int g0 = money.GoldStore;
            ACheck("sellsBack", up.SellBack(Upgrades.Branch.Cart));
            acLog += " refund=" + (money.Coins - c0) + "c+" + (money.GoldStore - g0) + "vox";
            ACheck("sellBackStopsTrip", !cart.OnTrip && !cart.spec.auto && cart.spec.motor);
            ACheck("noSendAfterSellBack", !wk.SendCart());
            Debug.Log((acOk ? "BULLDOZER_AUTOCART_RESULT" : "BULLDOZER_AUTOCART_FAILED") + acLog);
            AutoCartFinish(acOk ? 0 : 1);
        }
    }

    // The bigger cart:  -executeMethod BulldozerBuilder.BigCartTest
    // Buys it after Motor cart 3 (750 coins, no gold): the tub holds 2,000 L and its extra boards show; it fills past
    // the old 1,500 L; it still drives to the dump and pays what the load was worth; sold back, it is 1,500 L again.
    // Prints BULLDOZER_BIGCART_RESULT, or BULLDOZER_BIGCART_FAILED if a check didn't hold.
    static int bgcPhase; static float bgcPhaseStart, bgcTipEnd; static long bgcCoins0; static double bgcWorth; static bool bgcOk; static string bgcLog;

    public static void BigCartTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        bgcPhase = 0; bgcLog = ""; bgcOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += BigCartTick;
        EditorApplication.EnterPlaymode();
    }
    static void BigCartFinish(int code) { EditorApplication.update -= BigCartTick; EditorSettings.enterPlayModeOptionsEnabled = false; EditorApplication.Exit(code); }
    static void BCheck(string name, bool good) { bgcLog += " " + name + "=" + good; if (!good) bgcOk = false; }

    static void BigCartTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_BIGCART_FAILED timed out in phase " + bgcPhase + " " + bgcLog); BigCartFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var cart = MineCart.Instance; var money = Money.Instance; var up = Upgrades.Instance;
        if (w == null || wk == null || cart == null || money == null || up == null || cart.Length <= 0f) return;
        float t = Time.time;
        if (bgcPhase == 0)
        {
            if (t < 1f) return;
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            up.Reset(); money.Clear();
            up.SetLevel(Upgrades.Branch.Cart, Upgrades.BigCartLevel - 1);        // Motor cart 3
            var boards = cart.transform.Find("Big tub");
            BCheck("boardsHiddenBefore", boards != null && !boards.gameObject.activeSelf);
            int before = cart.capacity;
            money.TestGrant(750, 0);
            BCheck("buysWithCoinsOnly", up.Buy(Upgrades.Branch.Cart) && money.Coins == 0);
            bgcLog += " holdsL=" + (before * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "->" + (cart.capacity * VoxelWorld.VoxelVolume * 1000f).ToString("F0");
            BCheck("bigger", cart.capacity == 8192 && before == 6144);
            BCheck("stillMotor", cart.spec.motor && !cart.spec.auto);
            wk.Teleport(cart.transform.position + cart.transform.right * 3.2f, Facing(-cart.transform.right));
            dSteps = 0; dNext = t;
            bgcPhase = 1; bgcPhaseStart = t;
            return;
        }
        if (bgcPhase == 1)
        {
            var boards = cart.transform.Find("Big tub");
            if (boards != null && boards.gameObject.activeSelf && bgcLog.IndexOf("boardsShown") < 0) BCheck("boardsShown", true);
            if (!FillCart(w, cart, t, 7000) && t - bgcPhaseStart < 40f) return;
            if (t - bgcPhaseStart < 2f) return;
            float l = w.CartVoxels * VoxelWorld.VoxelVolume * 1000f;
            bgcLog += " loaded=" + l.ToString("F0") + "L";
            BCheck("boardsShown", boards != null && boards.gameObject.activeSelf);
            BCheck("holdsMoreThan1500", l > 1550f);
            TestCapture("big_cart_full.png");
            bgcWorth = CartWorth(w);
            cart.SetAlong(cart.EndLimit);                                         // at the dump
            Vector3 at, f; cart.HoldPlace(-1, out at, out f); wk.Teleport(at, Facing(f));
            bgcCoins0 = money.Coins;
            wk.PressE();
            BCheck("tips", cart.Tipping);
            bgcPhase = 2; bgcPhaseStart = t;
            return;
        }
        if (bgcPhase == 2)
        {
            if (cart.Tipping && t - bgcPhaseStart < 20f) { bgcTipEnd = t; return; }
            if (t - bgcTipEnd < 3.5f) return;
            long paid = money.Coins - bgcCoins0;
            bgcLog += " paid=" + paid + " worth=" + bgcWorth.ToString("F1") + " left=" + w.CartVoxels;
            BCheck("paysForAll", System.Math.Abs(paid - bgcWorth) < 1.01 && w.CartVoxels < VoxelWorld.ClodVoxels);
            long c0 = money.Coins;
            BCheck("sellsBack", up.SellBack(Upgrades.Branch.Cart) && money.Coins - c0 == 750);
            BCheck("smallerAgain", cart.capacity == 6144);
            Debug.Log((bgcOk ? "BULLDOZER_BIGCART_RESULT" : "BULLDOZER_BIGCART_FAILED") + bgcLog);
            BigCartFinish(bgcOk ? 0 : 1);
        }
    }

    // The goal and the ending:  -executeMethod BulldozerBuilder.EndingTest
    // The ending doesn't play before the goal.  Goes through every goal (Goals.TestComplete, with the parts fitted and
    // every road stretch graded so the new goals are really true), and the ending starts by itself: the panels hide,
    // the camera flies up the road (pictures on the way and of the stats card), the stats count what went down the
    // hopper; "Keep playing" hands the camera back; it doesn't play again; and Shown and the totals survive a save
    // and load of its section.  Prints BULLDOZER_ENDING_RESULT, or BULLDOZER_ENDING_FAILED.
    static int enPhase; static float enT0; static bool enOk; static string enLog; static Vector3 enCam0;

    public static void EndingTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        enPhase = 0; enLog = ""; enOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += EndingTick;
        EditorApplication.EnterPlaymode();
    }
    static void EndingFinish(int code) { EditorApplication.update -= EndingTick; EditorSettings.enterPlayModeOptionsEnabled = false; EditorApplication.Exit(code); }
    static void ECheck(string name, bool good) { enLog += " " + name + "=" + good; if (!good) enOk = false; }

    static void EndingTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_ENDING_FAILED timed out in phase " + enPhase + " " + enLog); EndingFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var wk = Worker.Instance; var money = Money.Instance; var goals = Goals.Instance; var end = Ending.Instance; var finds = Finds.Instance; var road = MountainRoadJob.Instance;
        if (wk == null || money == null || goals == null || end == null || finds == null || road == null || Camera.main == null) return;
        float t = Time.time;
        switch (enPhase)
        {
            case 0:
                if (Time.timeSinceLevelLoad < 4f) return;
                wk.useOverride = true;
                money.Clear(); goals.Reset(); end.TestReset();
                ECheck("notBeforeGoal", !Ending.Playing && !Ending.GoalReached);
                // what goes down the hopper is counted for the stats: 4,096 voxels of soil (1 m3) and 41 of gold (10 L)
                var paid = new int[16]; paid[VoxelWorld.LooseSoil] = 4096; paid[VoxelWorld.LooseGold] = 41;
                money.Pay(paid);
                enLog += " sold=" + end.SoldLitres.ToString("F0") + "L gold=" + end.GoldFoundLitres.ToString("F1") + "L";
                ECheck("countsHopper", System.Math.Abs(end.SoldLitres - 1000.0) < 0.5 && end.GoldFoundLitres > 9.5 && end.GoldFoundLitres < 10.5);
                for (int k = 0; k < Finds.Count; k++) finds.SetState(k, true, true, true);
                for (int k = 0; k < MountainRoad.Stretches; k++) road.TestGradeStretch(k);
                road.Refresh();
                enLog += " ticked=" + road.TickedCount;
                for (int guard = 0; guard < 40 && goals.Current < Goals.List.Length; guard++) goals.TestComplete();
                ECheck("allGoalsDone", goals.DoneCount == Goals.List.Length && goals.IsDone("dozer_fixed") && goals.IsDone("road_done"));
                ECheck("goalReached", Ending.GoalReached);
                enCam0 = Camera.main.transform.position;
                enPhase = 1; enT0 = t;
                return;
            case 1:
                if (!Ending.Playing && t - enT0 < 3f) return;
                ECheck("startsByItself", Ending.Playing);
                ECheck("playerHeld", wk.useOverride);
                enPhase = 2; enT0 = t;
                return;
            case 2:
                if (t - enT0 > 4f && enLog.IndexOf("flyPic1") < 0) { TestCapture("ending_fly1.png"); enLog += " flyPic1"; }
                if (t - enT0 > 11f && enLog.IndexOf("flyPic2") < 0) { TestCapture("ending_fly2.png"); enLog += " flyPic2"; ECheck("cameraMoved", (Camera.main.transform.position - enCam0).magnitude > 10f); }
                if (t - enT0 > Ending.FlyFor + 4f && enLog.IndexOf("cardShot") < 0) { ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/ending_card_screen.png"); enLog += " cardShot"; }
                if (t - enT0 > 8f && enLog.IndexOf("capShot") < 0) { ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/ending_caption_screen.png"); enLog += " capShot"; }
                if (t - enT0 < Ending.FlyFor + 6f) return;
                TestCapture("ending_card.png");
                enLog += " stats=[" + string.Join(" | ", end.StatLines()) + "]";
                end.Finish();                                                     // "Keep playing"
                var follow = Camera.main.GetComponent<FollowCamera>();
                ECheck("handsBack", !Ending.Playing && follow != null && follow.enabled);
                enPhase = 3; enT0 = t;
                return;
            case 3:
                if (t - enT0 < 4f) return;
                ECheck("onlyOnce", !Ending.Playing && end.Shown);
                var ms = new System.IO.MemoryStream();
                end.WriteState(new System.IO.BinaryWriter(ms));
                double sold = end.SoldLitres;
                end.Clear();
                ECheck("clearForgets", !end.Shown && end.SoldLitres == 0);
                ms.Position = 0;
                end.ReadState(new System.IO.BinaryReader(ms));
                ECheck("loadKeeps", end.Shown && end.SoldLitres == sold);
                Debug.Log((enOk ? "BULLDOZER_ENDING_RESULT" : "BULLDOZER_ENDING_FAILED") + enLog);
                EndingFinish(enOk ? 0 : 1);
                return;
        }
    }

    // First-time hints:  -executeMethod BulldozerBuilder.HintsTest
    // With the computer's prefs left alone (Hints.TestNoPrefs), sets up each tip's moment in turn (in the dozer, on
    // foot, dirt on the shovel, coins for an upgrade, gold in the store, a half-full cart) and checks that each tip
    // comes up, one at a time, and never twice.  A picture of one.  Prints BULLDOZER_HINTS_RESULT, or _FAILED.
    static int hnPhase; static float hnT0; static bool hnOk; static string hnLog, hnLast; static List<string> hnSeq = new List<string>();
    static bool hnPrefBefore; static float hnDigAt;

    public static void HintsTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        hnPhase = 0; hnLog = ""; hnOk = true; hnLast = ""; hnSeq.Clear(); hnDigAt = -1f;
        Hints.TestNoPrefs = true;
        hnPrefBefore = PlayerPrefs.HasKey("hint.dig");
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += HintsTick;
        EditorApplication.EnterPlaymode();
    }
    static void HintsFinish(int code) { EditorApplication.update -= HintsTick; Hints.TestNoPrefs = false; EditorSettings.enterPlayModeOptionsEnabled = false; EditorApplication.Exit(code); }
    static void HCheck(string name, bool good) { hnLog += " " + name + "=" + good; if (!good) hnOk = false; }

    static void HintsTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_HINTS_FAILED timed out in phase " + hnPhase + " " + hnLog); HintsFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var cart = MineCart.Instance; var money = Money.Instance; var up = Upgrades.Instance; var h = Hints.Instance;
        if (w == null || wk == null || cart == null || money == null || up == null || h == null || cart.Length <= 0f) return;
        float t = Time.time;
        string now = h.ShowingId;
        if (now != hnLast) { if (now.Length > 0) hnSeq.Add(now); hnLast = now; }
        switch (hnPhase)
        {
            case 0:                                                     // in the dozer
                if (Time.timeSinceLevelLoad < 2f) return;
                wk.useOverride = true;
                up.Reset(); money.Clear(); h.TestForget(); hnSeq.Clear(); hnLast = "";
                if (!wk.InDozer) wk.GetIn();
                hnPhase = 1; hnT0 = t; return;
            case 1:
                if (h.ShowingId != "dozer" && t - hnT0 < 8f) return;
                TestCapture("hint_dozer.png");
                wk.GetOut();                                            // on foot: the digging tip
                hnPhase = 2; hnT0 = t; return;
            case 2:
                if (h.ShowingId == "dig" && hnDigAt < 0f) hnDigAt = t;
                if ((hnDigAt < 0f || t - hnDigAt < 2f) && t - hnT0 < 14f) return;
                ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/hint_dig_screen.png"); hnLog += " dbg[" + h.DebugLine + "]";
                wk.Teleport(cart.transform.position + cart.transform.right * 3.2f, Facing(-cart.transform.right));
                Vector3 at = cart.transform.position + cart.transform.right * 2.4f;
                w.Pick(at, 0.35f, Vector3.zero); w.Scoop(at, 0.5f, 400);   // dirt on the shovel: the cart tip
                hnPhase = 3; hnT0 = t; return;
            case 3:
                if (h.ShowingId != "cart" && t - hnT0 < 12f) return;
                money.TestGrant(100, 0);                                // can afford an upgrade
                hnPhase = 4; hnT0 = t; return;
            case 4:
                if (h.ShowingId != "upgrade" && t - hnT0 < 12f) return;
                money.TestGrant(0, 10);                                 // gold in the store
                hnPhase = 5; hnT0 = t; return;
            case 5:
                if (h.ShowingId != "gold" && t - hnT0 < 12f) return;
                dSteps = 0; dNext = t;
                hnPhase = 6; hnT0 = t; return;
            case 6:                                                     // half a cart: the hopper tip
                FillCart(w, cart, t, cart.capacity / 2 + 200);
                if (h.ShowingId != "hopper" && t - hnT0 < 30f) return;
                hnPhase = 7; hnT0 = t; return;
            case 7:                                                     // nothing comes twice
                if (t - hnT0 < 15f) return;
                hnLog += " seq=" + string.Join(",", hnSeq.ToArray());
                foreach (var id in new[] { "dozer", "dig", "cart", "upgrade", "gold", "hopper" })
                {
                    int n = 0; foreach (var s in hnSeq) if (s == id) n++;
                    HCheck(id + "Once", n == 1);
                }
                HCheck("prefsUntouched", PlayerPrefs.HasKey("hint.dig") == hnPrefBefore);
                Debug.Log((hnOk ? "BULLDOZER_HINTS_RESULT" : "BULLDOZER_HINTS_FAILED") + hnLog);
                HintsFinish(hnOk ? 0 : 1);
                return;
        }
    }

    // ---------------------------------------------------------------- the Dingo (Dingo.cs)
    //   -executeMethod BulldozerBuilder.DingoTest          prints BULLDOZER_DINGO_RESULT (or _FAILED)
    //   -executeMethod BulldozerBuilder.RecordDingoClip    the same run filmed: frames and overlay.ass go to Logs/clip
    // Locked until bought; buy it from the tree (after Shovel 6); get on; drive into the mine; dig the first cave-in;
    // carry each load out and tip it into the cart (3 loads); push the cart along; hit solid rock; get off.  Checks the
    // dirt adds up exactly and that it reached every place it was sent (never stuck).
    static int dgPhase, dgLoads, dgCartAtTip, dgBucketAtTip, dgCaught, dgCarried, dgWay, dgCartAt0;
    static float dgCartPark, dgAimNext, dgShovelLpm, dgFirstDig, dgLastTip;
    static float dgPhaseStart, dgDigStart, dgDigLitres, dgDigSeconds, dgAlong0, dgStuckFor, dgCartDeep;
    static long dgVol0;
    static string dgLog; static bool dgOk, dgFilming;
    static Vector3 dgLastPos; static float dgWindow, dgBackUntil; static int dgLane, dgRock0; static bool dgDigging;

    public static void DingoTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        dgFilming = false; DingoReset();
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += DingoTick;
        EditorApplication.EnterPlaymode();
    }

    public static void RecordDingoClip()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        dgFilming = true; DingoReset();
        chFrame = 0; chView0 = -1; sOverlay.Clear(); trCaps.Clear();
        string dir = Application.dataPath + "/../Logs/clip";
        if (System.IO.Directory.Exists(dir)) System.IO.Directory.Delete(dir, true);
        System.IO.Directory.CreateDirectory(dir);
        clipLastGameFrame = -1;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += DingoTick;
        EditorApplication.EnterPlaymode();
    }

    static void DingoReset() { dgDigging = false; dgLane = 0; dgFirstDig = -1f; dgPhase = 0; dgLoads = 0; dgLog = ""; dgOk = true; dgWay = 0; dgStuckFor = 0f; dgCaught = dgCarried = 0; dgDigLitres = dgDigSeconds = 0f; }

    static void DingoFinish(int code)
    {
        EditorApplication.update -= DingoTick;
        Time.captureFramerate = 0;
        if (dgFilming && chView0 >= 0) GameViewSelect(chView0);
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    static void DCheck(string name, bool good) { dgLog += " " + name + "=" + good; if (!good) dgOk = false; }
    static void DgNext(int p, float t) { dgPhase = p; dgPhaseStart = t; dgStuckFor = 0f; }

    // the autopilot: what a player would press
    static float DgErr(Dingo dg, Vector3 at) { Vector3 d = at - dg.transform.position; d.y = 0f; return Mathf.DeltaAngle(dg.transform.eulerAngles.y, Facing(d)); }
    static void DgArms(Dingo dg, float want) { float e = want - dg.ArmRaise; dg.overrideArms = Mathf.Abs(e) < 0.6f ? 0f : Mathf.Sign(e); }
    static void DgBucket(Dingo dg, float want) { float e = want - dg.BucketAngle; dg.overrideBucket = Mathf.Abs(e) < 1.5f ? 0f : Mathf.Sign(e); }
    static bool DgGoTo(Dingo dg, Vector3 at, float within)
    {
        Vector3 d = at - dg.transform.position; d.y = 0f;
        if (d.magnitude < within) { dg.overrideThrottle = 0f; dg.overrideSteer = 0f; return true; }
        float err = DgErr(dg, at);
        dg.overrideSteer = Mathf.Clamp(err / 25f, -1f, 1f);
        dg.overrideThrottle = Mathf.Abs(err) < 20f ? Mathf.Clamp(d.magnitude / 0.8f, 0.35f, 1f) : 0f;
        return false;
    }
    static bool DgFace(Dingo dg, float yawDeg)
    {
        float err = Mathf.DeltaAngle(dg.transform.eulerAngles.y, yawDeg);
        dg.overrideThrottle = 0f;
        dg.overrideSteer = Mathf.Abs(err) < 2.5f ? 0f : Mathf.Clamp(err / 20f, -1f, 1f);
        return Mathf.Abs(err) < 2.5f;
    }
    // stuck: told to drive for 6 s and it hasn't got anywhere
    static bool DgStuck(Dingo dg, float dt)
    {
        // over each second it is told to drive, it must get at least 4 cm (a bogged push still does)
        bool trying = Mathf.Abs(dg.overrideThrottle) > 0.1f;
        if (!trying) { dgWindow = 0f; dgLastPos = dg.transform.position; return false; }
        dgWindow += dt;
        if (dgWindow < 1f) return false;
        float moved = Vector3.Distance(dg.transform.position, dgLastPos);
        dgLastPos = dg.transform.position; dgWindow = 0f;
        if (moved < 0.04f) dgStuckFor += 1f; else dgStuckFor = 0f;
        return dgStuckFor >= 6f;
    }
    static long DgVolume(VoxelWorld w) { return w.SolidCount + w.LooseTotal() - w.StartTotal; }
    // a still from a set spot (the follow camera is put back after)
    static void DgShot(string file, Vector3 from, Vector3 at)
    {
        var cam = Camera.main; if (cam == null || dgFilming) return;
        var f = cam.GetComponent<FollowCamera>();
        Vector3 p0 = cam.transform.position; Quaternion r0 = cam.transform.rotation;
        cam.transform.SetPositionAndRotation(from, Quaternion.LookRotation(at - from));
        TestCapture(file);
        cam.transform.SetPositionAndRotation(p0, r0);
    }

    static void DingoTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > (dgFilming ? 900 : 480)) { Debug.LogError("BULLDOZER_DINGO_FAILED timed out in phase " + dgPhase + " " + dgLog); DingoFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var cart = MineCart.Instance; var money = Money.Instance; var up = Upgrades.Instance; var dg = Dingo.Instance;
        var cam = Camera.main;
        if (w == null || wk == null || cart == null || money == null || up == null || dg == null || cam == null || cart.Length <= 0f) return;
        if (dgFilming) { if (Time.frameCount == clipLastGameFrame) return; clipLastGameFrame = Time.frameCount; }
        float t = Time.time, k = t - dgPhaseStart, dt = Time.deltaTime;
        string title = "", cap = "";
        Vector3 inside = new Vector3(VoxelWorld.PortalX, 0f, VoxelWorld.PortalZ + 1.6f);    // just in the tunnel
        Vector3 mouth = new Vector3(VoxelWorld.PortalX, 0f, VoxelWorld.PortalZ - 1.2f);
        if (dgPhase == 0)
        {
            Application.runInBackground = true;                              // (play mode otherwise stalls when the window loses focus)
            if (t < 1.5f) return;
            if (dgFilming)
            {
                chView0 = GameViewIndex();
                GameViewSize(1920, 1080);
                Time.captureFramerate = 30;
            }
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            up.Reset(); money.Clear();
            dg.Park();
            dgLog += " parkedAt" + dg.transform.position.ToString("F1") + " overlap" + dg.OverlapNow;
            { Vector3 c = dg.transform.position; DgShot("dingo_parked.png", c + dg.transform.forward * 2.6f + dg.transform.right * 1.9f + Vector3.up * 1.5f, c + Vector3.up * 0.7f);
              DgShot("dingo_parked_back.png", c - dg.transform.forward * 2.6f - dg.transform.right * 1.5f + Vector3.up * 1.9f, c + Vector3.up * 0.8f); }
            wk.Teleport(dg.transform.position - dg.transform.right * 1.2f, dg.transform.eulerAngles.y);
            DCheck("lockedUntilBought", Dingo.TryBoard(wk) && !dg.Driven);
            DCheck("treeLockedBeforeShovel6", up.CantBuy(Upgrades.Branch.Dingo) == "Needs Shovel 6");
            up.SetLevel(Upgrades.Branch.Shovel, 6);
            up.SetLevel(Upgrades.Branch.Pick, 5);
            up.SetLevel(Upgrades.Branch.Cart, 2);                          // (1,500 L: by the time he can buy a Dingo he'd have it)
            dgCartPark = cart.Along;
            dgVol0 = DgVolume(w);
            // First the shovel, to compare: Pick 5 and Shovel 6 at the same cave-in, the cart pushed right up behind him
            // (the shovel's best case: every throw goes straight in, no trips).
            float deepZ = VoxelWorld.PortalZ + VoxelWorld.TunnelLength - 1.2f;   // where the rails start, deep in the tunnel
            cart.SetAlong(deepZ - (VoxelWorld.PortalZ + 0.6f));
            wk.Teleport(new Vector3(VoxelWorld.PortalX, 0f, VoxelWorld.PortalZ + 2.2f), 0f);
            wk.SetTool(1); wk.Look(26f);
            wk.overrideUse = true; wk.overrideWalk = 0f;
            dgCartAt0 = w.CartVoxels; dgAimNext = t;
            DgNext(10, t);
            return;
        }
        if (dgPhase == 10)
        {
            title = "First, by hand:  Pick 5 and Shovel 6";
            cap = "The same cave-in, the cart right behind him.  In the cart: " + ((w.CartVoxels - dgCartAt0) * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + " L";
            if (t >= dgAimNext)
            {
                dgAimNext = t + 0.3f;
                string ai = wk.AimInfo;
                bool reach = ai.Contains("inReach=True"), rock = ai.Contains("mat=3 ");
                wk.overrideWalk = reach ? 0f : 0.5f;
                if (rock && wk.Tool == 1 && w.ShovelVoxels < VoxelWorld.ClodVoxels) wk.SetTool(0);     // a boulder: the pick
                else if (!rock && wk.Tool == 0) wk.SetTool(1);
            }
            float since = t - dgPhaseStart;
            if (since > 45f || !cart.HasRoom)
            {
                wk.overrideUse = false; wk.overrideWalk = 0f;
                float litres = (w.CartVoxels - dgCartAt0) * VoxelWorld.VoxelVolume * 1000f;
                dgShovelLpm = litres / since * 60f;
                dgLog += " shovel6=" + dgShovelLpm.ToString("F0") + "L/min(" + litres.ToString("F0") + "L in " + since.ToString("F0") + "s)";
                cart.SetAlong(cart.EndLimit);                                      // (emptied at the dump, so the Dingo starts with an empty cart)
                cart.Tip();
                DgNext(11, t);
            }
            return;
        }
        if (dgPhase == 11)
        {
            if (cart.Tipping || k < 4f) return;
            cart.SetAlong(dgCartPark + 4.5f);                                     // the cart parked out of the mine door, so the Dingo can get in
            dgCartDeep = cart.transform.position.z + 0.85f;
            wk.SetTool(1);
            wk.Teleport(dg.transform.position - dg.transform.right * 1.2f, dg.transform.eulerAngles.y);
            money.TestGrant(2000, 200);
            long c0 = money.Coins; int g0 = money.GoldStore;
            DCheck("bought", up.Buy(Upgrades.Branch.Dingo) && up.HasDingo && dg.owned);
            dgLog += " paid=" + (c0 - money.Coins) + "c+" + ((g0 - money.GoldStore) * VoxelWorld.VoxelVolume * 1000f).ToString("F1") + "Lgold";
            DCheck("sellBackNeedsDingoGone", up.CantSellBack(Upgrades.Branch.Shovel) != null);
            DCheck("getsOn", Dingo.TryBoard(wk) && dg.Driven && Dingo.Working);
            DCheck("quickOn", dg.BoardSeconds < 0.5f);
            dg.useOverride = true;
            dgLastPos = dg.transform.position;
            DgNext(1, t);
            return;
        }
        if (dgPhase >= 1 && dgPhase <= 6 && dg.Driven && DgStuck(dg, dt)) { DCheck("stuck_phase" + dgPhase + "_way" + dgWay + "_at" + dg.transform.position.ToString("F2") + "_yaw" + dg.transform.eulerAngles.y.ToString("F0") + "_arm" + dg.ArmRaise.ToString("F0") + "_ov" + dg.OverlapWhy(dg.transform.eulerAngles.y).Replace(" ", "|") + "_" + dg.LastBlock + "_cartZ" + cart.transform.position.z.ToString("F2") + "_deep" + dgCartDeep.ToString("F2") + "_th" + dg.overrideThrottle.ToString("F1"), false); DgNext(9, t); }
        if (dgPhase == 1)
        {
            // drive to the mine door, then in, arms a little up so the bucket clears the ground
            title = "The Dingo: bought, and on";
            cap = k < 3f ? "From the upgrades, after Shovel 6:  1,000 coins and 12 L of gold.  Enter gets on" : "W / S drive, A / D turn on the spot.  Into the mine";
            DgArms(dg, 14f); DgBucket(dg, 0f);
            Vector3 at = dgWay == 0 ? mouth : inside;
            if (DgGoTo(dg, at, 0.35f)) dgWay++;
            if (dgWay >= 2) { dg.overrideThrottle = 0f; DgNext(2, t); }
            if (k > 40f) { DCheck("reachedMine", false); DgNext(9, t); }
        }
        else if (dgPhase == 2)
        {
            // face in, lower the bucket flat on the floor, drive into the cave-in until it is full
            title = "Digging the cave-in (load " + (dgLoads + 1) + ")";
            cap = "Bucket low and flat, drive in:  " + dg.Litres.ToString("F0") + " L  (" + Mathf.RoundToInt(dg.Fill01 * 100f) + "%)" + (dg.Bog < 0.75f ? "   labouring" : "");
            if (k > 60f) { DCheck("digTimedOut", false); DgNext(9, t); return; }
            DgBucket(dg, 0f);
            if (!dgDigging)
            {
                // get ready: face in, bucket flat on the floor
                bool faced = DgFace(dg, 0f);
                if (!faced) return;
                DgArms(dg, 0f);
                if (dg.ArmRaise > 1f) return;
                dgDigging = true; dgDigStart = t; dgRock0 = dg.RockHits; dgBackUntil = -1f;
                if (dgFirstDig < 0f) dgFirstDig = t;
            }
            DgArms(dg, 0f);
            // a solid boulder in the way (it clanks off it): back off a little and try the next lane over, as a player would
            if (dg.RockHits - dgRock0 >= 3) { dgLane = dgLane == 0 ? 1 : dgLane == 1 ? -1 : 0; dgRock0 = dg.RockHits; dgBackUntil = t + 0.9f; dgLog += " rockInTheWay>lane" + dgLane; }
            float laneX = VoxelWorld.PortalX + dgLane * 0.85f;
            float steer = Mathf.Clamp((laneX - dg.transform.position.x) * 1.2f + Mathf.DeltaAngle(dg.transform.eulerAngles.y, 0f) / 20f, -1f, 1f);
            dg.overrideSteer = steer * 0.6f;
            dg.overrideThrottle = t < dgBackUntil ? -0.8f : 1f;
            if (dgLoads == 0 && dg.Fill01 > 0.5f && dgLog.IndexOf("digPic") < 0) { dgLog += " digPic"; TestCapture("dingo_dig.png"); Vector3 c = dg.transform.position; DgShot("dingo_dig_side.png", c + dg.transform.right * 1.3f - dg.transform.forward * 0.6f + Vector3.up * 1.6f, c + dg.transform.forward * 1.2f + Vector3.up * 0.4f); }
            if (dg.Fill01 >= 0.95f || t - dgDigStart > 25f)
            {
                dg.overrideThrottle = 0f; dg.overrideSteer = 0f;
                dgDigLitres += dg.Litres; dgDigSeconds += t - dgDigStart;
                if (dgLoads == 0) dgLog += " firstLoad=" + dg.Litres.ToString("F0") + "L/" + (t - dgDigStart).ToString("F1") + "s";
                dgWay = 0; dgDigging = false;
                DgNext(3, t);
            }
        }
        else if (dgPhase == 3)
        {
            // curl back a little, lift, back out of the tunnel, turn round, go up to the deep end of the cart
            title = "Out to the cart";
            cap = "Curl back, arms up:  the bucket stays level, nothing spills.  " + dg.Litres.ToString("F0") + " L on board";
            DgBucket(dg, -12f);
            if (dgWay == 0)
            {
                DgArms(dg, 18f);
                dg.overrideSteer = 0f;
                dg.overrideThrottle = dg.transform.position.z > VoxelWorld.PortalZ - 1.4f ? -1f : 0f;
                if (dg.overrideThrottle == 0f) dgWay = 1;
            }
            else if (dgWay == 1) { DgArms(dg, 30f); if (DgFace(dg, 180f)) dgWay = 2; }
            else
            {
                DgArms(dg, 70f);
                Vector3 stop = new Vector3(VoxelWorld.PortalX, 0f, dgCartDeep + 0.74f);
                bool there = dg.transform.position.z < stop.z + 0.08f;
                if (!there) DgGoTo(dg, stop, 0.1f); else { dg.overrideThrottle = 0f; dg.overrideSteer = 0f; }
                if (there && dg.ArmRaise > 68.5f && DgFace(dg, 180f))
                {
                    dgCartAtTip = w.CartVoxels; dgBucketAtTip = w.BucketVoxels;
                    DgNext(4, t);
                }
            }
            if (k > 45f) { DCheck("reachedCart", false); DgNext(9, t); }
        }
        else if (dgPhase == 4)
        {
            title = "Tipping into the cart";
            cap = k < 3f ? "Tip (E):  it pours out over the tub.  With the bucket up the cart catches a little wider"
                         : "Tap E again to shake out the last of it.  Cart: " + (w.CartVoxels * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + " L";
            dg.overrideThrottle = 0f; dg.overrideSteer = 0f; dg.overrideArms = 0f;
            DgBucket(dg, k < 2.4f ? 60f : 78f);                               // tipped well over the tub, then right over to empty it
            if (dgLoads == 0 && k > 1.2f && dgLog.IndexOf("tipPic") < 0) { dgLog += " tipPic"; TestCapture("dingo_tip.png"); Vector3 c = dg.transform.position; DgShot("dingo_tip_side.png", c + dg.transform.right * 3.2f + Vector3.up * 2.2f, c + dg.transform.forward * 1.2f + Vector3.up * 1.2f); }
            if (k > 2.6f && k < 2.6f + dt * 1.5f) dg.TapTip();
            if (k > 3.4f && k < 3.4f + dt * 1.5f) dg.TapTip();
            if (k > 5.5f)
            {
                int got = w.CartVoxels - dgCartAtTip, carried = dgBucketAtTip - w.BucketVoxels;
                dgCaught += got; dgCarried += carried; dgLastTip = t;
                dgLoads++;
                dgLog += " load" + dgLoads + "=" + (carried * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L>cart" + (got * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L";
                if (dgLoads == 1) DCheck("bucketEmptied", w.BucketVoxels < VoxelWorld.ClodVoxels * 2);
                dgWay = 0;
                DgNext(dgLoads < 3 ? 5 : 6, t);
            }
        }
        else if (dgPhase == 5)
        {
            // back for another: bucket level, back off the cart, turn round and drive back in
            title = "Back for another";
            cap = "Three loads in this run.  About " + Mathf.RoundToInt(1000f / Dingo.BucketLitres) + " fill the cart";
            DgBucket(dg, 0f);
            if (dgWay == 0) { DgArms(dg, 30f); dg.overrideThrottle = dg.transform.position.z < dgCartDeep + 1.6f ? -0.7f : 0f; dg.overrideSteer = 0f; if (dg.overrideThrottle == 0f) dgWay = 1; }
            else if (dgWay == 1) { DgArms(dg, 14f); if (DgFace(dg, 0f)) dgWay = 2; }
            else if (DgGoTo(dg, inside, 0.35f)) { DgNext(2, t); }
            if (k > 45f) { DCheck("backIn", false); DgNext(9, t); }
        }
        else if (dgPhase == 6)
        {
            // push the cart along the rails: bucket level and low, so it meets the cart's end, and drive on
            title = "Pushing the cart";
            cap = "Bump it and drive on:  the Dingo pushes the cart along the rails, no getting off";
            DgBucket(dg, 0f);
            if (dgWay == 0) { DgArms(dg, 30f); dg.overrideSteer = 0f; dg.overrideThrottle = dg.transform.position.z < dgCartDeep + 1.5f ? -0.6f : 0f; if (dg.overrideThrottle == 0f) dgWay = 1; }   // off the cart first
            else if (dgWay == 1) { dgAlong0 = cart.Along; DgArms(dg, 6f); if (Mathf.Abs(dg.ArmRaise - 6f) < 1.3f) { dgWay = 2; dgPhaseStart = t; } }
            else
            {
                dg.overrideArms = 0f;
                dg.overrideSteer = Mathf.Clamp((dg.transform.position.x - VoxelWorld.PortalX) * 0.8f + Mathf.DeltaAngle(dg.transform.eulerAngles.y, 180f) / 20f, -1f, 1f) * 0.6f;
                dg.overrideThrottle = 0.8f;
                if (k > 7f)
                {
                    dg.overrideThrottle = 0f;
                    float pushed = cart.Along - dgAlong0;
                    dgLog += " cartPushed=" + pushed.ToString("F2") + "m" + (cart.AtDump ? "(to the dump)" : "");
                    DCheck("pushesCart", pushed > 1.5f || (pushed > 0.5f && cart.AtDump));
                    DgNext(7, t);
                }
            }
        }
        else if (dgPhase == 7)
        {
            // solid rock: the bare rock patch on the floor.  Bucket down below the tracks, drive in: it stops with a clank.
            title = "Solid rock stops it";
            cap = "The edge won't cut solid rock:  a clank, sparks and a kick back.  That still needs the jackhammer";
            if (k < dt * 1.5f) { dg.Place(new Vector3(VoxelWorld.RockPadX - 3f, 0f, VoxelWorld.RockPadZ), 90f); dgWay = 0; }
            DgBucket(dg, 6f);
            DgArms(dg, -6f);
            dg.overrideSteer = 0f;
            dg.overrideThrottle = k > 1.2f ? 1f : 0f;
            if (k > 6f)
            {
                dg.overrideThrottle = 0f; dg.overrideArms = 0f; dg.overrideBucket = 0f;
                dgLog += " rockHits=" + dg.RockHits;
                DCheck("rockStopsIt", dg.RockHits > 0);
                DgNext(8, t);
            }
        }
        else if (dgPhase == 8)
        {
            title = "Off again";
            cap = "Enter gets off.  It stays where you leave it";
            if (k > 1.5f && dg.Driven)
            {
                Dingo.TryBoard(wk);
                DCheck("getsOff", !dg.Driven && !Dingo.Working && w.MaterialAt(wk.transform.position + Vector3.up * 1f) == VoxelWorld.Air);
            }
            if (k > 4f) DgNext(9, t);
        }
        else if (dgPhase == 9)
        {
            dg.overrideThrottle = dg.overrideSteer = dg.overrideArms = dg.overrideBucket = 0f;
            if (k < 2.5f) return;                                             // let the last clods settle
            long vol = DgVolume(w);
            long solid = w.CountSolid();
            dgLog += " loads=" + dgLoads + " dugL=" + dgDigLitres.ToString("F0") + " digSec=" + dgDigSeconds.ToString("F1")
                   + " carriedL=" + (dgCarried * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + " caughtL=" + (dgCaught * VoxelWorld.VoxelVolume * 1000f).ToString("F0")
                   + " volumeChange=" + (vol - dgVol0) + " solidCounted=" + (solid == w.SolidCount) + " lost=" + w.TotalLost;
            if (dgFirstDig >= 0f && dgLastTip > dgFirstDig)
            {
                float lpm = dgCaught * VoxelWorld.VoxelVolume * 1000f / (dgLastTip - dgFirstDig) * 60f;
                dgLog += " dingo=" + lpm.ToString("F0") + "L/min(into the cart, first dig to last tip, trips included)";
                dgLog += " faster=" + (lpm > dgShovelLpm ? "Dingo x" + (lpm / Mathf.Max(1f, dgShovelLpm)).ToString("F1") : "SHOVEL x" + (dgShovelLpm / Mathf.Max(1f, lpm)).ToString("F1"));
            }
            DCheck("threeLoads", dgLoads >= 3);
            DCheck("loadsNearlyFull", dgLoads > 0 && dgCarried / (float)dgLoads > Dingo.Capacity * 0.7f);
            DCheck("cartCaughtMost", dgCarried > 0 && dgCaught >= dgCarried * 0.8f);
            DCheck("volumeExact", vol == dgVol0 && solid == w.SolidCount && w.TotalLost == 0);
            if (dgFilming) { WriteOverlay(); Debug.Log("BULLDOZER_DINGO_CLIP_OK frames=" + chFrame + dgLog); DingoFinish(0); return; }
            Debug.Log((dgOk ? "BULLDOZER_DINGO_RESULT" : "BULLDOZER_DINGO_FAILED") + dgLog);
            DingoFinish(dgOk ? 0 : 1);
            return;
        }
        if (dgFilming)
        {
            float a0 = chFrame / 30f, b0 = (chFrame + 1) / 30f;
            string at = AssTime(a0) + "," + AssTime(b0);
            if (title.Length > 0) sOverlay.Add("Dialogue: 0," + at + ",Title,,0,0,0,," + AssEsc(title));
            if (cap.Length > 0) sOverlay.Add("Dialogue: 0," + at + ",Caption,,0,0,0,," + AssEsc(cap));
            ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/clip/frame_" + chFrame.ToString("D4") + ".png");
            chFrame++;
        }
    }

    // Save and load:  -executeMethod BulldozerBuilder.SaveTest
    // Digs, saves, digs more and changes things, loads, and checks everything came back exactly as saved.
    // Prints BULLDOZER_SAVE_RESULT.
    static int sPhase;
    static float sPhaseStart, sAlongSaved;
    static long sVolume0, sSolidSaved, sLooseSaved;
    static ulong sTopSaved;
    static int sClodsSaved, sTouchedSaved;
    static Vector3 sDozerSaved;
    static string sLog;

    public static void SaveTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        sPhase = 0; sLog = "";
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += SaveTick;
        EditorApplication.EnterPlaymode();
    }

    static void SaveFinish(int code)
    {
        EditorApplication.update -= SaveTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

    static void SaveTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_SAVE_FAILED timed out in phase " + sPhase + " " + sLog); SaveFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var cart = MineCart.Instance; var finds = Finds.Instance; var sg = SaveGame.Instance;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        if (w == null || wk == null || cart == null || finds == null || sg == null || d == null || cart.Length <= 0f) return;
        float t = Time.time;
        if (sPhase == 0)
        {
            wk.useOverride = true;
            if (!wk.InDozer) wk.GetIn();
            sVolume0 = w.CountSolid() + w.LooseTotal();
            d.useOverride = true; d.overrideBlade = -1f; d.overrideThrottle = 1f;      // dig a pass
            sPhase = 1; sPhaseStart = t;
            return;
        }
        if (sPhase == 1)
        {
            if (t - sPhaseStart < 5f) return;
            d.overrideThrottle = 0f;                                               // stop, with loose dirt still moving
            cart.SetAlong(cart.Along - 2f);
            finds.Collect(1);
            string msg = sg.Save();
            sSolidSaved = w.CountSolid(); sLooseSaved = w.LooseTotal(); sTopSaved = w.TopHash();
            sClodsSaved = w.ClodCount; sTouchedSaved = w.TouchedChunks();
            sDozerSaved = d.transform.position; sAlongSaved = cart.Along;
            sLog += "save=[" + msg + "] bytes=" + sg.LastBytes + " saveMs=" + sg.LastMs.ToString("F0") + " touchedChunks=" + sTouchedSaved + " clodsAtSave=" + sClodsSaved;
            // now change everything: dig on, turn, move the cart, fit a part
            d.overrideThrottle = 1f; d.overrideSteer = 0.6f; d.overrideAngle = 1f;
            cart.SetAlong(cart.Along + 6f);
            finds.Install(2);
            sPhase = 2; sPhaseStart = t;
            return;
        }
        if (sPhase == 2)
        {
            if (t - sPhaseStart < 4f) return;
            d.overrideThrottle = 0f; d.overrideSteer = 0f; d.overrideAngle = 0f;
            sLog += " changedBeforeLoad=" + (w.TopHash() != sTopSaved);
            string msg = sg.Load();
            sLog += " load=[" + msg + "] loadMs=" + sg.LastMs.ToString("F0")
                  + " solidSame=" + (w.CountSolid() == sSolidSaved) + " looseSame=" + (w.LooseTotal() == sLooseSaved)
                  + " groundSame=" + (w.TopHash() == sTopSaved) + " clodsSame=" + (w.ClodCount == sClodsSaved)
                  + " touchedSame=" + (w.TouchedChunks() == sTouchedSaved)
                  + " dozerBack=" + (Vector3.Distance(d.transform.position, sDozerSaved) < 0.01f)
                  + " cartBack=" + (Mathf.Abs(cart.Along - sAlongSaved) < 0.001f)
                  + " findsBack=" + (finds.Collected[1] && !finds.Installed[1] && !finds.Collected[2] && !finds.Installed[2])
                  + " stillInDozer=" + wk.InDozer;
            sPhase = 3; sPhaseStart = t;
            return;
        }
        if (sPhase == 3)
        {
            if (t - sPhaseStart < 5f) return;                                    // play on a little after the load
            sLog += " volumeChangeOverall=" + ((w.CountSolid() + w.LooseTotal()) - sVolume0);
            Debug.Log("BULLDOZER_SAVE_RESULT " + sLog);
            SaveFinish(0);
        }
    }

    /// Puts the worker just off one end of the cart, facing along the track, walking into it.
    static void StandAtEnd(Worker wk, MineCart cart, bool front)
    {
        Vector3 f = cart.transform.forward; f.y = 0f; f.Normalize();
        Vector3 at = cart.transform.position + f * (front ? 1.45f : -1.45f);
        wk.Teleport(at, Facing(front ? -f : f));
        cGrabbed = wk.GrabCart();
        wk.overrideWalk = 1f;
    }

    static void CartTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_CART_FAILED timed out in phase " + cPhase + " gameTime=" + Time.time + " frames=" + Time.frameCount + " clods=" + (VoxelWorld.Instance != null ? VoxelWorld.Instance.ClodCount : -1) + " " + cLog); CartFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var cart = MineCart.Instance;
        if (w == null || wk == null || cart == null || cart.Length <= 0f) return;
        float t = Time.time;
        if (cPhase == 0)
        {
            // first a picture of the mine entrance from beside the cart, as the owner sees it on foot
            if (wk.InDozer) wk.GetOut();
            wk.useOverride = true;
            Vector3 inward = -cart.transform.forward; inward.y = 0f; inward.Normalize();
            wk.Teleport(cart.transform.position + cart.transform.right * 1.3f - inward * 1.2f, Facing(inward));
            wk.Look(8f);
            cPhase = 20; cPhaseStart = t;
            return;
        }
        if (cPhase == 20)
        {
            if (t - cPhaseStart < 1.5f) return;
            TestCapture("entrance.png");
            wk.transform.Find("Model").gameObject.SetActive(false);
            wk.transform.Find("Hold").gameObject.SetActive(false);
            TestCapture("entrance_nobody.png");
            wk.transform.Find("Model").gameObject.SetActive(true);
            wk.transform.Find("Hold").gameObject.SetActive(true);
            cPhase = 21;
            return;
        }
        if (cPhase == 21)
        {
            cVolume0 = w.CountSolid() + w.LoadVoxels;
            cAlong0 = cart.Along;
            cLog += "spec=" + cart.spec.name + "/" + cart.capacity + " startAlong=" + cAlong0.ToString("F1") + "m";
            StandAtEnd(wk, cart, true);                         // the front end faces out of the mine: push it back in
            cLastAlong = cart.Along; cStillFor = 0f;
            cPhase = 1; cPhaseStart = t;
            return;
        }
        if (cPhase == 1)
        {
            // pushed into the mine: it should roll in, then stop at the cave-in and stay stopped
            float dt = Time.deltaTime;
            if (Mathf.Abs(cart.Along - cLastAlong) < 0.001f) cStillFor += dt; else cStillFor = 0f;
            cLastAlong = cart.Along;
            if (t - cPhaseStart < 9f) return;
            Vector3 front = cart.transform.position - cart.transform.forward * 1.05f + Vector3.up * 0.55f;
            cLog += " grabbed=" + cGrabbed + " leaning=" + (wk.HoldingCart != 0) + " pushedIn=" + (cAlong0 - cart.Along).ToString("F2") + "m stoppedFor=" + cStillFor.ToString("F1") + "s"
                  + " stopsAtRubble=" + cart.Blocked(cart.Along - 0.03f, -1f)
                  + " cartZ=" + cart.transform.position.z.ToString("F1") + " caveInStartsZ=" + (VoxelWorld.PortalZ + 2.6f).ToString("F1")
                  + " gapToFace=" + cart.RoomAhead(-1f).ToString("F2") + "m";
            TestCapture("cart_push.png");
            wk.overrideWalk = 0f;
            wk.LetGo();
            // stand beside the cart at the face and dig it with real shovel swings: each load should go in the cart
            Vector3 inward = -cart.transform.forward;
            wk.Teleport(cart.transform.position + cart.transform.right * 1.0f + inward * 0.7f, Facing(inward));
            wk.Look(28f);
            wk.SetTool(1);
            cThrows0 = wk.Throws; cScoops0 = wk.Scoops; cCart0 = w.CartVoxels;
            wk.overrideUse = true;
            cPhase = 10; cPhaseStart = t;
            return;
        }
        if (cPhase == 10)
        {
            // swap to the pick now and then, to loosen the face
            float k = t - cPhaseStart;
            int want = (k % 4f) < 0.9f ? 0 : 1;
            if (wk.Tool != want) wk.SetTool(want);
            if (k < 14f) return;
            wk.overrideUse = false;
            cLog += " faceScoops=" + (wk.Scoops - cScoops0) + " faceThrows=" + (wk.Throws - cThrows0)
                  + " intoCart=" + ((w.CartVoxels - cCart0) * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L"
                  + " workerAt=" + (wk.transform.position - cart.transform.position).magnitude.ToString("F2") + "m";
            // step back out of the face, beside the cart and a little behind it, to picture the load in it
            wk.SetTool(1);
            wk.Teleport(cart.transform.position + cart.transform.right * 1.0f + cart.transform.forward * 2.2f, Facing(-cart.transform.forward) - 15f);
            wk.Look(35f);
            cPhase = 11; cPhaseStart = t;
            return;
        }
        if (cPhase == 11)
        {
            if (t - cPhaseStart < 2f) return;
            TestCapture("cart_load.png");
            // now the far end of the line
            cart.SetAlong(cart.EndLimit - 3f);
            StandAtEnd(wk, cart, false);
            cPhase = 2; cPhaseStart = t;
            return;
        }
        if (cPhase == 2)
        {
            if (t - cPhaseStart < 6f) return;
            cLog += " grabbed2=" + cGrabbed + " atEndOfLine=" + (Mathf.Abs(cart.Along - cart.EndLimit) < 0.02f) + " neverPast=" + (cart.Along <= cart.EndLimit + 0.001f);
            wk.overrideWalk = 0f;
            wk.LetGo();
            // walking into it without holding it: it must not move
            cNoGrabFrom = cart.Along;
            StandAtEnd(wk, cart, true); wk.LetGo(); wk.overrideWalk = 1f;
            cPhase = 12; cPhaseStart = t;
            return;
        }
        if (cPhase == 12)
        {
            if (t - cPhaseStart < 2f) return;
            cLog += " walkIntoItMoved=" + Mathf.Abs(cart.Along - cNoGrabFrom).ToString("F2") + "m";
            wk.overrideWalk = 0f;
            // back by the mine entrance, then fill it
            cart.SetAlong(cAlong0);
            wk.Teleport(cart.transform.position + cart.transform.right * 3.2f, Facing(-cart.transform.right));
            cFillSteps = 0; cNext = t;
            cPhase = 3; cPhaseStart = t;
            return;
        }
        if (cPhase == 3)
        {
            // dig the ground beside it and drop each load into the tub
            if (w.CartVoxels >= 2400 || t - cPhaseStart > 15f) { cLog += " filled=" + (w.CartVoxels * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L"; cPhase = 4; cPhaseStart = t; return; }
            if (t < cNext) return;
            cNext = t + 0.08f;
            Vector3 side = cart.transform.right;
            Vector3 at = cart.transform.position + side * 2.4f + cart.transform.forward * (-1f + (cFillSteps % 9) * 0.25f) + Vector3.up * (0.1f - (cFillSteps / 9) * 0.12f);
            cFillSteps++;
            w.Pick(at, 0.35f, Vector3.zero);
            w.Scoop(at, 0.5f, 4000);
            if (w.ShovelVoxels >= VoxelWorld.ClodVoxels) w.Throw(cart.Mouth + Vector3.up * 0.7f, Vector3.zero, 0.25f, 0.4f);
            return;
        }
        if (cPhase == 4)
        {
            if (t - cPhaseStart < 2f) return;                                  // let the last of it land
            if (cPhase == 4 && cNext >= 0f)
            {
                // a close look down into the full cart, in daylight
                wk.Teleport(cart.transform.position + cart.transform.right * 1.6f - cart.transform.forward * 1.6f, Facing(cart.transform.position - wk.transform.position));
                wk.Look(38f);
                cNext = -1f; cPhaseStart = t - 1f;
                return;
            }
            TestCapture("cart_full.png");
            cLog += " loadShown=" + (cart.transform.Find("Load") != null && cart.transform.Find("Load").gameObject.activeSelf)
                  + " loadTop=" + (cart.transform.Find("Load").localPosition.y + cart.transform.Find("Load").localScale.y * 0.5f).ToString("F2") + "m";
            cLog += " beforeTip=" + (w.CartVoxels * VoxelWorld.VoxelVolume * 1000f).ToString("F0") + "L";
            cart.Tip();
            cPhase = 5; cPhaseStart = t;
            return;
        }
        if (cPhase == 5)
        {
            if (cart.Tipping && t - cPhaseStart < 15f) return;
            cLog += " tipTook=" + (t - cPhaseStart).ToString("F1") + "s leftInCart=" + w.CartVoxels + "voxels";
            cPhase = 6; cPhaseStart = t;
            return;
        }
        if (cPhase == 6)
        {
            if (t - cPhaseStart < 7f) return;                                  // let it all settle into ground
            long cChange = (w.CountSolid() + w.LoadVoxels) - cVolume0;
            cLog += " clodsStillLoose=" + w.ClodCount + " volumeChange=" + cChange;
            Debug.Log((cChange == 0 ? "BULLDOZER_CART_RESULT " : "BULLDOZER_CART_FAILED ") + cLog);
            CartFinish(cChange == 0 ? 0 : 1);
        }
    }

    // Where the pushed dirt sits across the blade:  -executeMethod BulldozerBuilder.PushTest
    // Pushes on flat ground for 8 s with the blade straight, then again with it swung right over, logging the heap
    // across the blade's width each second, with a picture from in front of the blade.  Prints BULLDOZER_PUSH_RESULT.
    static int puPhase; static float puT0; static string puLog; static Vector3 puStart;
    public static void PushTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        puPhase = 0; puLog = "";
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += PushTick;
        EditorApplication.EnterPlaymode();
    }
    static void PushFinish(int code) { EditorApplication.update -= PushTick; EditorSettings.enterPlayModeOptionsEnabled = false; EditorApplication.Exit(code); }
    static void PushTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 400) { Debug.LogError("BULLDOZER_PUSH_FAILED timed out " + puLog); PushFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var w = VoxelWorld.Instance; var wk = Worker.Instance;
        if (d == null || w == null || wk == null || d.Blade == null) return;
        float t = Time.time;
        if (puPhase == 0)
        {
            if (t < 2f) return;
            wk.useOverride = true; d.dead = false;
            if (!wk.InDozer) wk.GetIn();
            d.useOverride = true;
            puStart = d.transform.position;
            puPhase = 1; puT0 = t;
            return;
        }
        if (puPhase == 1 || puPhase == 3)
        {
            bool angled = puPhase == 3;
            float k = t - puT0;
            if (k < 0.1f)
            {
                d.Place(puStart + (angled ? new Vector3(8f, 0f, 0f) : Vector3.zero), 0f);
                return;
            }
            d.overrideBlade = k < 1.5f ? -1f : 0f;
            d.overrideAngle = angled && k < 2.5f ? 1f : 0f;
            d.overrideThrottle = k < 1.5f ? 0f : 1f;
            d.overrideSteer = 0f;
            if (k > 2f && Mathf.Repeat(k, 1f) < Time.deltaTime)
                puLog += " " + (angled ? "angled" : "straight") + "t" + k.ToString("F0") + "[yaw=" + d.BladeYaw.ToString("F0") + " speed=" + d.Speed.ToString("F1") + " heap=" + d.BladeLoadM3.ToString("F1") + " " + d.BladeLoadInfo() + "]";
            if (k > 8.5f && puLog.IndexOf(angled ? "picA" : "picS") < 0)
            {
                Vector3 bp = d.Blade.position, f = d.transform.forward;
                HillShot(bp + f * 5.5f + Vector3.up * 2.2f, bp + Vector3.up * 0.3f, angled ? "push_front_angled.png" : "push_front_straight.png");
                puLog += angled ? " picA" : " picS";
            }
            if (k < 9f) return;
            d.overrideThrottle = 0f;
            puPhase++; puT0 = t;
            return;
        }
        if (puPhase == 2) { d.overrideBlade = 1f; if (t - puT0 < 1.5f) return; d.Place(puStart, 0f); puPhase = 3; puT0 = t; return; }
        Debug.Log("BULLDOZER_PUSH_RESULT" + puLog);
        PushFinish(0);
    }

    // The clean screen:  -executeMethod BulldozerBuilder.HudTest
    // The help shows by itself at the start of a new game and goes with H; the dozer's corner shows the blade load and
    // depth; on foot the tool and the cart.  Takes hud_*.png in Logs.  Prints BULLDOZER_HUD_RESULT.
    static int hdPhase; static float hdT0; static string hdLog; static bool hdOk;
    public static void HudTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        hdPhase = 0; hdLog = ""; hdOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += HudTick;
        EditorApplication.EnterPlaymode();
    }
    static void HudCheck(bool ok, string what) { hdLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) hdOk = false; }
    static void HudShot(string name) { ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/" + name); }
    static void HudFinish()
    {
        EditorApplication.update -= HudTick; EditorSettings.enterPlayModeOptionsEnabled = false;
        Hud.HelpKey = false; Hud.DebugOn = false;
        if (hdOk) Debug.Log("BULLDOZER_HUD_RESULT" + hdLog); else Debug.LogError("BULLDOZER_HUD_FAILED phase " + hdPhase + hdLog);
        EditorApplication.Exit(hdOk ? 0 : 1);
    }
    static void HudTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { hdLog += " timed out"; hdOk = false; HudFinish(); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var w = VoxelWorld.Instance; var wk = Worker.Instance;
        if (d == null || w == null || wk == null || d.Blade == null || Hud.Instance == null) return;
        float t = Time.time;
        switch (hdPhase)
        {
            case 0:
                if (t < 2f) return;
                wk.useOverride = true; d.dead = false;
                if (!wk.InDozer) wk.GetIn();
                HudCheck(Hud.HelpOn, "helpAtStart");
                hdPhase = 1; hdT0 = t; return;
            case 1:
                if (t - hdT0 < 0.5f) return;
                HudShot("hud_help_dozer.png");
                hdPhase = 2; hdT0 = t; return;
            case 2:
                if (t - hdT0 < 0.5f) return;
                Hud.SkipFirstHelp();
                HudCheck(!Hud.HelpOn, "helpGoesAway");
                Hud.ToggleHelp(); HudCheck(Hud.HelpOn, "hShowsIt");
                Hud.ToggleHelp(); HudCheck(!Hud.HelpOn, "hHidesIt");
                d.useOverride = true; d.overrideBlade = -1f; d.overrideThrottle = 0f;
                hdPhase = 3; hdT0 = t; return;
            case 3:
                if (t - hdT0 < 1.5f) return;
                d.overrideBlade = 0f; d.overrideThrottle = 1f;
                hdPhase = 4; hdT0 = t; return;
            case 4:
                if (t - hdT0 < 4f) return;
                hdLog += " depth=[" + d.DepthLine() + "] load=" + d.BladeLoadM3.ToString("F1");
                HudCheck(d.DepthLine().StartsWith("Blade") && d.DepthLine().Contains(" cm "), "depthShown");
                HudCheck(d.BladeLoadM3 > 0.3f, "bladeHasLoad");
                d.overrideBlade = 0f; d.overrideAngle = 1f;
                hdPhase = 5; hdT0 = t; return;
            case 5:
                if (t - hdT0 < 1.2f) return;
                d.overrideAngle = 0f; d.overrideThrottle = 0f;
                HudCheck(d.Warnings().Contains("BLADE SWUNG"), "swungWarning");
                HudShot("hud_dozer.png");
                hdPhase = 6; hdT0 = t; return;
            case 6:
                if (t - hdT0 < 0.5f) return;
                Hud.DebugOn = true;
                hdPhase = 7; hdT0 = t; return;
            case 7:
                if (t - hdT0 < 0.5f) return;
                HudShot("hud_debug.png");
                Hud.DebugOn = false;
                d.useOverride = false;
                wk.GetOut();
                hdPhase = 8; hdT0 = t; return;
            case 8:
                if (t - hdT0 < 1.5f) return;
                HudCheck(!wk.InDozer, "gotOut");
                HudShot("hud_foot.png");
                hdPhase = 9; hdT0 = t; return;
            case 9:
                if (t - hdT0 < 0.5f) return;
                HudFinish(); return;
        }
    }

    // The sound:  -executeMethod BulldozerBuilder.SoundTest
    // Every sound gets made, the engine idles in the seat and works harder pushing a heap, the pick makes a sound, and
    // the volume settings step and are kept.  Prints BULLDOZER_SOUND_RESULT.
    static int sdPhase; static float sdT0, sdIdleVol, sdIdleLabour; static string sdLog; static bool sdOk; static int sdPlayed0;
    static float sdOldMaster, sdOldEngine, sdOldFx;
    public static void SoundTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        sdPhase = 0; sdLog = ""; sdOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += SoundTick;
        EditorApplication.EnterPlaymode();
    }
    static void SoundCheck(bool ok, string what) { sdLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) sdOk = false; }
    static void SoundFinish()
    {
        EditorApplication.update -= SoundTick; EditorSettings.enterPlayModeOptionsEnabled = false;
        if (sdOk) Debug.Log("BULLDOZER_SOUND_RESULT" + sdLog); else Debug.LogError("BULLDOZER_SOUND_FAILED phase " + sdPhase + sdLog);
        EditorApplication.Exit(sdOk ? 0 : 1);
    }
    static void SoundTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { sdLog += " timed out"; sdOk = false; SoundFinish(); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var w = VoxelWorld.Instance; var wk = Worker.Instance;
        if (d == null || w == null || wk == null || d.Blade == null || GameAudio.Instance == null) return;
        var da = d.GetComponent<DozerAudio>();
        float t = Time.time;
        switch (sdPhase)
        {
            case 0:
                if (t < 2f || da == null) return;
                int made = 0; float secs = 0f;
                foreach (var n in SoundBank.Names) { var c = SoundBank.Get(n); if (c != null && c.samples > 100) { made++; secs += c.length; } }
                sdLog += " sounds=" + made + "/" + SoundBank.Names.Length + " (" + secs.ToString("F1") + " s)";
                SoundCheck(made == SoundBank.Names.Length, "allSoundsMade");
                sdLog += " recorded=" + SoundBank.RecordedCount;
                SoundCheck(SoundBank.RecordedCount >= 17 && SoundBank.IsRecorded("engine") && SoundBank.IsRecorded("pick_rock"), "ownersRecordingsUsed");
                wk.useOverride = true; d.dead = false;
                if (!wk.InDozer) wk.GetIn();
                sdPhase = 1; sdT0 = t; return;
            case 1:
                if (t - sdT0 < 2f) return;
                sdIdleVol = da.EngineVolume; sdIdleLabour = da.Labour;
                sdLog += " idle[vol=" + sdIdleVol.ToString("F2") + " labour=" + sdIdleLabour.ToString("F2") + "]";
                SoundCheck(sdIdleVol > 0.1f, "engineIdles");
                d.useOverride = true; d.overrideBlade = -1f; d.overrideThrottle = 0f;
                sdPhase = 2; sdT0 = t; return;
            case 2:
                if (t - sdT0 < 1.5f) return;
                d.overrideBlade = 0f; d.overrideThrottle = 1f;
                sdPhase = 3; sdT0 = t; return;
            case 3:
                if (t - sdT0 < 6f) return;
                sdLog += " pushing[rpm=" + da.Rpm.ToString("F2") + " labour=" + da.Labour.ToString("F2") + " bog=" + d.Bog.ToString("F2") + " heap=" + d.BladeLoadM3.ToString("F1") + "]";
                SoundCheck(da.Rpm > 0.5f, "revsWithThrottle");
                SoundCheck(da.Labour > sdIdleLabour + 0.2f, "laboursUnderLoad");
                // the heavy feel: smoke and dust are being made, the nose has lifted with the full blade
                sdLog += " fx[puffs=" + HeavyFX.Emitted + " alive=" + HeavyFX.Alive + " feltPitch=" + d.FeltPitch.ToString("F2") + "]";
                SoundCheck(HeavyFX.Emitted > 20 && HeavyFX.Alive > 0, "smokeAndDust");
                SoundCheck(d.FeltPitch < -0.2f, "noseLiftsWithLoad");
                d.overrideThrottle = 0f; d.useOverride = false;
                wk.GetOut();
                sdPhase = 4; sdT0 = t; return;
            case 4:
                if (t - sdT0 < 1.5f) return;
                SoundCheck(da.EngineVolume < 0.05f, "engineOffWhenOut(" + da.EngineVolume.ToString("F2") + ")");
                sdPlayed0 = GameAudio.Played;
                GameAudio.PlayAt("pick_rock", wk.transform.position);
                GameAudio.Cash();
                SoundCheck(GameAudio.Played >= sdPlayed0 + 2, "oneShotsPlay");
                // the settings: step the volumes and read them back
                sdOldMaster = GameAudio.Master; sdOldEngine = GameAudio.Engine; sdOldFx = GameAudio.Effects;
                var pm = PauseMenu.Instance;
                pm.Change(PauseMenu.SoundRow, -1); pm.Change(PauseMenu.SoundRow + 1, +1); pm.Change(PauseMenu.SoundRow + 2, -1); pm.Change(PauseMenu.SoundRow + 2, -1);
                float m = GameAudio.Master, e = GameAudio.Engine, f = GameAudio.Effects;
                PauseMenu.SavePrefs();
                GameAudio.Master = GameAudio.Engine = GameAudio.Effects = 0.123f;
                PauseMenu.LoadPrefs();
                SoundCheck(Mathf.Approximately(GameAudio.Master, m) && Mathf.Approximately(GameAudio.Engine, e) && Mathf.Approximately(GameAudio.Effects, f)
                           && Mathf.Abs(m - (sdOldMaster - 0.1f)) < 0.001f, "volumesKept(" + m.ToString("F1") + "," + e.ToString("F1") + "," + f.ToString("F1") + ")");
                bool shake = PauseMenu.CameraShake;
                pm.Change(PauseMenu.ShakeRow, 1);
                SoundCheck(PauseMenu.CameraShake != shake, "shakeToggles");
                pm.Change(PauseMenu.ShakeRow, 1);
                GameAudio.Master = sdOldMaster; GameAudio.Engine = sdOldEngine; GameAudio.Effects = sdOldFx;
                PauseMenu.SavePrefs();
                sdPhase = 5; sdT0 = t; return;
            case 5:
                if (t - sdT0 < 0.5f) return;
                SoundCheck(AudioListener.volume == GameAudio.Master, "masterOnListener");
                SoundFinish(); return;
        }
    }

    // Trailer mode's other shots, one after another:  -executeMethod BulldozerBuilder.TrailerShotsTest
    // mine (the pick, then the cart out into daylight), restore (rusted -> engine catches -> yellow), wide (the
    // graded road from above, pulling back).  Pictures: Logs/shot_<name>_<seconds>.png.
    static int tsIdx; static string tsLog; static bool tsOk; static double tsT0; static readonly System.Collections.Generic.HashSet<string> tsTaken = new System.Collections.Generic.HashSet<string>();
    static readonly TrailerMode.ShotKind[] TsShots = { TrailerMode.ShotKind.Mine, TrailerMode.ShotKind.Restore, TrailerMode.ShotKind.Wide };
    static readonly float[][] TsAt = { new[] { 3f, 7f, 11f, 14.5f }, new[] { 1.5f, 3.8f, 4.9f, 6.5f }, new[] { 1f, 6f, 12f } };
    static float tsCartZ0, tsSolid0;
    public static void TrailerShotsTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        tsIdx = 0; tsLog = ""; tsOk = true; tsTaken.Clear();
        TrailerMode.On = true; TrailerMode.Shot = TsShots[0];
        testStart = EditorApplication.timeSinceStartup; tsT0 = -1;
        EditorApplication.update += TrailerShotsTick;
        EditorApplication.EnterPlaymode();
    }
    static void TrailerShotsFinish()
    {
        EditorApplication.update -= TrailerShotsTick;
        TrailerMode.On = false; TrailerMode.Shot = TrailerMode.ShotKind.Road;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        if (tsOk) Debug.Log("BULLDOZER_SHOTS_RESULT" + tsLog); else Debug.LogError("BULLDOZER_SHOTS_FAILED" + tsLog);
        EditorApplication.Exit(tsOk ? 0 : 1);
    }
    static void TrailerShotsTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 400) { tsLog += " timed out"; tsOk = false; TrailerShotsFinish(); return; }
        if (!EditorApplication.isPlaying) return;
        var tm = TrailerMode.Instance; var w = VoxelWorld.Instance; var cart = MineCart.Instance;
        if (tm == null || w == null) return;
        double t = EditorApplication.timeSinceStartup;
        if (tsT0 < 0)
        {
            if (Time.timeSinceLevelLoad < 1.6f) return;                    // the shot starts 1.5 s in
            tsT0 = t;
            if (cart != null) tsCartZ0 = cart.transform.position.z;
            tsSolid0 = w.SolidCount;
        }
        float st = (float)(t - tsT0);
        string name = TsShots[tsIdx].ToString().ToLowerInvariant();
        foreach (float at in TsAt[tsIdx])
        {
            string key = name + at;
            if (st >= at && tsTaken.Add(key)) TestCapture("shot_" + name + "_" + at.ToString("F1") + ".png");
        }
        float end = TsAt[tsIdx][TsAt[tsIdx].Length - 1] + 0.5f;
        if (st < end) return;
        if (TsShots[tsIdx] == TrailerMode.ShotKind.Mine)
        {
            float cz = cart != null ? cart.transform.position.z : 0f;
            tsLog += " mine: picked=" + (tsSolid0 - w.SolidCount) + " voxels held=" + Worker.Instance.HoldingCart + " cartZ " + tsCartZ0.ToString("F1") + "->" + cz.ToString("F1") + " (mouth " + VoxelWorld.PortalZ + ")";
            if (cart == null || cz > VoxelWorld.PortalZ - 1f) { tsOk = false; tsLog += " CART_NOT_OUT=FAIL"; }
        }
        else if (TsShots[tsIdx] == TrailerMode.ShotKind.Restore)
        {
            var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
            bool yellow = true;
            foreach (var r in d.GetComponentsInChildren<MeshRenderer>()) if (r.HasPropertyBlock()) yellow = false;
            tsLog += " restore: yellowAfter5s=" + yellow;
            if (!yellow) { tsOk = false; tsLog += " STILL_RUSTY=FAIL"; }
        }
        else
        {
            tsLog += " wide: done";
        }
        tsIdx++;
        if (tsIdx >= TsShots.Length) { TrailerShotsFinish(); return; }
        TrailerMode.Shot = TsShots[tsIdx];
        tsT0 = -1;
        UnityEngine.SceneManagement.SceneManager.LoadScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene().buildIndex);
    }

    // Trailer mode (DiggerGame.exe -trailer):  -executeMethod BulldozerBuilder.TrailerTest
    // The dozer drives itself up the mountain road on blade auto Grade: after 40 s it is well up the road, on the
    // road, with Grade on.  Pictures at 12 s and 35 s: Logs/trailer_mode_1.png, trailer_mode_2.png (no panels).
    static int trPhase; static string trLog; static bool trOk, trShot1, trShot2;
    public static void TrailerTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        trPhase = 0; trLog = ""; trOk = true; trShot1 = trShot2 = false;
        TrailerMode.On = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += TrailerTick;
        EditorApplication.EnterPlaymode();
    }
    static void TrailerFinish()
    {
        EditorApplication.update -= TrailerTick;
        TrailerMode.On = false;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        if (trOk) Debug.Log("BULLDOZER_TRAILER_RESULT" + trLog); else Debug.LogError("BULLDOZER_TRAILER_FAILED" + trLog);
        EditorApplication.Exit(trOk ? 0 : 1);
    }
    static void TrailerTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { trLog += " timed out"; trOk = false; TrailerFinish(); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        if (d == null) return;
        float t = Time.timeSinceLevelLoad;
        if (!trShot1 && t > 12f) { trShot1 = true; TestCapture("trailer_mode_1.png"); }
        if (!trShot2 && t > 35f) { trShot2 = true; TestCapture("trailer_mode_2.png"); }
        if (t < 42f) return;
        Vector3 p = d.transform.position;
        float s, off; Vector2 dir; MountainRoad.Nearest(p.x, p.z, out s, out off, out dir);
        trLog += " along=" + s.ToString("F1") + "m off=" + off.ToString("F2") + " auto=" + d.BladeAutoName + " grade=" + d.GradeMode;
        if (s < 25f) { trOk = false; trLog += " NOT_FAR_UP=FAIL"; }
        if (Mathf.Abs(off) > MountainRoad.CorridorHalf) { trOk = false; trLog += " OFF_ROAD=FAIL"; }
        if (!d.GradeMode) { trOk = false; trLog += " NOT_ON_GRADE=FAIL"; }
        if (SaveGame.AutoOn) { trOk = false; trLog += " WOULD_SAVE=FAIL"; }
        TrailerFinish();
    }

    // Blade auto holding a cut (below 0):  -executeMethod BulldozerBuilder.BladeCutHoldTest
    // On flat ground, standing still: blade auto on Flat, then set to Cut 30 cm.  The blade must go down to about
    // 30 cm into the ground and STAY there (not spring back up); then driving on, it keeps cutting about 30 cm.
    // Then the lever as the player works it: a quick tap down from Flat holds Cut 5 cm (it used to spring back to
    // Flat, as the blade had not moved yet when the tap was let go); held down and let go it stays where it got to;
    // a tap up goes up one step.  Uphill on the mountain road, stepping from Flat to Cut 10 cm never lifts the blade.
    // Grade (the next press of B after a height): standing on the road the cutting edge goes to the road's grade, and
    // driving up the road on it brings the road nearer grade.
    static int bcPhase; static string bcLog; static bool bcOk; static double bcT0; static float bcLowest, bcAfter;
    public static void BladeCutHoldTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        bcPhase = 0; bcLog = ""; bcOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += BladeCutTick;
        EditorApplication.EnterPlaymode();
    }
    static void BladeCutFinish()
    {
        EditorApplication.update -= BladeCutTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        if (bcOk) Debug.Log("BULLDOZER_BLADECUT_RESULT" + bcLog); else Debug.LogError("BULLDOZER_BLADECUT_FAILED phase " + bcPhase + bcLog);
        EditorApplication.Exit(bcOk ? 0 : 1);
    }
    static double bcNextLog;
    static float bcGrade0, bcGradeS0; static float[] bcRoadBefore;
    // the mean distance from grade of the road's middle, from `from` to `to` metres ahead of the dozer (and remembers
    // the ground there, so it can be compared afterwards)
    static float BcRoadOff(DozerController d, float from, float to)
    {
        float s0, o0; Vector2 d0; MountainRoad.Nearest(d.transform.position.x, d.transform.position.z, out s0, out o0, out d0);
        bcGradeS0 = s0;
        bcRoadBefore = new float[40];
        for (int i = 0; i < 40; i++) { float s = s0 + i * 0.25f; Vector2 p = BcRoadPoint(s); float fh; VoxelWorld.Instance.FirmHeightAt(p.x, p.y, out fh); bcRoadBefore[i] = fh - MountainRoad.GradeAt(s); }
        return BcRoadOffAt(s0 + from, s0 + to, true);
    }
    static Vector2 BcRoadPoint(float s)
    {
        int n = MountainRoad.Count;
        for (int i = 1; i < n; i++)
            if (MountainRoad.AlongAt(i) >= s) { float u = Mathf.InverseLerp(MountainRoad.AlongAt(i - 1), MountainRoad.AlongAt(i), s); return Vector2.Lerp(MountainRoad.Point(i - 1), MountainRoad.Point(i), u); }
        return MountainRoad.Point(n - 1);
    }
    static float BcRoadOffAt(float from, float to, bool before = false)
    {
        float sum = 0f; int n = 0;
        for (float s = from; s <= to; s += 0.25f)
        {
            float off;
            if (before) { int i = Mathf.RoundToInt((s - bcGradeS0) / 0.25f); if (i < 0 || i >= bcRoadBefore.Length) continue; off = bcRoadBefore[i]; }
            else { Vector2 p = BcRoadPoint(s); float fh; VoxelWorld.Instance.FirmHeightAt(p.x, p.y, out fh); off = fh - MountainRoad.GradeAt(s); }
            sum += Mathf.Abs(off); n++;
        }
        return n > 0 ? sum / n : 0f;
    }
    static void BladeCutTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 200) { bcLog += " timed out"; bcOk = false; BladeCutFinish(); return; }
        if (!EditorApplication.isPlaying) return;
        var wk = Worker.Instance; var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        if (wk == null || d == null || Time.timeSinceLevelLoad < 2f) return;
        double t = EditorApplication.timeSinceStartup;
        switch (bcPhase)
        {
            case 0:
                wk.useOverride = true;
                if (!wk.InDozer) wk.GetIn();
                d.useOverride = true; d.dead = false;
                d.Place(new Vector3(0f, 0f, -16f), 0f);
                d.overrideBlade = 0f; d.overrideSteer = 0f; d.overrideRipper = 1f; d.overrideThrottle = 0f;
                d.bladeAuto = DozerController.BladeAutoMode.Flat;
                bcPhase = 1; bcT0 = t; bcNextLog = t;
                return;
            case 1:                                                     // on Flat for a second, then Cut 30 cm, standing still
                if (t - bcT0 < 1.5f) return;
                d.AutoCm = -30;
                bcLog += " set=" + d.BladeAutoName;
                bcPhase = 2; bcT0 = t; bcLowest = 9f;
                return;
            case 2:
                if (t >= bcNextLog) { bcNextLog = t + 0.5; bcLog += " [" + (t - bcT0).ToString("F1") + "s edge=" + d.EdgeAboveTracks.ToString("F2") + " arm=" + d.BladeArmAngle.ToString("F1") + " cm=" + d.AutoCm + (d.HeightAutoActive ? "" : " NOTACTIVE") + "]"; }
                bcLowest = Mathf.Min(bcLowest, d.EdgeAboveTracks);
                if (t - bcT0 < 7f) return;
                bcAfter = d.EdgeAboveTracks;
                bcLog += " standing: lowest=" + bcLowest.ToString("F2") + " after7s=" + bcAfter.ToString("F2");
                if (!(bcAfter < -0.2f)) { bcOk = false; bcLog += " STAYED_DOWN=FAIL"; }
                if (d.AutoCm != -30) { bcOk = false; bcLog += " HEIGHT_CHANGED=FAIL"; }
                bcPhase = 3; bcT0 = t;
                return;
            case 3:                                                     // drive on: it keeps cutting
                d.overrideThrottle = 0.5f;
                if (t >= bcNextLog) { bcNextLog = t + 0.5; bcLog += " [drive " + (t - bcT0).ToString("F1") + "s edge=" + d.EdgeAboveTracks.ToString("F2") + " cm=" + d.AutoCm + "]"; }
                if (t - bcT0 < 8f) return;
                d.overrideThrottle = 0f;
                if (d.AutoCm != -30) { bcOk = false; bcLog += " HEIGHT_CHANGED_DRIVING=FAIL"; }
                {   // the cut it left: about 30 cm below the ground as it was (flat, about 0 here), not deeper and deeper
                    var w = VoxelWorld.Instance;
                    Vector3 dp = d.transform.position;
                    string depths = ""; float worst = 0f;
                    bcLog += " drove=" + (dp.z + 16f).ToString("F1") + "m";
                    // along where the blade went: from where it started (3.4 m ahead of the dozer's middle) to where it is now
                    for (float u = 0.2f; u <= 0.81f; u += 0.15f)
                    {
                        float z = Mathf.Lerp(-16f + 3.4f, dp.z + 3.0f, u);
                        float fh; w.FirmHeightAt(0f, z, out fh);        // (firm: loose dirt can lie in the cut)
                        float dep = -fh;
                        depths += (depths.Length > 0 ? "/" : "") + dep.ToString("F2");
                        worst = Mathf.Max(worst, dep);
                    }
                    bcLog += " cutDepthsBehind=" + depths;
                    if (worst > 0.40f) { bcOk = false; bcLog += " CUT_KEPT_GOING_DOWN=FAIL"; }
                    if (worst < 0.15f) { bcOk = false; bcLog += " DID_NOT_CUT=FAIL"; }
                }
                d.AutoCm = 0; d.leverAsPlayer = true; d.overrideBlade = 0f;
                d.Place(new Vector3(9f, 0f, -16f), 0f);                     // fresh flat ground, beside the cut
                bcPhase = 4; bcT0 = t;
                return;
            case 4:                                                     // the player's lever: a quick tap down from Flat
                if (t - bcT0 < 2f) return;
                d.overrideBlade = t - bcT0 < 2.12f ? -1f : 0f;
                if (t - bcT0 < 5f) return;
                bcLog += " tapDown: " + d.BladeAutoName + " edge=" + d.EdgeAboveTracks.ToString("F2");
                if (d.AutoCm != -5 || d.EdgeAboveTracks > -0.03f) { bcOk = false; bcLog += " TAP_DOWN_SPRANG_BACK=FAIL"; }
                bcPhase = 5; bcT0 = t;
                return;
            case 5:                                                     // held down 1.5 s, let go: it stays down where it got to
                d.overrideBlade = t - bcT0 < 1.5f ? -1f : 0f;
                if (t - bcT0 < 5f) return;
                bcLog += " heldDown: " + d.BladeAutoName + " edge=" + d.EdgeAboveTracks.ToString("F2");
                if (d.AutoCm > -10 || d.EdgeAboveTracks > -0.08f || Mathf.Abs(d.EdgeAboveTracks * 100f - d.AutoCm) > 6f) { bcOk = false; bcLog += " HOLD_DOWN_SPRANG_BACK=FAIL"; }
                bcAfter = d.AutoCm;
                bcPhase = 6; bcT0 = t;
                return;
            case 6:                                                     // a tap up: one step up
                d.overrideBlade = t - bcT0 < 0.12f ? 1f : 0f;
                if (t - bcT0 < 3f) return;
                bcLog += " tapUp: " + d.BladeAutoName;
                if (d.AutoCm != (int)bcAfter + 5) { bcOk = false; bcLog += " TAP_UP=FAIL"; }
                d.leverAsPlayer = false;
                {   // uphill on the mountain road, facing up it, on Flat
                    Vector2 a0 = MountainRoad.Point(10), a1 = MountainRoad.Point(14), dv = (a1 - a0).normalized;
                    d.Place(new Vector3(a0.x, 0f, a0.y), Mathf.Atan2(dv.x, dv.y) * Mathf.Rad2Deg);
                    d.AutoCm = 0;
                }
                bcPhase = 7; bcT0 = t;
                return;
            case 7:                                                     // uphill, Cut 10 cm: the blade goes DOWN, not up
                if (t - bcT0 < 2f) return;
                if (bcPhase == 7 && d.AutoCm == 0) { bcAfter = d.EdgeAboveTracks; d.AutoCm = -10; bcLog += " uphill flat edge=" + bcAfter.ToString("F2"); }
                if (t - bcT0 < 5f) return;
                bcLog += " uphill cut10 edge=" + d.EdgeAboveTracks.ToString("F2") + " pitch=" + Mathf.DeltaAngle(0f, d.transform.eulerAngles.x).ToString("F1");
                if (d.EdgeAboveTracks > bcAfter + 0.05f) { bcOk = false; bcLog += " UPHILL_CUT_LIFTED_THE_BLADE=FAIL"; }   // (a cut goes from the ground ahead, which is lumpy here, not yet graded: a few cm either way, but no big lift)
                // Grade: one more press after a height
                {   // to a stretch of road that needs cutting (its middle well above grade), just before it, facing up the road
                    float best = -1f, bestOff = 0f;
                    for (float s0 = 6f; s0 < MountainRoad.Length - 20f; s0 += 1f)
                    {
                        float sum = 0f; int n = 0;
                        for (float s1 = s0 + 3f; s1 <= s0 + 11f; s1 += 0.5f) { Vector2 q = BcRoadPoint(s1); float fh; if (VoxelWorld.Instance.FirmHeightAt(q.x, q.y, out fh)) { sum += fh - MountainRoad.GradeAt(s1); n++; } }
                        if (n > 10 && sum / n > bestOff) { bestOff = sum / n; best = s0; }
                    }
                    Vector2 a0 = BcRoadPoint(best), a1 = BcRoadPoint(best + 2f), dv = (a1 - a0).normalized;
                    d.Place(new Vector3(a0.x, 0f, a0.y), Mathf.Atan2(dv.x, dv.y) * Mathf.Rad2Deg);
                    bcLog += " cutStretchAt=" + best.ToString("F0") + "m (" + bestOff.ToString("F2") + " m above grade)";
                }
                d.bladeAuto = DozerController.BladeAutoMode.Flat;
                d.CycleBladeAuto();
                bcLog += " then=" + d.BladeAutoName;
                if (!d.GradeMode) { bcOk = false; bcLog += " NO_GRADE_MODE=FAIL"; }
                bcPhase = 8; bcT0 = t;
                return;
            case 8:                                                     // Grade, standing on the road: the edge goes to the road's grade
                if (t - bcT0 < 5f) return;
                {
                    var blade = d.Blade;
                    Vector3 e = (blade.TransformPoint(new Vector3(-2.25f, -0.75f, 1.1f)) + blade.TransformPoint(new Vector3(2.25f, -0.75f, 1.1f))) * 0.5f;
                    float es, eo; Vector2 ed; MountainRoad.Nearest(e.x, e.z, out es, out eo, out ed);
                    float offG = e.y - MountainRoad.GradeAt(es);
                    bcLog += " grade: edgeOffGrade=" + offG.ToString("F2") + " edgeAboveTracks=" + d.EdgeAboveTracks.ToString("F2");
                    if (Mathf.Abs(offG) > 0.07f) { bcOk = false; bcLog += " EDGE_NOT_ON_GRADE=FAIL"; }
                    // the road ahead, before: how far its middle is from grade
                    bcGrade0 = BcRoadOff(d, 2f, 10f);
                    bcLog += " roadOffBefore=" + bcGrade0.ToString("F2");
                }
                bcPhase = 9; bcT0 = t;
                return;
            case 9:                                                     // drive up the road on Grade: the road gets nearer grade
                d.overrideThrottle = t - bcT0 < 0.5f ? 0f : 0.5f;
                if (t - bcT0 < 9f) return;
                d.overrideThrottle = 0f;
                {
                    float after = BcRoadOffAt(bcGradeS0 + 3f, bcGradeS0 + 7f);
                    bcLog += " roadOffAfter=" + after.ToString("F2") + " (" + (bcGradeS0 + 3f).ToString("F0") + "-" + (bcGradeS0 + 7f).ToString("F0") + " m along)";
                    float before = BcRoadOffAt(bcGradeS0 + 3f, bcGradeS0 + 7f, true);
                    if (!(after < before * 0.7f || after < 0.08f)) { bcOk = false; bcLog += " ROAD_NOT_NEARER_GRADE=FAIL(before " + before.ToString("F2") + ")"; }
                }
                // the corridor: the dozer may now drive 4 m off the road's line (past the pegs at 2.25 m)
                bcLog += " corridor=" + MountainRoad.CorridorHalf.ToString("F1");
                if (MountainRoad.CorridorHalf < 3.9f) { bcOk = false; bcLog += " CORRIDOR=FAIL"; }
                BladeCutFinish();
                return;
        }
    }

    // Pushing a tree over and picking up its wood:  -executeMethod BulldozerBuilder.TreeFellTest
    // On a fresh test save (Logs/fell_test.bin): the dozer drives head on into a tree on the hilltop and is held up
    // by it while it leans (about as long as PushNeeded says), then it goes over away from the dozer, lands as chunks
    // of wood, and no longer stops anything; driving on over the chunks picks them up (Wood goes up, nothing is lost).
    // Saved and loaded again: the tree is still down and not in the way, the wood and the chunks left are kept.
    // Pictures: Logs/tree_fall.png (going over), Logs/tree_chunks.png (the wood lying there).
    static int tfPhase, tfTree, tfChunks0, tfWood1, tfLeft1; static string tfLog; static bool tfOk, tfShot1, tfShot2;
    static double tfT0, tfStrainFrom, tfFellAt; static Vector3 tfFrom; static float tfWay;
    static string TfWork { get { return Application.dataPath + "/../Logs/fell_test.bin"; } }
    public static void TreeFellTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        tfPhase = 0; tfLog = ""; tfOk = true; tfTree = -1; tfShot1 = tfShot2 = false; tfStrainFrom = tfFellAt = -1;
        if (System.IO.File.Exists(TfWork)) System.IO.File.Delete(TfWork);
        SaveGame.PathOverride = TfWork; SaveGame.TestAuto = true; SaveGame.AutoEvery = 1e6f;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += TreeFellTick;
        EditorApplication.EnterPlaymode();
    }
    static void TfCheck(bool ok, string what) { tfLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) tfOk = false; }
    static void TreeFellFinish()
    {
        EditorApplication.update -= TreeFellTick;
        SaveGame.PathOverride = null; SaveGame.TestAuto = false; SaveGame.AutoEvery = 300f;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        if (tfOk) Debug.Log("BULLDOZER_TREEFELL_RESULT" + tfLog); else Debug.LogError("BULLDOZER_TREEFELL_FAILED phase " + tfPhase + tfLog);
        EditorApplication.Exit(tfOk ? 0 : 1);
    }
    static void TreeFellTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 400) { tfLog += " timed out"; tfOk = false; TreeFellFinish(); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var sg = SaveGame.Instance; var fell = TreeFelling.Instance; var wk = Worker.Instance;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        if (w == null || sg == null || fell == null || wk == null || d == null) return;
        double t = EditorApplication.timeSinceStartup;
        switch (tfPhase)
        {
            case 0:                                                     // pick a tree with a clear, fairly level run up to it
                if (!sg.StartupDone || Time.timeSinceLevelLoad < 2f) return;
                wk.useOverride = true;
                foreach (int tr in SiteProps.SolidTrees())
                {
                    Vector3 at = FireSim.Trees[tr].at;
                    for (int k = 0; k < 8 && tfTree < 0; k++)
                    {
                        float a = k * Mathf.PI / 4f;
                        Vector3 dir = new Vector3(Mathf.Sin(a), 0f, Mathf.Cos(a));
                        bool clear = true;
                        for (float back = 3.1f; back <= 9f && clear; back += 0.7f)
                        {
                            Vector3 q = at - dir * back;
                            if (SiteProps.Blocks(q, 2.4f) || Mathf.Abs(w.HeightAt(q.x, q.z) - w.HeightAt(at.x, at.z)) > 1.2f || Mathf.Abs(q.x) > 44f || q.z > 44f) clear = false;
                        }
                        for (float on = 1f; on <= FireSim.Trees[tr].height && clear; on += 1f)   // and room ahead for it to fall and to drive on
                        {
                            Vector3 q = at + dir * on;
                            if (Mathf.Abs(q.x) > 44f || q.z > 44f || q.z < -44f) clear = false;
                        }
                        if (clear) { tfTree = tr; tfWay = a; }
                    }
                    if (tfTree >= 0) break;
                }
                TfCheck(tfTree >= 0, "foundATree");
                if (tfTree < 0) { TreeFellFinish(); return; }
                {
                    Vector3 at = FireSim.Trees[tfTree].at, dir = new Vector3(Mathf.Sin(tfWay), 0f, Mathf.Cos(tfWay));
                    tfFrom = at - dir * 7f;
                    if (!wk.InDozer) wk.GetIn();
                    d.useOverride = true; d.dead = false;
                    d.Place(new Vector3(tfFrom.x, 0f, tfFrom.z), tfWay * Mathf.Rad2Deg);
                    d.bladeAuto = DozerController.BladeAutoMode.Off;
                    d.overrideBlade = 0f; d.overrideSteer = 0f; d.overrideRipper = 1f; d.overrideThrottle = 0f;
                    tfLog += " tree=" + tfTree + " at=(" + at.x.ToString("F1") + "," + at.z.ToString("F1") + ") tall=" + FireSim.Trees[tfTree].height.ToString("F1") + " needs=" + TreeFelling.PushNeeded(tfTree).ToString("F1") + "s";
                    TfCheck(SiteProps.TreeBlocking(at, 0.3f) == tfTree, "treeStandsInTheWay");
                }
                tfPhase = 1; tfT0 = t;
                return;
            case 1:                                                     // drive into it until it goes over
                d.overrideThrottle = t - tfT0 < 1f ? 0f : 0.7f;
                if (tfStrainFrom < 0 && fell.Pushing == tfTree) tfStrainFrom = t;
                if (tfFellAt < 0 && fell.Felled.Contains(tfTree)) tfFellAt = t;
                if (tfFellAt > 0 && !tfShot1 && t - tfFellAt > 1.3f && Camera.main != null)
                {
                    tfShot1 = true;
                    TfShoot(w, "tree_fall.png", 0.3f);
                }
                if (tfFellAt > 0 && t - tfFellAt > TreeFelling.FallTook + 0.5f)
                {
                    d.overrideThrottle = 0f;
                    Vector3 at = FireSim.Trees[tfTree].at;
                    double strain = tfFellAt - tfStrainFrom;
                    tfChunks0 = fell.ChunkCount;
                    tfLog += " strained=" + strain.ToString("F1") + "s chunks=" + tfChunks0;
                    TfCheck(strain > TreeFelling.PushNeeded(tfTree) * 0.7f && strain < TreeFelling.PushNeeded(tfTree) + 2f, "heldUpWhileItLeant");
                    TfCheck(SiteProps.TreeBlocking(at, 0.3f) < 0 && !SiteProps.Blocks(at, 0.3f), "trunkNoLongerInTheWay");
                    TfCheck(tfChunks0 >= 4, "brokeIntoWood");
                    TfCheck(fell.Wood == 0, "notPickedUpYet");
                    tfPhase = 2; tfT0 = t;
                }
                else if (tfFellAt < 0 && t - tfT0 > 15f) { TfCheck(false, "fellWithin15s(push=" + fell.PushShare.ToString("F2") + ")"); TreeFellFinish(); }
                return;
            case 2:                                                     // drive on over the wood
                if (!tfShot2 && Camera.main != null) { tfShot2 = true; TfShoot(w, "tree_chunks.png", 0.5f); }
                d.overrideThrottle = t - tfT0 < 0.5f ? 0f : 0.6f;
                if (t - tfT0 < 12f && fell.ChunkCount > 0) return;
                d.overrideThrottle = 0f;
                if (t - tfT0 < 12.6f && fell.ChunkCount == 0) { }                 // (let the last ones land in the cab)
                tfWood1 = fell.Wood; tfLeft1 = fell.ChunkCount;
                tfLog += " wood=" + tfWood1 + " left=" + tfLeft1 + " made=" + fell.ChunksMade + " treesDown=" + fell.Felled.Count;
                TfCheck(tfWood1 > 0, "pickedUpWood");
                TfCheck(tfWood1 + tfLeft1 == fell.ChunksMade, "noWoodLost");          // (a chunk flying into the cab is still in ChunkCount)
                string said = sg.Save();
                TfCheck(said.StartsWith("Game saved"), "saved");
                UnityEngine.SceneManagement.SceneManager.LoadScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene().buildIndex);
                tfPhase = 3; tfT0 = t;
                return;
            case 3:                                                     // loaded again
                if (t - tfT0 < 2f || !sg.StartupDone || Time.timeSinceLevelLoad < 2.5f) return;
                {
                    Vector3 at = FireSim.Trees[tfTree].at;
                    TfCheck(sg.CarriedOn, "reloaded");
                    TfCheck(fell.Felled.Contains(tfTree), "stillDown");
                    TfCheck(SiteProps.TreeBlocking(at, 0.3f) < 0 && !SiteProps.Blocks(at, 0.3f), "stillNotInTheWay");
                    TfCheck(fell.Wood == tfWood1, "woodKept(" + fell.Wood + ")");
                    TfCheck(fell.ChunkCount == tfLeft1, "chunksKept(" + fell.ChunkCount + ")");
                }
                TreeFellFinish();
                return;
        }
    }
    static void TfShoot(VoxelWorld w, string file, float along)
    {
        var tree = FireSim.Trees[tfTree];
        Vector3 dir = new Vector3(Mathf.Sin(tfWay), 0f, Mathf.Cos(tfWay)), side = new Vector3(dir.z, 0f, -dir.x);
        Vector3 look = tree.at + dir * tree.height * along;
        look.y = w.HeightAt(look.x, look.z) + 1.5f;
        Vector3 eye = look + side * 13f - dir * 3f;                      // from the side, a little above
        eye.y = look.y + 7f;
        var ct = Camera.main.transform;
        ct.position = eye; ct.LookAt(look);
        Shader.SetGlobalVector("_CutFrom", eye); Shader.SetGlobalVector("_CutTo", look); Shader.SetGlobalFloat("_CutRadius", 1.6f);   // see through the forest (as the game's camera does)
        TestCapture(file);
    }

    // The one-off pile at the foot of the mountain road:  -executeMethod BulldozerBuilder.RoadPileTest
    // On a COPY of the owner's save (Logs/pile_owner_copy.bin; it was saved before the pile existed):
    //   loads it and the pile is dropped once: about 20 m³ of loose soil, a heap at the foot of the road, the books straight,
    //   the dozer not inside it; saved and loaded again it is still there and is NOT dropped a second time;
    //   then the dozer pushes it up the road (the heap goes down, the dozer gets past where it was).
    static int rpPhase; static string rpLog; static bool rpOk, rpShot; static double rpT0; static float rpTop0, rpBase0; static long rpAdded;
    static string RpCopy { get { return Application.dataPath + "/../Logs/pile_owner_copy.bin"; } }
    static string RpWork { get { return Application.dataPath + "/../Logs/pile_test.bin"; } }
    public static void RoadPileTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        rpPhase = 0; rpLog = ""; rpOk = true; rpShot = false;
        if (!System.IO.File.Exists(RpCopy)) { Debug.LogError("BULLDOZER_ROADPILE_FAILED no copy of the owner's save at " + RpCopy); EditorApplication.Exit(1); return; }
        System.IO.File.Copy(RpCopy, RpWork, true);
        SaveGame.PathOverride = RpWork; SaveGame.TestAuto = true; SaveGame.AutoEvery = 1e6f;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += RoadPileTick;
        EditorApplication.EnterPlaymode();
    }
    static void RpCheck(bool ok, string what) { rpLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) rpOk = false; }
    static void RoadPileFinish()
    {
        EditorApplication.update -= RoadPileTick;
        SaveGame.PathOverride = null; SaveGame.TestAuto = false; SaveGame.AutoEvery = 300f;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        if (rpOk) Debug.Log("BULLDOZER_ROADPILE_RESULT" + rpLog); else Debug.LogError("BULLDOZER_ROADPILE_FAILED phase " + rpPhase + rpLog);
        EditorApplication.Exit(rpOk ? 0 : 1);
    }
    static float RpRing(VoxelWorld w, Vector2 c)       // the ground just outside the heap (the average of 8 points)
    {
        float s = 0f;
        for (int k = 0; k < 8; k++) { float a = k * Mathf.PI / 4f; s += w.TopAt(c.x + Mathf.Cos(a) * (RoadPile.Radius + 0.6f), c.y + Mathf.Sin(a) * (RoadPile.Radius + 0.6f)); }
        return s / 8f;
    }
    static void RoadPileTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 400) { rpLog += " timed out"; rpOk = false; RoadPileFinish(); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var sg = SaveGame.Instance; var pile = RoadPile.Instance; var wk = Worker.Instance;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        if (w == null || sg == null || pile == null || wk == null || d == null) return;
        double t = EditorApplication.timeSinceStartup;
        Vector2 c = RoadPile.Centre();
        switch (rpPhase)
        {
            case 0:                                                     // the owner's save loads, and the pile is dropped
                if (!sg.StartupDone || !pile.Placed || Time.timeSinceLevelLoad < 2f) return;
                wk.useOverride = true;
                rpAdded = pile.LastAdded;
                float m3 = rpAdded * VoxelWorld.VoxelVolume;
                rpTop0 = w.TopAt(c.x, c.y); rpBase0 = RpRing(w, c);
                Vector2 roadStart = MountainRoad.Point(0);
                rpLog += " centre=(" + c.x.ToString("F1") + "," + c.y.ToString("F1") + ") roadStart=(" + roadStart.x.ToString("F1") + "," + roadStart.y.ToString("F1") + ") m3=" + m3.ToString("F2")
                       + " heapTall=" + (rpTop0 - rpBase0).ToString("F2") + " dozerAt=(" + d.transform.position.x.ToString("F1") + "," + d.transform.position.z.ToString("F1") + ")";
                RpCheck(sg.CarriedOn, "ownerSaveLoaded");
                RpCheck(m3 > 19f && m3 < 21f, "about20m3");
                RpCheck(rpTop0 - rpBase0 > 0.6f, "aHeapStandsThere");             // (about 1.1 m in the middle; the ground round it slopes)
                RpCheck(w.LooseOnTop(c.x, c.y), "itIsLooseDirt");
                RpCheck(w.KindAt(c.x, c.y) == VoxelWorld.BlockSite, "onTheSite");
                RpCheck(w.SolidCount + w.LooseTotal() == w.StartTotal, "booksStraight(" + (w.SolidCount + w.LooseTotal() - w.StartTotal) + ")");
                RpCheck((new Vector2(d.transform.position.x, d.transform.position.z) - c).magnitude > RoadPile.Radius + 1.5f, "dozerNotInIt");
                {   // the second pile, beside the road on its left
                    Vector2 c2 = RoadPile.Centre2();
                    float m3b = pile.LastAdded2 * VoxelWorld.VoxelVolume;
                    float ring2 = 0f;
                    for (int k = 0; k < 8; k++) { float a2 = k * Mathf.PI / 4f; ring2 += w.TopAt(c2.x + Mathf.Cos(a2) * (RoadPile.Radius2 + 0.6f), c2.y + Mathf.Sin(a2) * (RoadPile.Radius2 + 0.6f)); }
                    ring2 /= 8f;
                    int treesIn = 0;
                    foreach (int tr in SiteProps.SolidTrees()) if ((new Vector2(FireSim.Trees[tr].at.x, FireSim.Trees[tr].at.z) - c2).magnitude < RoadPile.Radius2 + 0.6f) treesIn++;
                    rpLog += " pile2=(" + c2.x.ToString("F1") + "," + c2.y.ToString("F1") + ") m3=" + m3b.ToString("F2") + " tall=" + (w.TopAt(c2.x, c2.y) - ring2).ToString("F2") + " treesIn=" + treesIn;
                    RpCheck(pile.Placed2 && m3b > 29f && m3b < 31f, "pile2about30m3");
                    RpCheck(w.TopAt(c2.x, c2.y) - ring2 > 0.6f, "pile2Stands");
                    RpCheck(w.LooseOnTop(c2.x, c2.y) && w.KindAt(c2.x, c2.y) == VoxelWorld.BlockSite, "pile2LooseOnSite");
                    Vector2 dv2 = (MountainRoad.Point(Mathf.Min(4, MountainRoad.Count - 1)) - MountainRoad.Point(0)).normalized;
                    RpCheck(Vector2.Dot(c2 - MountainRoad.Point(0), new Vector2(-dv2.y, dv2.x)) > 4f, "pile2LeftOfRoad");
                    RpCheck(treesIn == 0, "noTreeInPile2");
                }
                string said = sg.Save();
                RpCheck(said.StartsWith("Game saved"), "saved");
                UnityEngine.SceneManagement.SceneManager.LoadScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene().buildIndex);
                rpPhase = 1; rpT0 = t;
                return;
            case 1:                                                     // loaded again: still there, not dropped twice
                if (t - rpT0 < 2f || !sg.StartupDone || Time.timeSinceLevelLoad < 2.5f) return;
                wk.useOverride = true;
                RpCheck(sg.CarriedOn, "reloaded");
                RpCheck(pile.Placed && pile.LastAdded == 0, "notDroppedAgain(" + pile.LastAdded + ")");
                RpCheck(pile.Placed2 && pile.LastAdded2 == 0, "pile2NotDroppedAgain");
                RpCheck(Mathf.Abs(w.TopAt(c.x, c.y) - rpTop0) < 0.07f, "heapKept");
                RpCheck(w.SolidCount + w.LooseTotal() == w.StartTotal, "booksStraightAfterLoad");
                // into the dozer, behind the heap, facing up the road; blade on Flat
                Vector2 dir = (MountainRoad.Point(Mathf.Min(4, MountainRoad.Count - 1)) - MountainRoad.Point(0)).normalized;
                Vector2 p = c - dir * (RoadPile.Radius + 4f);
                if (!wk.InDozer) wk.GetIn();
                d.useOverride = true; d.dead = false;
                d.Place(new Vector3(p.x, 0f, p.y), Mathf.Atan2(dir.x, dir.y) * Mathf.Rad2Deg);
                d.bladeAuto = DozerController.BladeAutoMode.Flat;
                d.overrideBlade = 0f; d.overrideSteer = 0f; d.overrideRipper = 1f; d.overrideThrottle = 0f;
                rpPhase = 2; rpT0 = t;
                return;
            case 2:                                                     // push it up the road
                d.overrideThrottle = t - rpT0 < 1.5f ? 0f : 0.8f;
                if (!rpShot && t - rpT0 > 1.2f && Camera.main != null)                    // the heap from behind and above the dozer, looking up the road
                {
                    rpShot = true;
                    Vector2 dv = (MountainRoad.Point(Mathf.Min(4, MountainRoad.Count - 1)) - MountainRoad.Point(0)).normalized;
                    Vector2 eye = c - dv * 6f + new Vector2(dv.y, -dv.x) * 11f;           // (from the side: trees stand behind it)
                    var ct = Camera.main.transform;
                    ct.position = new Vector3(eye.x, w.TopAt(c.x, c.y) + 6f, eye.y);
                    ct.LookAt(new Vector3(c.x + dv.x * 2f, w.TopAt(c.x, c.y) - 0.5f, c.y + dv.y * 2f));
                    TestCapture("road_pile.png");
                }
                if (t - rpT0 < 16f) return;
                d.overrideThrottle = 0f;
                Vector2 dir2 = (MountainRoad.Point(Mathf.Min(4, MountainRoad.Count - 1)) - MountainRoad.Point(0)).normalized;
                Vector2 at = new Vector2(d.transform.position.x, d.transform.position.z);
                float past = Vector2.Dot(at - c, dir2);
                float top1 = w.TopAt(c.x, c.y);
                rpLog += " afterPush heapTall=" + (top1 - rpBase0).ToString("F2") + " dozerPastMiddle=" + past.ToString("F1") + "m load=" + (d.BladeLoadM3).ToString("F1") + "m3";
                RpCheck(top1 < rpTop0 - 0.5f, "heapPushedAway");
                RpCheck(past > 0f, "dozerGotThrough");
                RpCheck(w.TotalLost == 0, "nothingLost");
                RoadPileFinish();
                return;
        }
    }

    // The goals:  -executeMethod BulldozerBuilder.GoalsTest
    // A new game starts on the first goal.  Shovelling into the first cave-in ticks it (bonus paid, sound played).
    // Buying an upgrade ticks that one.  The goals go through a save and a load.  A save from before the goals skips
    // what it has already done.  Then a COPY of the owner's save (Logs/goals_owner_copy.bin, if the scratchpad one is
    // given) is loaded to check it still carries on.  Never writes the owner's own save.  Prints BULLDOZER_GOALS_RESULT.
    static int glPhase; static float glT0; static string glLog; static bool glOk; static long glCoins; static int glPlayed;
    static string GlFile { get { return Application.dataPath + "/../Logs/goals_test.bin"; } }
    static string GlOwnerCopy { get { return Application.dataPath + "/../Logs/goals_owner_copy.bin"; } }
    public static void GoalsTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        glPhase = 0; glLog = ""; glOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += GoalsTick;
        EditorApplication.EnterPlaymode();
    }
    static void GoalsCheck(bool ok, string what) { glLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) glOk = false; }
    static void GoalsFinish()
    {
        SaveGame.PathOverride = null;
        EditorApplication.update -= GoalsTick; EditorSettings.enterPlayModeOptionsEnabled = false;
        if (glOk) Debug.Log("BULLDOZER_GOALS_RESULT" + glLog); else Debug.LogError("BULLDOZER_GOALS_FAILED phase " + glPhase + glLog);
        EditorApplication.Exit(glOk ? 0 : 1);
    }
    static void GoalsTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { glLog += " timed out"; glOk = false; GoalsFinish(); return; }
        if (!EditorApplication.isPlaying) return;
        var w = VoxelWorld.Instance; var wk = Worker.Instance; var g = Goals.Instance; var m = Money.Instance; var up = Upgrades.Instance;
        if (w == null || wk == null || g == null || m == null || up == null || SaveGame.Instance == null) return;
        float t = Time.time;
        switch (glPhase)
        {
            case 0:
                if (t < 2.5f) return;
                wk.useOverride = true;
                glLog += " fresh fill=" + g.CaveFill(0).ToString("F3") + "/" + g.CaveFill(1).ToString("F3") + "/" + g.CaveFill(2).ToString("F3")
                       + " highest=" + g.CaveHighest(0).ToString("F2") + "/" + g.CaveHighest(1).ToString("F2") + "/" + g.CaveHighest(2).ToString("F2");
                GoalsCheck(g.CurrentId == "cave1_dig", "startsOnFirst(" + g.CurrentId + ")");
                GoalsCheck(!g.CaveDug(0) && !g.CaveClear(0) && !g.CaveClear(1) && !g.CaveClear(2), "cavesStartFull");
                GoalsCheck(Mathf.Abs(g.CaveFill(0) - Goals.FreshFill[0]) < 0.02f && Mathf.Abs(g.CaveFill(1) - Goals.FreshFill[1]) < 0.02f && Mathf.Abs(g.CaveFill(2) - Goals.FreshFill[2]) < 0.02f, "freshFillMatchesTable");
                glCoins = m.Coins; glPlayed = GameAudio.Played;
                // shovel into the face of the first cave-in, and throw each load out of the mine
                int got = 0;
                for (float a = 4.0f; a <= 6.01f; a += 0.4f)
                    for (float x = -1f; x <= 1.01f; x += 0.5f)
                        for (float y = 0.4f; y <= 1.21f; y += 0.4f)
                        {
                            got += w.Scoop(new Vector3(VoxelWorld.PortalX + x, y, VoxelWorld.PortalZ + a), 0.3f, 3000);
                            if (w.ShovelVoxels > 0) w.Throw(new Vector3(VoxelWorld.PortalX + 3f, 1.5f, VoxelWorld.PortalZ - 9f), new Vector3(0f, 1f, -2f), 1f, 0.7f);
                        }
                glLog += " shovelled=" + (got * VoxelWorld.VoxelVolume).ToString("F2") + "m3 fill1now=" + g.CaveFill(0).ToString("F3");
                glPhase = 1; glT0 = t; return;
            case 1:
                if (t - glT0 < 1.5f) return;
                GoalsCheck(g.IsDone("cave1_dig") && g.CurrentId == "cart_fill", "digIntoTicks(" + g.CurrentId + ")");
                GoalsCheck(m.Coins >= glCoins + Goals.List[0].bonus, "bonusPaid");
                GoalsCheck(GameAudio.Played > glPlayed, "soundPlayed");
                TestCapture("goals_done.png");
                g.TestComplete(); g.TestComplete();                                     // fill the cart, tip it
                m.TestGrant(1000, 0);
                GoalsCheck(up.Buy(Upgrades.Branch.Pick), "boughtPick2");
                glPhase = 2; glT0 = t; return;
            case 2:
                if (t - glT0 < 1.5f) return;
                GoalsCheck(g.IsDone("upgrade1") && g.CurrentId == "cave1_clear", "upgradeTicks(" + g.CurrentId + ")");
                TestCapture("goals_hud.png");
                // through a real save and load (a file of the test's own)
                SaveGame.PathOverride = GlFile;
                string said = SaveGame.Instance.Save();
                int cur = g.Current, n = g.DoneCount;
                g.Reset();
                string said2 = SaveGame.Instance.Load();
                GoalsCheck(said.StartsWith("Game saved") && said2.StartsWith("Game loaded") && g.Current == cur && g.DoneCount == n, "savedAndLoaded(" + g.CurrentId + "," + g.DoneCount + ")");
                // a save from before the goals: what it has done is skipped
                g.FromOldSave();
                GoalsCheck(g.IsDone("cave1_dig") && g.IsDone("cart_tip") && g.IsDone("upgrade1") && !g.IsDone("cart_fill") && g.CurrentId == "cart_fill", "oldSaveSkipsDone(" + g.CurrentId + ")");
                // the owner's save (a copy): it must load and carry on
                if (System.IO.File.Exists(GlOwnerCopy))
                {
                    SaveGame.PathOverride = GlOwnerCopy;
                    string said3 = SaveGame.Instance.Load();
                    glLog += " owner[" + said3 + " coins=" + m.Coins + " earned=" + m.Earned + " goal=" + g.CurrentId + " done=" + g.DoneCount + "]";
                    GoalsCheck(said3.StartsWith("Game loaded"), "ownerSaveLoads");
                }
                SaveGame.PathOverride = null;
                glPhase = 3; glT0 = t; return;
            case 3:
                if (t - glT0 < 1f) return;
                TestCapture("goals_owner.png");
                glPhase = 4; glT0 = t; return;
            case 4:
                if (t - glT0 < 0.5f) return;
                GoalsFinish(); return;
        }
    }

    // A clip of the polish (heavy feel, hard rock, ripping, the ramp, a goal), WITH the game's sound:
    //   -executeMethod BulldozerBuilder.RecordPolishClip
    // Frames go to Logs/clip at 30 a second, captions to Logs/clip/overlay.ass, the sound to Logs/clip/sound.wav
    // (Unity's AudioRenderer, in step with the frames).  ffmpeg puts them together.
    static int pcSeg, pcSegFrame, pcFrame, pcEnd;
    static Vector3 pcStart; static bool pcFps0;
    static List<float> pcSound = new List<float>();
    public static void RecordPolishClip()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        pcSeg = -1; pcFrame = 0; pcEnd = 0; sOverlay.Clear(); trCaps.Clear(); pcSound.Clear();
        string dir = Application.dataPath + "/../Logs/clip";
        System.IO.Directory.CreateDirectory(dir);
        foreach (var f in System.IO.Directory.GetFiles(dir)) { try { System.IO.File.Delete(f); } catch (System.Exception) { } }   // (the folder itself may be open somewhere)
        testStart = EditorApplication.timeSinceStartup;
        clipLastGameFrame = -1;
        EditorApplication.update += PolishTick;
        EditorApplication.EnterPlaymode();
    }
    static void PcNext(int seg) { pcSeg = seg; pcSegFrame = pcFrame; }
    static void PolishFinish(int code)
    {
        EditorApplication.update -= PolishTick;
        Time.captureFramerate = 0;
        PauseMenu.ShowFps = pcFps0;
        try { AudioRenderer.Stop(); } catch (System.Exception) { }
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }
    static void PcWriteWav(string path, List<float> s, int rate, int ch)
    {
        using (var f = new System.IO.BinaryWriter(System.IO.File.Create(path)))
        {
            int bytes = s.Count * 2;
            f.Write(System.Text.Encoding.ASCII.GetBytes("RIFF")); f.Write(36 + bytes); f.Write(System.Text.Encoding.ASCII.GetBytes("WAVE"));
            f.Write(System.Text.Encoding.ASCII.GetBytes("fmt ")); f.Write(16); f.Write((short)1); f.Write((short)ch); f.Write(rate); f.Write(rate * ch * 2); f.Write((short)(ch * 2)); f.Write((short)16);
            f.Write(System.Text.Encoding.ASCII.GetBytes("data")); f.Write(bytes);
            foreach (float v in s) f.Write((short)Mathf.Clamp(Mathf.RoundToInt(v * 32767f), -32768, 32767));
        }
    }
    static void PolishTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 900) { Debug.LogError("BULLDOZER_POLISHCLIP_FAILED timed out in " + pcSeg); PolishFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var cam = Camera.main; var w = VoxelWorld.Instance; var wk = Worker.Instance;
        if (d == null || cam == null || w == null || wk == null || d.Blade == null || Goals.Instance == null) return;
        if (Time.frameCount == clipLastGameFrame) return;
        clipLastGameFrame = Time.frameCount;
        var follow = cam.GetComponent<FollowCamera>();
        if (pcEnd > 0)
        {
            if (--pcEnd == 0)
            {
                WriteOverlay();
                int ch = AudioSettings.speakerMode == AudioSpeakerMode.Mono ? 1 : 2;
                PcWriteWav(Application.dataPath + "/../Logs/clip/sound.wav", pcSound, AudioSettings.outputSampleRate, ch);
                Debug.Log("BULLDOZER_POLISHCLIP_OK frames=" + pcFrame + " soundSeconds=" + (pcSound.Count / (float)ch / AudioSettings.outputSampleRate).ToString("F1") + " rate=" + AudioSettings.outputSampleRate + " ch=" + ch);
                PolishFinish(0);
            }
            return;
        }
        if (pcSeg == -1)
        {
            if (Time.realtimeSinceStartup < 3f || Time.timeSinceLevelLoad < 2.5f) return;
            GameViewSize(1920, 1080);
            Hud.SkipFirstHelp();
            pcFps0 = PauseMenu.ShowFps; PauseMenu.ShowFps = false;            // (filming makes the fps read low)
            wk.useOverride = true; d.dead = false;
            if (!wk.InDozer) wk.GetIn();
            d.useOverride = true;
            pcStart = d.transform.position;
            d.Place(pcStart, 0f);
            Time.captureFramerate = 30;
            AudioRenderer.Start();
            PcNext(0);
            return;
        }
        float k = (pcFrame - pcSegFrame) / 30f;
        string title = "", cap = "";
        if (pcSeg == 0)
        {
            d.overrideBlade = k < 1.2f ? -1f : 0f; d.overrideSteer = 0f; d.overrideRipper = 0f;
            d.overrideThrottle = k < 1.6f ? 0f : 1f;
            if (follow != null) { follow.yawOffset = Mathf.Lerp(80f, 55f, k / 11f); follow.distance = 12f; follow.pitch = 16f; }
            title = "A heavy machine";
            cap = k < 4f ? "Grey puff from the stack as the throttle opens" : "Labouring: thick black smoke, the engine drops, dust off the blade, the nose lifts";
            if (k > 11f) { d.overrideThrottle = 0f; PcNext(1); }
        }
        else if (pcSeg == 1)
        {
            if (k < 0.05f) { d.Place(new Vector3(VoxelWorld.RockPadX, 0f, VoxelWorld.RockPadZ - 9f), 0f); d.overrideBlade = 0f; }
            d.overrideBlade = k < 1.2f ? -1f : 0f; d.overrideThrottle = k < 1.3f ? 0f : 1f; d.overrideSteer = 0f;
            if (follow != null) { follow.yawOffset = 100f; follow.distance = 11f; follow.pitch = 15f; }
            title = "Hard rock";
            cap = "The blade bangs into rock:  a clunk, a jolt, and the camera bumps";
            if (k > 7f) { d.overrideThrottle = 0f; PcNext(2); }
        }
        else if (pcSeg == 2)
        {
            if (k < 0.05f) { d.Place(new Vector3(VoxelWorld.RockPadX, 0f, VoxelWorld.RockPadZ - 3f), 0f); }
            d.overrideBlade = 1f; d.overrideRipper = k < 1.5f ? -1f : 0f; d.overrideThrottle = k < 1.6f ? 0f : 0.5f; d.overrideSteer = 0f;
            if (follow != null) { follow.yawOffset = 150f; follow.distance = 10f; follow.pitch = 14f; }
            title = "Ripping";
            cap = "The ripper grinds through the rock, with a steady shudder";
            if (k > 7f) { d.overrideThrottle = 0f; d.overrideRipper = 1f; PcNext(3); }
        }
        else if (pcSeg == 3)
        {
            if (k < 0.05f) { d.Place(new Vector3(VoxelWorld.TrackCentreX(1f), 0f, 1f), 0f); }
            d.overrideBlade = 1f; d.overrideRipper = 1f;
            d.overrideThrottle = k < 1f ? 0f : 1f;
            float want = VoxelWorld.TrackCentreX(d.transform.position.z + 3f) - d.transform.position.x;
            d.overrideSteer = Mathf.Clamp(want * 0.6f, -1f, 1f);
            if (follow != null) { follow.yawOffset = 70f; follow.distance = 12f; follow.pitch = 14f; }
            title = "Fixed: up the ramp with the blade raised";
            cap = d.Glanced ? "The blade end catches the rock bench, glances off it, and carries on up" : "It used to stop dead here on \"hard rock\"";
            if (k > 10f) { d.overrideThrottle = 0f; PcNext(4); }
        }
        else if (pcSeg == 4)
        {
            if (k < 0.05f)
            {
                d.useOverride = false;
                wk.GetOut();
                wk.Teleport(new Vector3(VoxelWorld.PortalX, 0f, VoxelWorld.PortalZ + 1.6f), 0f);
                wk.Look(10f);
            }
            if (k > 2.5f && k < 2.55f)
                for (float a = 4.0f; a <= 6.01f; a += 0.4f)
                    for (float x = -1f; x <= 1.01f; x += 0.5f)
                        for (float y = 0.4f; y <= 1.21f; y += 0.4f)
                        {
                            w.Scoop(new Vector3(VoxelWorld.PortalX + x, y, VoxelWorld.PortalZ + a), 0.3f, 3000);
                            if (w.ShovelVoxels > 0) w.Throw(new Vector3(VoxelWorld.PortalX + 2.5f, 2.5f, VoxelWorld.PortalZ - 2f), new Vector3(0f, 1f, -3f), 1f, 0.7f);
                        }
            title = "Small goals, one at a time";
            cap = k < 3f ? "The goal sits at the top of the screen" : "Done:  a ding, a few coins, and the next goal comes up";
            if (k > 8f) { pcEnd = 3; return; }
        }
        // the sound for this frame
        int n = AudioRenderer.GetSampleCountForCaptureFrame();
        int chs = AudioSettings.speakerMode == AudioSpeakerMode.Mono ? 1 : 2;
        if (n > 0)
        {
            var buf = new Unity.Collections.NativeArray<float>(n * chs, Unity.Collections.Allocator.Temp);
            if (AudioRenderer.Render(buf)) for (int i = 0; i < buf.Length; i++) pcSound.Add(buf[i]);
            buf.Dispose();
        }
        float a0 = pcFrame / 30f, b0 = (pcFrame + 1) / 30f;
        string at = AssTime(a0) + "," + AssTime(b0);
        if (title.Length > 0) sOverlay.Add("Dialogue: 0," + at + ",Title,,0,0,0,," + AssEsc(title));
        if (cap.Length > 0) sOverlay.Add("Dialogue: 0," + at + ",Caption,,0,0,0,," + AssEsc(cap));
        ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/clip/frame_" + pcFrame.ToString("D4") + ".png");
        pcFrame++;
    }

    // Driving through ripped ground:  -executeMethod BulldozerBuilder.RubbleTest
    // Rips the bare rock patch with three passes of the ripper, then drives through the rubble twice: blade resting at
    // ground level (it pushes the rubble: slower, but must never get stuck), then blade raised (must keep going over
    // 1 m/s).  Prints BULLDOZER_RUBBLE_RESULT.
    static int rbPhase, rbPass; static float rbT0, rbMinV, rbSumV, rbDist; static int rbN; static string rbLog; static bool rbOk;
    static Vector3 rbFrom;
    public static void RubbleTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        rbPhase = 0; rbPass = 0; rbLog = ""; rbOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += RubbleTick;
        EditorApplication.EnterPlaymode();
    }
    static void RubbleFinish()
    {
        EditorApplication.update -= RubbleTick; EditorSettings.enterPlayModeOptionsEnabled = false;
        if (rbOk) Debug.Log("BULLDOZER_RUBBLE_RESULT" + rbLog); else Debug.LogError("BULLDOZER_RUBBLE_FAILED phase " + rbPhase + rbLog);
        EditorApplication.Exit(rbOk ? 0 : 1);
    }
    static void RubbleTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 400) { rbLog += " timed out"; rbOk = false; RubbleFinish(); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var w = VoxelWorld.Instance; var wk = Worker.Instance;
        if (d == null || w == null || wk == null || d.Blade == null) return;
        float t = Time.time, k = t - rbT0;
        float px = VoxelWorld.RockPadX, pz = VoxelWorld.RockPadZ;
        switch (rbPhase)
        {
            case 0:
                if (t < 2f) return;
                wk.useOverride = true; d.dead = false;
                if (!wk.InDozer) wk.GetIn();
                d.useOverride = true;
                rbPhase = 1; rbT0 = t; return;
            case 1:
                // a ripping pass along the patch (three passes, side by side)
                if (k < 0.05f) { d.Place(new Vector3(px - 0.75f + 0.75f * rbPass, 0f, pz - 7f), 0f); return; }
                d.overrideBlade = 1f; d.overrideSteer = 0f;
                d.overrideRipper = k < 2.5f ? -1f : 0f;
                d.overrideThrottle = k < 2.5f ? 0f : 0.6f;
                if (k < 14f) return;
                d.overrideThrottle = 0f; d.overrideRipper = 1f;
                rbLog += " pass" + rbPass + "reachedZ=" + d.transform.position.z.ToString("F1");
                rbPass++; rbT0 = t;
                if (rbPass >= 3) { rbPhase = 2; rbLog += " ripped=" + w.TotalRipped + " clods=" + w.ClodCount; }
                return;
            case 2:
                if (k < 4f) return;                                              // the rubble settles
                rbPhase = 3; rbT0 = t; return;
            case 3: case 4: case 5:
            {
                bool raised = rbPhase == 5, down = rbPhase == 4;   // 3: blade auto Flat (edge at ground level), 4: pushing, about 10 cm down, 5: raised
                if (k < 0.05f)
                {
                    d.Place(new Vector3(px, 0f, pz - 9f), 0f);
                    d.overrideBlade = 0f; d.overrideThrottle = 0f;
                    d.bladeAuto = rbPhase == 3 ? DozerController.BladeAutoMode.Flat : DozerController.BladeAutoMode.Off;
                    rbFrom = d.transform.position; rbMinV = 99f; rbSumV = 0f; rbN = 0;
                    return;
                }
                d.overrideRipper = 1f; d.overrideSteer = 0f;
                // ground level: the blade lowered just to the surface (lever down for a moment from parked); raised: up
                // pushing: the lever down until the edge is about 10 cm into the ground, then let go (it holds there)
                d.overrideBlade = raised ? 1f : down && d.BladeArmAngle < d.AutoAngle(DozerController.BladeAutoMode.Cut10) ? -1f : 0f;
                d.overrideThrottle = k < 1.5f ? 0f : 1f;
                bool inPatch = d.transform.position.z > pz - 6f && d.transform.position.z < pz + 4f;
                if (k > 3f && inPatch) { rbMinV = Mathf.Min(rbMinV, d.Speed); rbSumV += d.Speed; rbN++; }
                if (down && d.BlockedByRock && rbLog.IndexOf("hardScan") < 0)
                {
                    // what the blade is up against: hard voxels in its box, and what is round them
                    int nHard = 0, topLoose = 0, besideLoose = 0; float ylo = 9f, yhi = -9f;
                    for (float bx = -2.2f; bx <= 2.2f; bx += 0.0625f)
                        for (float by = -0.75f; by <= 1.25f; by += 0.0625f)
                            for (float bz = 0.85f; bz <= 1.15f; bz += 0.0625f)
                            {
                                Vector3 wp = d.Blade.TransformPoint(new Vector3(bx, by, bz));
                                byte m = w.MaterialAt(wp);
                                if (m < VoxelWorld.Rock || m > VoxelWorld.Gold) continue;
                                nHard++; ylo = Mathf.Min(ylo, wp.y); yhi = Mathf.Max(yhi, wp.y);
                                if (w.LooseOnTop(wp.x, wp.z)) topLoose++;
                                bool near = false;
                                for (int q = 0; q < 4 && !near; q++)
                                {
                                    Vector3 o = q == 0 ? Vector3.right : q == 1 ? Vector3.left : q == 2 ? Vector3.forward : Vector3.back;
                                    byte mn = w.MaterialAt(wp + o * 0.2f);
                                    near = mn >= VoxelWorld.LooseSoil;
                                }
                                if (near) besideLoose++;
                            }
                    rbLog += " hardScan[n=" + nHard + " y=" + ylo.ToString("F2") + ".." + yhi.ToString("F2") + " colTopLoose=" + topLoose + " looseBeside=" + besideLoose + " surface=" + w.HeightAt(d.Blade.position.x, d.Blade.position.z + 1f).ToString("F2") + "]";
                }
                if (k > 2f && Mathf.Repeat(k, 1f) < Time.deltaTime && d.transform.position.z < pz + 5f)
                    rbLog += " [" + (raised ? "up" : down ? "down" : "flat") + " t" + k.ToString("F0") + " z=" + d.transform.position.z.ToString("F1") + " v=" + d.Speed.ToString("F2") + " bog=" + d.Bog.ToString("F2")
                           + " load=" + d.BladeLoadM3.ToString("F1") + " cut=" + d.CutRateM3.ToString("F1") + " cliff=" + d.AtCliff + " climb=" + d.Climbing + " rock=" + d.BlockedByRock + " edge=" + d.EdgeAboveTracks.ToString("F2") + " arm=" + d.BladeArmAngle.ToString("F1") + " y=" + d.transform.position.y.ToString("F2") + "]";
                if (k < 16f && d.transform.position.z < pz + 5f) return;
                d.overrideThrottle = 0f;
                float avg = rbSumV / Mathf.Max(1, rbN);
                rbDist = d.transform.position.z - rbFrom.z;
                rbLog += " " + (raised ? "RAISED" : down ? "DOWN" : "FLAT") + ":dist=" + rbDist.ToString("F1") + " avgV=" + avg.ToString("F2") + " minV=" + rbMinV.ToString("F2");
                if (raised) { bool ok = avg > 1f && rbMinV > 0.4f; rbLog += " raisedKeepsGoing=" + (ok ? "ok" : "FAIL"); if (!ok) rbOk = false; }
                else { bool ok = rbMinV > 0.15f && rbDist > 9f; rbLog += " lowNeverStuck=" + (ok ? "ok" : "FAIL"); if (!ok) rbOk = false; }
                if (raised) { TestCapture("rubble_after.png"); RubbleFinish(); return; }
                d.bladeAuto = DozerController.BladeAutoMode.Off;
                rbPhase++; rbT0 = t; return;
            }
        }
    }

    // A clip of ripping the rock patch and then pushing through it, with the sound:
    //   -executeMethod BulldozerBuilder.RecordRubbleClip      (frames, captions and sound.wav in Logs/clip, as RecordPolishClip)
    static int rcSeg2, rcPass2;
    public static void RecordRubbleClip()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        pcSeg = -1; pcFrame = 0; pcEnd = 0; rcSeg2 = 0; rcPass2 = 0; sOverlay.Clear(); trCaps.Clear(); pcSound.Clear();
        string dir = Application.dataPath + "/../Logs/clip";
        System.IO.Directory.CreateDirectory(dir);
        foreach (var f in System.IO.Directory.GetFiles(dir)) { try { System.IO.File.Delete(f); } catch (System.Exception) { } }
        testStart = EditorApplication.timeSinceStartup;
        clipLastGameFrame = -1;
        EditorApplication.update += RubbleClipTick;
        EditorApplication.EnterPlaymode();
    }
    static void RubbleClipTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 900) { Debug.LogError("BULLDOZER_RUBBLECLIP_FAILED timed out in " + pcSeg); EditorApplication.update -= RubbleClipTick; PolishFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var cam = Camera.main; var w = VoxelWorld.Instance; var wk = Worker.Instance;
        if (d == null || cam == null || w == null || wk == null || d.Blade == null) return;
        if (Time.frameCount == clipLastGameFrame) return;
        clipLastGameFrame = Time.frameCount;
        var follow = cam.GetComponent<FollowCamera>();
        float px = VoxelWorld.RockPadX, pz = VoxelWorld.RockPadZ;
        if (pcEnd > 0)
        {
            if (--pcEnd == 0)
            {
                WriteOverlay();
                int ch = AudioSettings.speakerMode == AudioSpeakerMode.Mono ? 1 : 2;
                PcWriteWav(Application.dataPath + "/../Logs/clip/sound.wav", pcSound, AudioSettings.outputSampleRate, ch);
                Debug.Log("BULLDOZER_RUBBLECLIP_OK frames=" + pcFrame);
                EditorApplication.update -= RubbleClipTick;
                PolishFinish(0);
            }
            return;
        }
        if (pcSeg == -1)
        {
            if (Time.realtimeSinceStartup < 3f || Time.timeSinceLevelLoad < 2.5f) return;
            GameViewSize(1920, 1080);
            Hud.SkipFirstHelp();
            pcFps0 = PauseMenu.ShowFps; PauseMenu.ShowFps = false;
            wk.useOverride = true; d.dead = false;
            if (!wk.InDozer) wk.GetIn();
            d.useOverride = true;
            Time.captureFramerate = 30;
            pcSeg = 0; pcSegFrame = Time.frameCount;
            return;
        }
        if (pcSeg == 0)
        {
            // not filmed: two ripping passes beside the one that is filmed
            float k0 = (Time.frameCount - pcSegFrame) / 30f;
            if (k0 < 0.05f) { d.Place(new Vector3(px - 0.75f + 1.5f * rcPass2, 0f, pz - 7f), 0f); return; }
            d.overrideBlade = 1f; d.overrideSteer = 0f; d.overrideRipper = k0 < 2.5f ? -1f : 0f; d.overrideThrottle = k0 < 2.5f ? 0f : 0.6f;
            if (k0 < 14f) return;
            d.overrideThrottle = 0f; d.overrideRipper = 1f;
            if (++rcPass2 < 2) { pcSegFrame = Time.frameCount; return; }
            AudioRenderer.Start();
            PcNext(1);
            return;
        }
        float k = (pcFrame - pcSegFrame) / 30f;
        string title = "", cap = "";
        if (pcSeg == 1)
        {
            if (k < 0.05f) d.Place(new Vector3(px, 0f, pz - 7f), 0f);
            d.overrideBlade = 1f; d.overrideSteer = 0f; d.overrideRipper = k < 2.5f ? -1f : 0f; d.overrideThrottle = k < 2.5f ? 0f : 0.6f;
            if (follow != null) { follow.yawOffset = 110f; follow.distance = 11f; follow.pitch = 15f; }
            title = "Rip the rock";
            cap = "The ripper now cracks the whole width between its teeth (sounds: the owner's recordings)";
            if (k > 9f) { d.overrideThrottle = 0f; d.overrideRipper = 1f; PcNext(2); }
        }
        else if (pcSeg == 2)
        {
            if (k < 0.05f) { d.Place(new Vector3(px, 0f, pz - 9f), 0f); d.overrideBlade = 0f; d.overrideThrottle = 0f; }
            d.overrideRipper = 1f; d.overrideSteer = 0f;
            d.overrideBlade = d.BladeArmAngle < d.AutoAngle(DozerController.BladeAutoMode.Cut10) ? -1f : 0f;   // the arms where 10 cm in would be
            d.overrideThrottle = k < 2.6f ? 0f : 1f;
            if (follow != null) { follow.yawOffset = Mathf.Lerp(70f, 40f, k / 11f); follow.distance = 12f; follow.pitch = 16f; }
            title = "Then push straight through it";
            cap = k < 5f ? "Blade 10 cm in, through the ripped rock" : "No more stopping dead on \"hard rock\"";
            if (k > 11f) { d.overrideThrottle = 0f; pcEnd = 3; return; }
        }
        int n = AudioRenderer.GetSampleCountForCaptureFrame();
        int chs = AudioSettings.speakerMode == AudioSpeakerMode.Mono ? 1 : 2;
        if (n > 0)
        {
            var buf = new Unity.Collections.NativeArray<float>(n * chs, Unity.Collections.Allocator.Temp);
            if (AudioRenderer.Render(buf)) for (int i = 0; i < buf.Length; i++) pcSound.Add(buf[i]);
            buf.Dispose();
        }
        float a0 = pcFrame / 30f, b0 = (pcFrame + 1) / 30f;
        string at = AssTime(a0) + "," + AssTime(b0);
        if (title.Length > 0) sOverlay.Add("Dialogue: 0," + at + ",Title,,0,0,0,," + AssEsc(title));
        if (cap.Length > 0) sOverlay.Add("Dialogue: 0," + at + ",Caption,,0,0,0,," + AssEsc(cap));
        ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/clip/frame_" + pcFrame.ToString("D4") + ".png");
        pcFrame++;
    }

    // Autosave, carry on and New game:  -executeMethod BulldozerBuilder.AutosaveTest
    // Uses a save file of its own in Logs (never the owner's).  Waits for an autosave, saves with some coins, starts a
    // new game (the save goes aside as .old, the site starts fresh), then puts the save back, reloads, and checks the
    // game carried on with the coins.  Prints BULLDOZER_AUTOSAVE_RESULT.
    static int asPhase; static float asT0; static string asLog; static bool asOk; static long asCoins;
    static string AsFile { get { return Application.dataPath + "/../Logs/autosave_test.bin"; } }
    // Reset ground:  -executeMethod BulldozerBuilder.ResetGroundTest    prints BULLDOZER_RESETGROUND_RESULT (or _FAILED)
    // Dig a trench and raise a heap, drive a bit, then reset: the ground must be exactly as made (same height at the
    // spots, same amount of ground, nothing loose), and the coins must still be there.
    static int rgPhase; static string rgLog; static bool rgOk; static float rgT0; static long rgSolid0, rgCoins;
    static float[] rgH0;
    static readonly Vector2[] RgSpots = { new Vector2(2f, -10f), new Vector2(3f, -10f), new Vector2(-2f, -6f), new Vector2(0f, -4f) };
    public static void ResetGroundTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        rgPhase = 0; rgLog = ""; rgOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += ResetGroundTick;
        EditorApplication.EnterPlaymode();
    }
    static void RgCheck(bool ok, string what) { rgLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) rgOk = false; }
    static void ResetGroundFinish(int code)
    {
        EditorApplication.update -= ResetGroundTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }
    static void ResetGroundTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_RESETGROUND_FAILED timed out in phase " + rgPhase + rgLog); ResetGroundFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var sg = SaveGame.Instance; var w = VoxelWorld.Instance; var m = Money.Instance; var wk = Worker.Instance;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        if (sg == null || w == null || m == null || wk == null || d == null) return;
        float t = Time.time;
        if (rgPhase == 0)
        {
            if (t < 2f) return;
            wk.useOverride = true; d.useOverride = true; d.dead = false;
            if (!wk.InDozer) wk.GetIn();
            rgSolid0 = w.StartTotal;                                     // the ground as made (the parked blade may already have nicked a few voxels)
            rgH0 = new float[RgSpots.Length];
            for (int i = 0; i < RgSpots.Length; i++) rgH0[i] = w.TopAt(RgSpots[i].x, RgSpots[i].y);
            // a trench and a heap
            for (float x = 1.5f; x < 3.5f; x += VoxelWorld.Voxel) for (float z = -11f; z < -9f; z += VoxelWorld.Voxel) w.TestSetColumn(x, z, w.TopAt(x, z) - 0.5f);
            for (float x = -2.5f; x < -1.5f; x += VoxelWorld.Voxel) for (float z = -6.5f; z < -5.5f; z += VoxelWorld.Voxel) w.TestSetColumn(x, z, w.TopAt(x, z) + 0.4f);
            m.TestGrant(250, 0); rgCoins = m.Coins;
            d.overrideBlade = -1f; d.overrideThrottle = 1f;           // dig a bit with the blade too
            rgPhase = 1; rgT0 = t;
            return;
        }
        if (rgPhase == 1)
        {
            if (t - rgT0 < 4f) return;
            d.overrideThrottle = 0f; d.overrideBlade = 1f;            // stop and lift clear, so it isn't digging as it resets
            if (t - rgT0 < 7f) return;
            bool changed = Mathf.Abs(w.TopAt(2f, -10f) - rgH0[0]) > 0.3f;
            RgCheck(changed, "dugFirst");
            rgLog += " clodsBefore=" + w.ClodCount + " solidChange=" + (w.SolidCount - rgSolid0);
            sg.ResetGround();
            rgPhase = 2; rgT0 = t;
            return;
        }
        if (rgPhase == 2)
        {
            if (t - rgT0 < 1f) return;
            float worst = 0f;
            for (int i = 0; i < RgSpots.Length; i++) worst = Mathf.Max(worst, Mathf.Abs(w.TopAt(RgSpots[i].x, RgSpots[i].y) - rgH0[i]));
            rgLog += " worstHeightChange=" + worst.ToString("F3") + " solidAfter-start=" + (w.SolidCount - rgSolid0) + " clods=" + w.ClodCount + " loose=" + w.LoadVoxels;
            RgCheck(worst < 0.001f, "groundAsMade");
            RgCheck(w.SolidCount == rgSolid0, "sameAmountOfGround");
            RgCheck(w.ClodCount == 0 && w.LoadVoxels == 0, "nothingLoose");
            RgCheck(m.Coins == rgCoins, "coinsKept");
            RgCheck(d.transform.position.y > w.TopAt(d.transform.position.x, d.transform.position.z) - 0.3f, "dozerOnTop");
            Debug.Log((rgOk ? "BULLDOZER_RESETGROUND_RESULT" : "BULLDOZER_RESETGROUND_FAILED") + rgLog);
            ResetGroundFinish(rgOk ? 0 : 1);
        }
    }

    public static void AutosaveTest()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        if (System.IO.File.Exists(AsFile)) System.IO.File.Delete(AsFile);
        if (System.IO.File.Exists(AsFile + ".old")) System.IO.File.Delete(AsFile + ".old");
        SaveGame.PathOverride = AsFile; SaveGame.TestAuto = true; SaveGame.AutoEvery = 3f;
        asPhase = 0; asLog = ""; asOk = true;
        testStart = EditorApplication.timeSinceStartup;
        EditorApplication.update += AutosaveTick;
        EditorApplication.EnterPlaymode();
    }
    static void AsCheck(bool ok, string what) { asLog += " " + what + "=" + (ok ? "ok" : "FAIL"); if (!ok) asOk = false; }
    static void AutosaveFinish(int code)
    {
        EditorApplication.update -= AutosaveTick;
        SaveGame.PathOverride = null; SaveGame.TestAuto = false; SaveGame.AutoEvery = 300f;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }
    static void AutosaveTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 300) { Debug.LogError("BULLDOZER_AUTOSAVE_FAILED timed out in phase " + asPhase + asLog); AutosaveFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var sg = SaveGame.Instance; var w = VoxelWorld.Instance; var m = Money.Instance;
        if (sg == null || w == null || m == null || Worker.Instance == null) return;
        float t = Time.realtimeSinceStartup;
        if (asPhase == 0)
        {
            AsCheck(!sg.CarriedOn, "noSaveSoFreshStart");
            asPhase = 1; asT0 = t;
            return;
        }
        if (asPhase == 1)
        {
            if (!System.IO.File.Exists(AsFile)) { if (t - asT0 > 20f) { AsCheck(false, "autosavedWithin20s"); asPhase = 2; } return; }
            AsCheck(true, "autosaved");
            m.Refund(123, 0);
            asCoins = m.Coins;
            string said = sg.Save();                                  // what Quit does
            AsCheck(said.StartsWith("Game saved"), "savedOnQuit");
            asLog += " coins=" + asCoins;
            asPhase = 2;
            return;
        }
        if (asPhase == 2)
        {
            SaveGame.AutoEvery = 300f;                                 // no more autosaves while checking
            sg.NewGame();
            asPhase = 3; asT0 = t;
            return;
        }
        if (asPhase == 3)
        {
            if (t - asT0 < 3f || Time.timeSinceLevelLoad < 1.5f) return;
            AsCheck(!System.IO.File.Exists(AsFile) && System.IO.File.Exists(AsFile + ".old"), "newGameKeptBackup");
            AsCheck(!sg.CarriedOn, "newGameIsFresh");
            AsCheck(m.Coins == 0, "newGameCoinsZero(" + m.Coins + ")");
            AsCheck(Time.timeScale == 1f, "runningAfterNewGame");
            System.IO.File.Move(AsFile + ".old", AsFile);              // the save back, and start the game again
            UnityEngine.SceneManagement.SceneManager.LoadScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene().buildIndex);
            asPhase = 4; asT0 = t;
            return;
        }
        if (asPhase == 4)
        {
            if (t - asT0 < 3f || Time.timeSinceLevelLoad < 2f) return;
            AsCheck(sg.CarriedOn, "carriedOnFromSave");
            AsCheck(m.Coins == asCoins, "coinsBack(" + m.Coins + ")");
            Debug.Log((asOk ? "BULLDOZER_AUTOSAVE_RESULT" : "BULLDOZER_AUTOSAVE_FAILED") + asLog);
            AutosaveFinish(asOk ? 0 : 1);
        }
    }

    // A video of the latest changes, filmed with the screen (so the menus and the cab text are in it):
    //   -executeMethod BulldozerBuilder.RecordChangesClip    Frames (1920 x 1080) and overlay.ass go to Logs/clip.
    // Straight push (faster, slows under the heap, fills the blade), swung blade warning, the blade lifted clear going
    // up the ramp, the auto blade on Flat, the Esc menu and settings, and the upgrade tree.  On Ultra with the fps shown.
    static int chSeg, chSegFrame, chFrame, chView0 = -1, chQ0, chEnd;
    static bool chFps0;
    static Vector3 chStart;
    public static void RecordChangesClip()
    {
        EditorSceneManager.OpenScene(ScenePath);
        EditorSettings.enterPlayModeOptionsEnabled = true;
        EditorSettings.enterPlayModeOptions = EnterPlayModeOptions.DisableDomainReload;
        chSeg = -1; chFrame = 0; chEnd = 0; sOverlay.Clear(); trCaps.Clear(); sTitle = ""; sCaption = "";
        string dir = Application.dataPath + "/../Logs/clip";
        if (System.IO.Directory.Exists(dir)) System.IO.Directory.Delete(dir, true);
        System.IO.Directory.CreateDirectory(dir);
        testStart = EditorApplication.timeSinceStartup;
        clipLastGameFrame = -1;
        EditorApplication.update += ChangesTick;
        EditorApplication.EnterPlaymode();
    }
    static void ChNext(int seg) { chSeg = seg; chSegFrame = chFrame; }
    static void ChangesFinish(int code)
    {
        EditorApplication.update -= ChangesTick;
        Time.captureFramerate = 0;
        PauseMenu.Quality = chQ0; PauseMenu.ShowFps = chFps0; PauseMenu.SavePrefs();
        if (chView0 >= 0) GameViewSelect(chView0);
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }
    static void ChangesTick()
    {
        if (EditorApplication.timeSinceStartup - testStart > 600) { Debug.LogError("BULLDOZER_CHANGES_FAILED timed out in " + chSeg); ChangesFinish(1); return; }
        if (!EditorApplication.isPlaying) return;
        var d = UnityEngine.Object.FindFirstObjectByType<DozerController>();
        var cam = Camera.main; var w = VoxelWorld.Instance; var wk = Worker.Instance;
        var pm = PauseMenu.Instance; var up = Upgrades.Instance; var money = Money.Instance;
        if (d == null || cam == null || w == null || wk == null || pm == null || up == null || money == null || d.Blade == null) return;
        if (Time.frameCount == clipLastGameFrame) return;
        clipLastGameFrame = Time.frameCount;
        var follow = cam.GetComponent<FollowCamera>();
        if (chEnd > 0) { if (--chEnd == 0) { WriteOverlay(); Debug.Log("BULLDOZER_CHANGES_OK frames=" + chFrame); ChangesFinish(0); } return; }
        if (chSeg == -1)
        {
            if (Time.realtimeSinceStartup < 3f || Time.timeSinceLevelLoad < 2f) return;
            chView0 = GameViewIndex();
            GameViewSize(1920, 1080);
            chQ0 = PauseMenu.Quality; chFps0 = PauseMenu.ShowFps;
            PauseMenu.Quality = 3; PauseMenu.ShowFps = false; pm.ApplyGraphics();      // (filming makes the fps read low, so it's off)
            wk.useOverride = true; d.dead = false;
            if (!wk.InDozer) wk.GetIn();
            d.useOverride = true;
            chStart = d.transform.position;
            d.Place(chStart, 0f);
            Time.captureFramerate = 30;
            ChNext(0);
            return;
        }
        float k = (chFrame - chSegFrame) / 30f;
        string title = "", cap = "";
        if (chSeg == 0)
        {
            // straight push: blade down, full throttle
            d.overrideBlade = k < 1.2f ? -1f : 0f; d.overrideAngle = 0f; d.overrideSteer = 0f;
            d.overrideThrottle = k < 1.2f ? 0f : 1f;
            if (follow != null) { follow.yawOffset = Mathf.Lerp(30f, 60f, k / 11f); follow.distance = 11f; follow.pitch = 22f; }
            title = "Faster and stronger, but it feels the load";
            cap = k < 5.5f ? "Top speed up from 3.0 to 3.7 m/s, and the blade lifts higher"
                           : "Slows as the heap grows:  heap " + d.BladeLoadM3.ToString("F1") + " m\u00b3,  speed " + d.Speed.ToString("F1") + " m/s";
            if (k > 11f) ChNext(1);
        }
        else if (chSeg == 1)
        {
            // keep pushing, from in front: a straight blade fills edge to edge
            d.overrideThrottle = 0.6f; d.overrideBlade = 0f;
            Vector3 bp = d.Blade.position, f = d.transform.forward;
            Vector3 cp = bp + f * 6f + Vector3.up * 2.4f + d.transform.right * 1.2f;
            if (follow != null) follow.enabled = false;
            cam.transform.SetPositionAndRotation(cp, Quaternion.LookRotation((bp + Vector3.up * 0.3f) - cp));
            title = "The blade fills";
            cap = "Blade straight:  the dirt fills it edge to edge, and stays in front";
            if (k > 6f) { if (follow != null) follow.enabled = true; ChNext(2); }
        }
        else if (chSeg == 2)
        {
            // swing it: the warning
            d.overrideThrottle = 0.6f;
            d.overrideAngle = k < 1.2f ? 1f : (k > 5.5f && k < 6.7f) ? -1f : 0f;     // swing it, then back straight
            if (follow != null) { follow.yawOffset = 20f; follow.distance = 10f; follow.pitch = 26f; }
            title = "Blade swung warning";
            cap = k < 5.5f ? "Swing the blade and it tells you:  the dirt rolls off one end" : "X straightens it again";
            if (k > 8f) { d.overrideThrottle = 0f; ChNext(3); }
        }
        else if (chSeg == 3)
        {
            // up the ramp with the blade up
            if (k < 0.05f)
            {
                d.Place(new Vector3(VoxelWorld.TrackCentreX(1f), 0f, 1f), 0f);
                d.overrideAngle = 0f;
            }
            d.overrideBlade = 1f; d.overrideRipper = 1f;
            d.overrideThrottle = k < 1f ? 0f : 1f;
            float want = VoxelWorld.TrackCentreX(d.transform.position.z + 3f) - d.transform.position.x;
            d.overrideSteer = Mathf.Clamp(want * 0.6f, -1f, 1f);
            if (follow != null) { follow.yawOffset = 95f; follow.distance = 11f; follow.pitch = 12f; }
            title = "Blade up clears the hill";
            cap = "It lifts higher now (26 degrees), so going up a steep bit it doesn't scrape the ground away";
            if (k > 10f) { d.overrideThrottle = 0f; ChNext(4); }
        }
        else if (chSeg == 4)
        {
            // the auto blade on Flat
            if (k < 0.05f)
            {
                d.Place(chStart + new Vector3(8f, 0f, 0f), 0f);
                d.overrideBlade = 0f; d.overrideRipper = 0f; d.overrideSteer = 0f; d.overrideThrottle = 0f;
                d.bladeAuto = DozerController.BladeAutoMode.Off; d.CycleBladeAuto();
            }
            d.overrideBlade = 0f; d.overrideSteer = 0f;
            d.overrideThrottle = k < 1.5f ? 0f : 1f;
            if (follow != null) { follow.yawOffset = 70f; follow.distance = 10f; follow.pitch = 18f; }
            title = "Auto blade:  B on the keyboard, A on the pad";
            cap = "On and off; while on, blade up / down set the height it holds, 5 cm a tap.  Here on " + d.BladeAutoName;
            if (k > 10f) { d.overrideThrottle = 0f; d.bladeAuto = DozerController.BladeAutoMode.Off; ChNext(5); }
        }
        else if (chSeg == 5)
        {
            // the Esc menu, then settings
            if (k < 0.05f) pm.SetOpen(true);
            if (k > 4f && k < 4.05f) pm.ShowSettings();
            title = k < 4f ? "Esc menu" : "Settings";
            cap = k < 4f ? "Resume, Settings, New game, Quit.  It autosaves every 5 minutes and when you quit"
                         : "Ultra graphics (this video is on Ultra), fps counter (F11), UI size, view distance";
            if (k > 9f) { pm.SetOpen(false); ChNext(6); }
        }
        else if (chSeg == 6)
        {
            // the upgrade tree
            if (k < 0.05f)
            {
                if (wk.InDozer) wk.GetOut();
                wk.useOverride = false;
                up.Reset(); money.Clear(); money.TestGrant(1500, 0);
            }
            if (k > 0.5f && !up.Open && k < 1f) up.SetOpen(true);
            if (k > 2.5f && k < 2.55f) up.MoveSelection(0, 1);
            if (k > 4f && k < 4.05f) up.MoveSelection(1, 0);
            if (k > 5.5f && k < 5.55f) up.MoveSelection(-1, 0);
            if (k > 6.5f && k < 6.55f) up.BuySelected();
            title = "The upgrade tree";
            cap = "Bigger, and laid out as a tree.  Arrows / d-pad to move, Enter / A to buy";
            if (k > 9.5f) { up.SetOpen(false); chEnd = 3; return; }
        }
        float a0 = chFrame / 30f, b0 = (chFrame + 1) / 30f;
        string at = AssTime(a0) + "," + AssTime(b0);
        if (title.Length > 0) sOverlay.Add("Dialogue: 0," + at + ",Title,,0,0,0,," + AssEsc(title));
        if (cap.Length > 0) sOverlay.Add("Dialogue: 0," + at + ",Caption,,0,0,0,," + AssEsc(cap));
        ScreenCapture.CaptureScreenshot(Application.dataPath + "/../Logs/clip/frame_" + chFrame.ToString("D4") + ".png");
        chFrame++;
    }

    static void TestFinish(int code)
    {
        EditorApplication.update -= TestTick;
        EditorSettings.enterPlayModeOptionsEnabled = false;
        EditorApplication.Exit(code);
    }

